-- ============================================================
-- Core/Logic.lua
-- Чистая бизнес-логика заклинаний и отдыха.
-- НЕ обращается к UI или Network напрямую —
-- вместо этого генерирует события через SB.Events.
-- ============================================================
local addonName, SB = ...
SB.Logic = SB.Logic or {}

-- Цель, зафиксированная в момент нажатия «Каст».
-- Хранится до момента формирования эмоута (включая форсированный).
local pendingTargetName     = ""
local pendingTargetGender   = 1
-- Был ли в цели ДРУЖЕСТВЕННЫЙ ИГРОК (а не НПС, не враг и не пусто).
-- Нужно для spell.buff: эффект на союзника можно отправить только живому
-- клиенту, и только тому, кому мы вообще можем помогать — иначе «Щит»
-- уходил бы вражескому игроку, если тот случайно оказался в таргете.
local pendingTargetIsAlly = false

-- ЯВНОЕ «НА СЕБЯ». Ставится ConfirmCast из opts.onSelf и живёт ровно
-- столько же, сколько pendingTargetName: до эмоута, до ответа Ведущего.
--
-- Значит он не «предпочтительно на себя», а «ЦЕЛИ НЕТ ВОВСЕ». Игрок
-- выбрал пункт «Применить на себя», и всё, что было в таргете, к этому
-- касту отношения не имеет — ни как получатель, ни как повод отказать по
-- дальности или видимости.
local pendingSelfCast = false

-- ============================================================
-- ПРЕДМЕТ — БОНУСНОЕ ДЕЙСТВИЕ
--
-- Флаг ставится в ConfirmCast и гасится в SpendTurn: между ними лежит
-- весь резолв, а SpendTurn зовут ПЯТЬ разных путей (ПвЕ-бросок, ПвП,
-- площадь, эффект, удар по существу). Проводить признак через все пять
-- параметром значило бы пять раз одно и то же — и один раз забыть.
--
-- Живёт он ровно от нажатия до конца резолва: SpendTurn его снимает
-- сразу, как только увидит.
local pendingBonusAction = false

--- Считается ли применение этого заклинания бонусным действием.
--- Предмет и только предмет, и только в свой ход пошагового режима
--- (см. TO.CanUseBonus).
function SB.Logic.IsBonusAction(spell)
    if not (SB.Items and SB.Items.IsItem and SB.Items.IsItem(spell)) then
        return false
    end
    return (SB.TurnOrder and SB.TurnOrder.CanUseBonus
            and SB.TurnOrder.CanUseBonus()) or false
end

-- ============================================================
-- СКЛЯНКА БЕЗ ЦЕЛИ — ВЫПИТА САМИМ
--
-- У заклинания промах мимо цели — это ошибка: «Могущество» с дальностью
-- 2.5 м не про себя, и молча превращать его в самобафф нельзя (см.
-- врезку в GetTargetedEffect). У ПРЕДМЕТА ровно наоборот: склянка уже в
-- руке. По умолчанию её выпивают сами, а чтобы напоить соседа, его надо
-- выбрать целью И выбрать это в меню — то есть сделать два движения, а
-- не забыть одно.
--
-- Дальность у зелья не «докуда добьёт», а «надо стоять рядом»: она
-- описывает случай, когда поят другого, и потому не может служить
-- доводом против того, чтобы выпить самому.
--
-- Правило одно на обе половины развилки — GetTargetedEffect (касты,
-- которые аддон разрешает сам) и ApplyBuffToTarget (те, что вернулись от
-- Ведущего или прошли без сопротивления), — поэтому и записано один раз.
-- @param hasTarget boolean  есть ли получатель, кроме самого игрока
local function ItemStaysOnCaster(spell, hasTarget)
    if not (SB.Items and SB.Items.IsItem and SB.Items.IsItem(spell)) then
        return false
    end
    return pendingSelfCast or not hasTarget
end

-- ============================================================
-- РЕЕСТР ИСТОЧНИКОВ МОДИФИКАТОРА БРОСКА (расширяемо)
-- Любой источник (мастерство, уровень, будущие баффы/дебаффы,
-- эффекты предметов и т.д.) регистрируется здесь через
-- SB.Logic.RegisterModifierSource. Итоговый модификатор броска —
-- сумма источников, ПОДХОДЯЩИХ ПОД ОБЛАСТЬ броска. UI (тултип в
-- главном окне) строится по этому же реестру, так что новый
-- источник появится в тултипе автоматически, без правок UI.
--
-- ОБЛАСТИ (scope):
--   "attack"  — только броски атаки/каста/лечения
--   "defense" — только броски защиты (ПвП-уворот)
--   "both"    — и то, и другое
--
-- Зачем разделение: раньше защита считалась тем же
-- GetModifierBreakdown(), что и атака, из-за чего ранг заклинателя
-- (Мастерство) непрошено усиливал ЗАЩИТУ. Теперь каждый источник знает
-- свою область, и всё, что влияет на бросок, видно в разбивке тултипа.
-- ============================================================
SB.Logic.ModifierSources = SB.Logic.ModifierSources or {}

--- Регистрирует источник модификатора броска.
--- @param key    string    Уникальный ключ источника (для перезаписи/отладки)
--- @param label  string    Человекочитаемое имя для тултипа
--- @param fn     function  fn(ctx) -> число. ctx может содержать
---        { spell = ..., slotLevel = ..., versus = "<имя второй стороны>" }.
---        versus читает только провокация (см. её источник ниже): всем
---        прочим безразлично, по кому идёт бросок.
--- @param scope  string|nil "attack" | "defense" | "both" (по умолчанию "both")
function SB.Logic.RegisterModifierSource(key, label, fn, scope)
    SB.Logic.ModifierSources[key] = {
        label = label,
        fn    = fn,
        scope = scope or "both",
    }
end

function SB.Logic.GetResourceBarColor(className)
    if SB.Data.NonCasterClasses and SB.Data.NonCasterClasses[className] then
        local token = SB.Data.ClassColorTokens and SB.Data.ClassColorTokens[className]
        local c = token and RAID_CLASS_COLORS and RAID_CLASS_COLORS[token]
        if c then return c.r, c.g, c.b end
    end
    return 0.20, 0.48, 0.88  -- стандартный синий "мана" (как у кастеров)
end

--- Имя ресурса каста для произвольного класса (не обязательно своего —
--- нужно ГМу для панели выдачи ресурсов другому игроку). Мана для
--- кастеров, собственный ресурс (см. SB.Data.ClassResourceNames) —
--- для некастеров.
---
--- ВНИМАНИЕ: внутри кода и в сетевом протоколе ресурс кастеров
--- по-прежнему называется zeal/maxZeal. Переименованы только
--- отображаемые строки: менять имена полей в пакетах STATUS означало бы
--- рассинхрон с игроками на старой версии аддона. Не путать также с
--- НАВЫКОМ «Рвение» (ветка Духа) — это разные сущности, и как раз
--- поэтому ресурс теперь зовётся Маной.
function SB.Logic.GetResourceName(className)
    if SB.Data.NonCasterClasses and SB.Data.NonCasterClasses[className] then
        return (SB.Data.ClassResourceNames and SB.Data.ClassResourceNames[className]) or "Энергия"
    end
    return "Мана"
end

--- Название заклинания нулевого порядка ("Заговор" у кастеров,
--- "Приём" у некастеров) для произвольного класса. plural=true даёт
--- множественное число ("Заговоры"/"Приёмы") для заголовков-группировок.
function SB.Logic.GetCantripLabel(className, plural)
    local isNonCaster = SB.Data.NonCasterClasses and SB.Data.NonCasterClasses[className]
    if plural then
        return isNonCaster and "Приёмы" or "Заговоры"
    end
    return isNonCaster and "Приём" or "Заговор"
end


--- Возвращает (total, parts): суммарный модификатор и разбивку по
--- источникам (список { label = string, value = number }), уже
--- отсортированную и без нулевых источников (не засорять тултип).
--- @param scope string|nil "attack" (по умолчанию) | "defense"
--- @param ctx   table|nil  Контекст броска, например { spell = spell }.
---                          Источники, зависящие от заклинания (напр.
---                          «Внушение»), читают его отсюда.
function SB.Logic.GetModifierBreakdown(scope, ctx)
    scope = scope or "attack"
    local total = 0
    local parts = {}
    for key, src in pairs(SB.Logic.ModifierSources) do
        if src.scope == "both" or src.scope == scope then
            local ok, val = pcall(src.fn, ctx)
            val = ok and (tonumber(val) or 0) or 0
            total = total + val
            if val ~= 0 then
                table.insert(parts, { key = key, label = src.label, value = val })
            end
        end
    end
    table.sort(parts, function(a, b) return a.label < b.label end)
    return total, parts
end

-- ── Встроенные источники ────────────────────────────────────

-- Мастерство — ранг ЗАКЛИНАТЕЛЯ, поэтому только атака: то, насколько
-- ты силён в магии, не должно помогать уворачиваться.
--
-- ТОЛЬКО ДЛЯ ЗАКЛИНАНИЙ СВОЕГО КЛАССА. Ранг — это глубина владения
-- СВОЕЙ школой, и на чужую он не переносится: Воин, взявший из
-- библиотеки заклинание Мага, применяет его как любитель. Раньше ранг
-- прибавлялся ко всему подряд, и «нахватать» чужих заклинаний было
-- выгоднее, чем углубляться в свои.
--
-- Заклинание БЕЗ класса считается своим — по той же причине, что и в
-- SB.Data.IsCasterSpell: у кастомных заклинаний Ведущего класс может
-- быть не задан, и молча срезать им ранг было бы неожиданно.
-- Контекста нет вовсе (бейдж модификатора в главном окне, где
-- заклинание ещё не выбрано) — тоже считаем своим, иначе бейдж
-- показывал бы число ниже того, что игрок увидит в большинстве кастов.
-- РАНГ БЕРЁТСЯ У ШКОЛЫ ЗАКЛИНАНИЯ, А НЕ У ГЕРОЯ.
--
-- Раньше здесь стояла развилка «своё заклинание — полный ранг, чужое —
-- ноль». Она была верна, пока ранг был один на персонажа. Теперь ранг
-- принадлежит школе (см. врезку о мультиклассе в Core/PlayerModel.lua),
-- и жрец-эксперт с магической вещью адепта обязан получать +8 на
-- жреческое и +5 на магическое — а не +8 на всё и ноль на второе.
--
-- Заклинание БЕЗ класса идёт по рангу героя: у кастомных заклинаний
-- Ведущего класс может быть не задан, и молча срезать им ранг было бы
-- неожиданно.
--
-- А ВОТ БЕЗ КОНТЕКСТА ВООБЩЕ — НОЛЬ, и это перемена. Раньше бейдж
-- модификатора в шапке (где заклинание ещё не выбрано) показывал ранг
-- родной школы, «чтобы не занижать». Вышло наоборот: с тех пор как ранг
-- разъехался по школам, это число верно ровно для одной из них и врёт
-- про все остальные — жрец-эксперт видел в шапке +8 и получал +5 на
-- магическое заклинание, не понимая, куда делись три.
--
-- Бейдж теперь показывает только то, что не зависит от выбора: класс,
-- уровень, висящие эффекты. Ранг школы приписан к тем же условным
-- слагаемым, что скейлинг и «Внушение», — «добавляется в момент каста»
-- (см. подсказку бейджа в UI/MainFrame.lua).
SB.Logic.RegisterModifierSource("mastery", "Мастерство школы", function(ctx)
    local PM    = SB.PlayerModel
    local spell = ctx and ctx.spell
    local cls   = spell and spell.class

    -- Заклинание не выбрано — прибавка неизвестна. Не «полная», не
    -- «средняя»: неизвестна.
    if not spell then return 0 end

    local rank
    if not cls or cls == "" or cls == "Эффект" then
        rank = PM.GetMastery()
    else
        -- Школа закрыта — ранга в ней нет, и прибавки тоже.
        rank = PM.GetClassRank(cls)
    end
    return (rank and SB.Data.Config.Modifiers[rank]) or 0
end, "attack")

-- Уровень персонажа — общая опытность, работает в обе стороны.
SB.Logic.RegisterModifierSource("level", "Уровень персонажа", function()
    return SB.PlayerModel.GetLevelModifier()
end, "both")

-- Профиль класса (см. SB.Data.ClassProfiles) — то, чем классы
-- отличаются друг от друга помимо механики ресурса. Два отдельных
-- источника, а не один: атака и защита сдвигаются на РАЗНЫЕ величины
-- (у Мага +4/−4), и одним источником со scope="both" это не выразить.
-- Регистрация в общем реестре означает, что сдвиг автоматически виден
-- в разбивке обоих бейджей в шапке — без правок UI.
SB.Logic.RegisterModifierSource("classAtk", "Класс", function()
    return SB.Data.GetClassProfile().attack or 0
end, "attack")

SB.Logic.RegisterModifierSource("classDef", "Класс", function()
    return SB.Data.GetClassProfile().defense or 0
end, "defense")

-- Вложенный сверх стоимости ресурс — прибавка к попаданию у приёмов
-- некастерских классов (см. SB.Logic.GetCastPower). Нужен ctx.spell и
-- ctx.slotLevel.
--
-- Раньше эта прибавка вписывалась в разбивку вручную, тремя копиями в
-- трёх функциях, с ключом "resource", которого нет в реестре, — и в
-- разбивке вылезала сырая английская строка «resource». Теперь источник
-- обычный, подпись берётся отсюда, а разбивка собирается сама и видна
-- на бейджах в шапке.
-- Баффы и дебаффы, висящие на персонаже (см. Core/ActiveEffects.lua).
-- Как и профиль класса — два источника, потому что эффект может
-- сдвигать атаку и защиту на разные величины (например «Каменная кожа»:
-- +защита, −атака). Через реестр — значит сдвиг сам виден в разбивке
-- бейджей, ровно как модификаторы способностей.
SB.Logic.RegisterModifierSource("effAtk", "Эффекты", function()
    if not SB.ActiveEffects or not SB.ActiveEffects.GetMod then return 0 end
    return (SB.ActiveEffects.GetMod("attack"))
end, "attack")

SB.Logic.RegisterModifierSource("effDef", "Эффекты", function()
    if not SB.ActiveEffects or not SB.ActiveEffects.GetMod then return 0 end
    return (SB.ActiveEffects.GetMod("defense"))
end, "defense")

-- Оружие в руках (см. SB.Data.WeaponBonuses): топор — к атаке, меч — к
-- защите. Тоже два источника, по той же причине, что у эффектов, и тоже
-- через реестр — прибавка сама видна в разбивке бейджей.
SB.Logic.RegisterModifierSource("weaponAtk", "Оружие", function()
    return SB.Skills and SB.Skills.GetWeaponBonus
       and (SB.Skills.GetWeaponBonus("attack")) or 0
end, "attack")

SB.Logic.RegisterModifierSource("weaponDef", "Оружие", function()
    return SB.Skills and SB.Skills.GetWeaponBonus
       and (SB.Skills.GetWeaponBonus("defense")) or 0
end, "defense")

--- Наибольшая прибавка оружия в канале — у кого угодно: складывающийся
--- вид в обеих руках, нескладывающийся — один раз. Для сверки чужих
--- бросков: точного оружия атакующего мы не знаем.
function SB.Logic.MaxWeaponBonus(channel)
    local out = 0
    for _, def in pairs(SB.Data.WeaponBonuses or {}) do
        if def.channel == channel then
            local v = (tonumber(def.value) or 0) * (def.stacks and 2 or 1)
            if v > 0 then out = out + v end
        end
    end
    return out
end

-- ПРОВОКАЦИЯ — единственный источник в реестре, который зависит от
-- ТОГО, ПО КОМУ идёт бросок (ctx.versus). Остальные считают персонажа
-- самого по себе, и это не случайность: условный модификатор пришлось
-- бы объяснять в каждой подсказке заново. Здесь без него нельзя —
-- в условии вся механика (см. врезку «ПРОВОКАЦИЯ» в
-- Core/ActiveEffects.lua).
--
-- "both": провокация мешает и бить, и уворачиваться. Второе не
-- натяжка — приковано ВНИМАНИЕ, а не рука: тот, кто не сводит глаз с
-- обидчика, хуже видит удар сбоку.
--
-- НЕТ ctx.versus — ЗНАЧИТ ШТРАФ ЕСТЬ. Броски без второй стороны в
-- аддоне бывают (ручная атака по просьбе Ведущего, площадной залп,
-- защита вне размена), и «не назвали цель» не повод отменять эффект.
-- Зато штраф виден в разбивке бейджа отдельной строкой, так что за
-- столом с ним всегда можно договориться.
SB.Logic.RegisterModifierSource("taunt", "Провокация", function(ctx)
    if not (SB.ActiveEffects and SB.ActiveEffects.GetTauntPenalty) then return 0 end
    return (SB.ActiveEffects.GetTauntPenalty(ctx and ctx.versus))
end, "both")

SB.Logic.RegisterModifierSource("resource", "Вложенный ресурс", function(ctx)
    if not ctx or not ctx.spell then return 0 end
    local _, hitBonus = SB.Logic.GetCastPower(ctx.spell, ctx.slotLevel)
    return hitBonus
end, "attack")

-- Автоматической прибавки к защите от Ловкости здесь НЕТ намеренно.
-- Раньше источник "dodge" давал её каждому персонажу просто за очки в
-- характеристике — то есть защита росла сама, без вложений игрока. Теперь
-- уклонение зависит только от того, что игрок развивал осознанно:
-- Акробатика (навык) и висящие эффекты. Ловкость по-прежнему работает
-- через скейлинг заклинаний и через свои навыки.

-- Акробатика — ловкий уход от удара. Заменила здесь «Ношение брони»:
-- броня больше не помогает УКЛОНИТЬСЯ, она гасит уже прошедший урон
-- (см. SB.Skills.GetDamageReduction в HandlePvpAttackReceived).
SB.Logic.RegisterModifierSource("acrobatics", "Акробатика", function()
    return SB.Skills and SB.Skills.GetAcrobaticsDefenseBonus
       and SB.Skills.GetAcrobaticsDefenseBonus() or 0
end, "defense")

-- Концентрация — только пока реально поддерживаешь эффект.
SB.Logic.RegisterModifierSource("concentration", "Концентрация", function()
    return SB.Skills and SB.Skills.GetConcentrationDefenseBonus
       and SB.Skills.GetConcentrationDefenseBonus() or 0
end, "defense")

-- Внушение — только для заклинаний, не наносящих урон (нужен ctx.spell).
SB.Logic.RegisterModifierSource("persuasion", "Внушение", function(ctx)
    if not ctx or not ctx.spell then return 0 end
    return SB.Skills and SB.Skills.GetPersuasionBonus and SB.Skills.GetPersuasionBonus(ctx.spell) or 0
end, "attack")

-- Милосердие — только для лечащих заклинаний (нужен ctx.spell).
-- Через реестр, а не отдельным слагаемым в ResolveHeal: так прибавка
-- сразу видна в разбивке модификатора у обеих сторон, и её не надо
-- дописывать руками в каждое сообщение.
SB.Logic.RegisterModifierSource("mercy", "Милосердие", function(ctx)
    if not ctx or not ctx.spell then return 0 end
    return SB.Skills and SB.Skills.GetMercyHealBonus and SB.Skills.GetMercyHealBonus(ctx.spell) or 0
end, "attack")

-- ============================================================
-- СКЕЙЛИНГ ЗАКЛИНАНИЯ ОТ ХАРАКТЕРИСТИК
--
-- У заклинания три канала: hit (попадание), crit (шанс крита) и
-- damage (урон/исцеление). К каждому можно привязать ЛЮБОЕ число
-- атрибутов И навыков со своим коэффициентом, в том числе
-- отрицательным.
--
--   scaling = {
--       hit    = { ["Рвение"] = 1 },                  -- навык
--       crit   = { ["Концентрация"] = 1 },
--       damage = { ["Дух"] = 1.5, ["Сила"] = -0.5 },  -- дробные и минус
--   }
--
-- Коэффициент умножается на «очки сверх минимума» характеристики и на
-- цену очка канала (Config.ScalingPerPoint). Атрибуты и навыки
-- взаимозаменяемы: SB.Attributes.Get полиморфен и принимает оба.
--
-- СТАРЫЙ ФОРМАТ ПОДДЕРЖИВАЕТСЯ: attributes = { hit = "Дух" } — это
-- ровно то же самое, что scaling = { hit = { ["Дух"] = 1 } }. Если у
-- заклинания заданы оба, по каждому каналу выигрывает scaling.
-- ============================================================

--- Округление к нулю: и +1.5, и -1.5 дают модуль 1. Обычный floor
--- делал бы штраф (-1.5 → -2) жёстче бонуса (+1.5 → +1), из-за чего
--- отрицательный скейлинг бил бы сильнее, чем написано в заклинании.
local function TruncTowardZero(x)
    if x >= 0 then return math.floor(x) end
    return math.ceil(x)
end

--- Во сколько раз вложенный ресурс усиливает канал damage у
--- КАСТЕРСКОГО заклинания. У некастерского вложенный ресурс уходит
--- в точность, а не в силу (см. GetCastPower), и множитель к нему не
--- применяется — проверку делает сам GetSpellScaling.
---
--- Раньше вложенная мана добавляла к урону ПЛОСКУЮ единицу за штуку
--- (Config.DamagePerMana), одинаково всем. Из-за этого мана была
--- сильнее характеристик: три единицы давали +3, а полностью вложенный
--- Интеллект — только +2, и вкладываться в характеристику было
--- невыгодно. Теперь мана не добавляет урон сама, а УСИЛИВАЕТ то, что
--- игрок уже развил: +50% к скейлингу канала за каждую вложенную
--- единицу (Config.DamageScalePerMana).
---
--- Считается от ПОЛНОГО объёма вложенного, а не от избытка над кругом
--- заклинания. От избытка получалось бы, что заклинание 3-го круга,
--- применённое 3-м кругом, не получает НИЧЕГО, а заговор, поднятый до
--- 3-го, бьёт сильнее его же — круг переставал что-либо значить. Ровно
--- эту ошибку уже чинили у прибавки к попаданию, см. GetCastPower.
---
--- Множитель применяется ДО усечения дроби: иначе скейлинг сначала
--- обнулялся бы у характеристик 2 и 4 (по 0.5 за очко), и умножать
--- было бы уже нечего.
--- @return number
function SB.Logic.GetDamageScaleMultiplier(slotLevel)
    local slot = math.max(0, math.floor(tonumber(slotLevel) or 0))
    if slot == 0 then return 1 end
    return 1 + slot * (SB.Data.Config.DamageScalePerMana or 0)
end

-- ============================================================
-- ДАЁТ ЛИ ВЛИВАНИЕ РЕСУРСА ХОТЬ ЧТО-НИБУДЬ
--
-- Окно выбора круга предлагало влить ресурс В ЛЮБОЕ заклинание, включая
-- те, где от этого не меняется ровно ничего. Хуже всего это выглядело на
-- бессрочных стойках и обликах: игрок видел «Мана x 3» над «Боевой
-- стойкой», выбирал, платил — и получал ту же самую бесконечную стойку.
-- Предложенный выбор, который ничего не решает, читается как поломка.
--
-- ЧТО РЕАЛЬНО ЗАВИСИТ ОТ ВЛОЖЕННОГО — ровно три вещи, и все выведены не
-- из замысла, а из арифметики резолва:
--
--   • МНОЖИТЕЛЬ СКЕЙЛИНГА канала damage (GetDamageScaleMultiplier выше).
--     Работает, только если у заклинания этот канал вообще есть;
--   • РАСТЯЖЕНИЕ СРОКА эффекта (GetUpcastMultiplier ниже). Работает,
--     только если эффект есть и срок у него КОНЕЧНЫЙ: «до конца сцены»
--     вдвое — это всё та же «до конца сцены»;
--   • ЧИСЛО СНИМАЕМЫХ ЭФФЕКТОВ у рассеивания (GetDispelCount). Каждая
--     единица сверх круга снимает ещё один эффект — там вложенное и есть
--     вся цена, броска у рассеивания нет вовсе.
--
-- ТРЕТЬЮ Я СНАЧАЛА ПРОПУСТИЛ, и правило вышло строже, чем арифметика:
-- «Снятие проклятья» и «Устранение яда» переставали предлагать вливание,
-- хотя от него у них зависит главное. Поэтому ниже, в Tests/run.lua,
-- стоит проверка, которая сверяет это правило не со списком заклинаний, а
-- с ФАКТИЧЕСКИМИ числами: считает каст на своём круге и на круге выше и
-- требует, чтобы CanUpcast согласился с тем, изменилось ли хоть что-то.
-- Появится четвёртый рычаг — проверка укажет на него сама.
--
-- ЧЕГО ЗДЕСЬ НЕТ И НЕ ДОЛЖНО БЫТЬ: починка доспеха. Канал "armor"
-- множителем не трогается (см. GetSpellScaling — множитель только у
-- damage), так что от вливания она не растёт.
--
-- ПОЧЕМУ НЕ ПО canCrit И НЕ ПО isHeal, хотя так и просится. База урона и
-- база лечения от вложенного НЕ РАСТУТ: обе считаются как
-- «база + slot * DamagePerMana», а DamagePerMana давно ноль — мана
-- перестала прибавлять урон сама и стала множить уже развитое (см.
-- врезку у DamageScalePerMana). Уронное заклинание без канала damage
-- получает от вливания ровно ноль, и предлагать его игроку не за что.
--
-- Заклинаний, которым вливание не даёт ничего, в библиотеке 72.
-- ============================================================

--- Что получится у ЭТОГО персонажа, если влить столько. Пять чисел, по
--- одному на каждый рычаг; строкой — сравнивать проще, чем пятёрками.
local function UpcastSnapshot(spell, lvl)
    local eff = spell.container or spell.buff or spell.debuff
    return table.concat({
        SB.Logic.GetSpellScaling(spell, "damage", lvl),
        eff and SB.Logic.GetEffectDuration(eff, spell, lvl) or 0,
        SB.Logic.GetDispelSchools(spell) and SB.Logic.GetDispelCount(spell, lvl) or 0,
        SB.Logic.GetSpellRepair(spell, lvl),
        (spell.isHeal and SB.Logic.GetHealPower or SB.Logic.GetCastPower)(spell, lvl),
    }, "/")
end

--- @return boolean  true — вливать сверх своего круга имеет смысл
---
--- СПРАШИВАЕМ АРИФМЕТИКУ, А НЕ ПРИЗНАКИ ЗАКЛИНАНИЯ.
---
--- Сперва здесь стояло рассуждение о структуре: «есть канал damage —
--- значит поможет». Оно врало в обе стороны. Пропустило рассеивание (там
--- вложенное — вся цена) и обещало прибавку «Засаде»: круг у неё второй,
--- потолок реалма третий, коэффициент 1.2, — и единственный доступный
--- шаг не меняет урон НИ ПРИ КАКОЙ Ловкости, потому что дробь усекается.
---
--- Множитель растёт на 0.15 за круг, а числа целые. Угадать по признакам,
--- переползёт ли произведение через единицу, нельзя — можно только
--- посчитать. Поэтому считаем: что выйдет на своём круге и что выйдет на
--- каждом доступном выше.
---
--- ОТ ТЕКУЩЕГО ПЕРСОНАЖА, а не «вообще»: у одного Сила 3, и вливание ему
--- даёт, у другого Сила 5 — и не даёт. Окно выбора круга открыто
--- КОНКРЕТНЫМ игроком, и честный ответ там — про него.
---
--- Обещать то, чего резолв не даст, эта функция теперь не может в
--- принципе: она зовёт те же функции, что и он.
function SB.Logic.CanUpcast(spell)
    if type(spell) ~= "table" then return false end

    local own = math.max(0, tonumber(spell.level) or 0)
    local top = (SB.Data.GetRealmMaxOrder and SB.Data.GetRealmMaxOrder()) or own
    if top <= own then return false end   -- вливать некуда: круг один

    local base = UpcastSnapshot(spell, own)
    for lvl = own + 1, top do
        if UpcastSnapshot(spell, lvl) ~= base then return true end
    end
    return false
end

--- @param spell   table   Заклинание
--- @param channel string  "hit" | "crit" | "damage"
--- @param slotLevel number|nil  сколько ресурса вложено в каст. Влияет
---        ТОЛЬКО на канал damage (см. GetDamageScaleMultiplier); для
---        hit/crit игнорируется — вложенный ресурс работает там своим
---        источником реестра "resource" и только у некастеров.
--- @return number total, table parts  parts = { {key,label,value}, ... }
--- @param statFn function|nil  чем мерить характеристику. По умолчанию —
---        характеристики ИГРОКА. Существо считает свой скейлинг тем же
---        кодом, подставляя сюда собственные цифры (см.
---        SB.NPC.AttackModifier): правила перевода очков в прибавку —
---        одни на всех, и вторая их копия для существ разъехалась бы с
---        первой на первой же правке баланса.
function SB.Logic.GetSpellScaling(spell, channel, slotLevel, statFn)
    if not spell then return 0, {} end

    local sources = spell.scaling and spell.scaling[channel]
    if sources == nil then
        sources = spell.attributes and spell.attributes[channel]
    end
    if sources == nil then return 0, {} end

    -- Строка — сокращение для коэффициента 1.
    if type(sources) == "string" then
        sources = { [sources] = 1 }
    elseif type(sources) ~= "table" then
        return 0, {}
    end

    local perPoint = (SB.Data.Config.ScalingPerPoint or {})[channel] or 0
    local total, parts = 0, {}

    -- Вложенный ресурс усиливает канал damage ЦЕЛИКОМ, а не каждый
    -- коэффициент по отдельности. Иначе заклинание с двумя статами в
    -- канале получало бы от маны вдвое больше, чем с одним, — то есть
    -- выгода от вливания зависела бы от того, сколько строк автор
    -- написал в таблице, а это оформление данных, а не решение
    -- дизайнера. Таких заклинаний в библиотеке 13.
    --
    -- У ВСЕХ ЗАКЛИНАНИЙ ОДИНАКОВО. Раньше здесь стояла проверка
    -- IsCasterSpell: кастер вкладывал ресурс в силу удара, некастер — в
    -- точность (+HitPerResource к броску). Развилку убрали вместе с
    -- HitPerResource (см. GetCastPower): пока она была, у половины
    -- библиотеки вложенный ресурс на урон не влиял вовсе, и сравнить
    -- классы по урону было нельзя в принципе.
    --
    -- Двойного бонуса, от которого защищала проверка, теперь не бывает:
    -- HitPerResource = 0, то есть точность от вливания не растёт ни у
    -- кого. Если будете возвращать её некастерам, верните и проверку —
    -- иначе они снова получат оба бонуса сразу.
    local mult = 1
    if channel == "damage" and slotLevel then
        mult = SB.Logic.GetDamageScaleMultiplier(slotLevel)
    end

    -- ── ДРОБИ СКЛАДЫВАЮТСЯ, А НЕ ТЕРЯЮТСЯ ПО ОДНОЙ ──────────
    --
    -- Здесь усекалось КАЖДОЕ слагаемое по отдельности, и ради чего —
    -- ради того, чтобы разбивка в тултипе сходилась с итогом. Цена
    -- оказалась велика: заклинание со скейлингом «0.5 Дух + 0.5 Характер»
    -- давало +1 только за пять очков в ОДНОЙ характеристике. Четыре
    -- Характера и два Духа — те же четыре очка сверх минимума, честная
    -- единица по формуле — превращались в 0.75 и 0.25, и обе доли
    -- отбрасывались порознь. Игрок вложил ровно столько же и не получил
    -- ничего; хуже того, узнать об этом можно было только опытом.
    --
    -- Теперь слагаемые копятся ТОЧНЫМИ, усекается один раз общий итог, а
    -- разбивка раскладывается уже по целому итогу — так она по-прежнему
    -- сходится с ним до единицы, но перестаёт врать о самой механике.
    local exact = {}
    for statKey, coeff in pairs(sources) do
        coeff = tonumber(coeff) or 0
        if coeff ~= 0 then
            -- Очки сверх минимума: характеристика со значением 1 не
            -- даёт ничего ни в плюс, ни в минус. GetEffective — чтобы
            -- бафф на характеристику усиливал и скейлинг заклинаний,
            -- а не только сами броски по ней.
            -- От общей базы (SB.Data.STAT_BASE), а не от голой единицы:
            -- здесь она была записана числом мимо констант, и смена базы
            -- прошла бы мимо скейлинга заклинаний целиком.
            local base   = SB.Data.STAT_BASE or 0
            local points = ((statFn or SB.Attributes.GetEffective)(statKey) or base) - base
            local raw = points * perPoint * coeff * mult
            if raw ~= 0 then
                exact[#exact + 1] = { key = statKey, label = statKey, raw = raw }
                total = total + raw
            end
        end
    end
    if #exact == 0 then return 0, {} end

    total = TruncTowardZero(total)

    -- ── КАК ЦЕЛЫЙ ИТОГ РАСКЛАДЫВАЕТСЯ ОБРАТНО ───────────────
    --
    -- Каждому — его целая часть, а остаток от усечения итога уходит тем,
    -- у кого БОЛЬШЕ ОТБРОШЕННАЯ ДОЛЯ. Способ известный (наибольший
    -- остаток), и важен он не точностью, а тем, что сумма подписей
    -- РАВНА показанному итогу при любых коэффициентах. Расхождение здесь
    -- читалось бы как ошибка счёта, даже когда счёт верен.
    local spare = total
    for _, e in ipairs(exact) do
        e.value = TruncTowardZero(e.raw)
        e.rest  = math.abs(e.raw - e.value)
        spare   = spare - e.value
    end

    if spare ~= 0 then
        -- Порядок раздачи — по убыванию отброшенной доли; при равных
        -- долях по имени, иначе pairs() делал бы результат случайным от
        -- запуска к запуску.
        local order = {}
        for i, e in ipairs(exact) do order[i] = e end
        table.sort(order, function(a, b)
            if a.rest ~= b.rest then return a.rest > b.rest end
            return a.key < b.key
        end)
        local step = (spare > 0) and 1 or -1
        for i = 1, math.abs(spare) do
            local e = order[((i - 1) % #order) + 1]
            e.value = e.value + step
        end
    end

    for _, e in ipairs(exact) do
        -- Нулевые слагаемые в подписи не идут: «Дух +0» — это шум, а не
        -- сведения. На итог это не влияет, он уже посчитан.
        if e.value ~= 0 then
            parts[#parts + 1] = { key = e.key, label = e.label, value = e.value }
        end
    end

    table.sort(parts, function(a, b) return a.label < b.label end)
    return total, parts
end

--- Минимальное значение НА КУБИКЕ, начиная с которого бросок считается
--- критическим. Сравнивать надо именно с кубиком, а не с итогом:
--- итог включает бонус за уровень (+30 на 25-м), и по нему крит
--- превращался бы в «каждый второй успех» у высокоуровневых и в
--- «никогда» у новичков. Подробности — Config.CritBand.
--- @param critBonus number  расширение полосы от скейлинга канала crit
--- @param rollMax   number|nil  верхняя грань кубика (по умолчанию 100)
function SB.Logic.GetCritThreshold(critBonus, rollMax)
    rollMax = tonumber(rollMax) or 100
    -- Активные эффекты тоже расширяют (или сужают) полосу крита —
    -- канал "crit" в их mods, см. Core/ActiveEffects.lua.
    local fromEffects = (SB.ActiveEffects and SB.ActiveEffects.GetMod)
        and (SB.ActiveEffects.GetMod("crit")) or 0
    local band = (SB.Data.Config.CritBand or 5) + (tonumber(critBonus) or 0) + fromEffects
    -- ПОТОЛОК ПОЛОСЫ — Config.CritBandMaxPct процентов кубика.
    --
    -- Раньше здесь стояла половина, и это было слишком щедро: базовая
    -- полоса — пятёрка, а один-единственный бафф давал +25 пунктов, то
    -- есть каждый третий удар. Два таких упирались в потолок, и крит
    -- переставал быть событием — становился режимом.
    local capPct = tonumber(SB.Data.Config.CritBandMaxPct) or 25
    -- ПОЛ — НОЛЬ, А НЕ ЕДИНИЦА. Единица стояла, пока база была пятёркой:
    -- она мешала дебаффу канала crit увести полосу в минус. С базой в
    -- ноль тот же пол молча стал бы НОВОЙ базой — «крита нет вовсе»
    -- превратилось бы в «крит на сотне у всех и даром», то есть ровно в
    -- то, что убирали (см. Config.CritBand). Пустая полоса даёт порог
    -- rollMax + 1, который не берёт ни один бросок, — и это честный
    -- ответ «не критует».
    band = math.max(0, math.min(band, math.floor(rollMax * capPct / 100)))
    return rollMax - band + 1
end

-- ============================================================
-- БАЗОВЫЙ УРОН И ВЛОЖЕННЫЙ РЕСУРС
--
-- Правило теперь ОДНО НА ВСЕХ, без развилки по классу заклинания:
-- вложенный ресурс усиливает СКЕЙЛИНГ канала damage, и считается это в
-- GetSpellScaling через GetDamageScaleMultiplier. Эта функция возвращает
-- только базу — множитель применяется к скейлингу, иначе одна и та же
-- прибавка вошла бы в расчёт дважды.
--
-- Раньше развилка была: кастер вливал в силу, некастер — в точность
-- (+HitPerResource к броску). Убрана по двум причинам. Во-первых, у
-- половины библиотеки ресурс не влиял на урон вовсе, и сравнивать классы
-- между собой было нельзя: одни считались по одной формуле, другие по
-- другой. Во-вторых, точность у некастеров и так росла быстрее всех —
-- профили класса дают им +2..+8 к атаке, — а вложение добавляло сверху
-- ещё до +9, и исход размена решало «влил или не влил».
--
-- БАЗА — ТОЛЬКО У ЗАГОВОРОВ (круг 0). У заклинаний первого круга и выше
-- весь урон складывается из скейлинга: базовая единица была там десятой
-- частью итога и только размывала вклад характеристик. У заговоров
-- наоборот — канала damage у них, как правило, нет вовсе, и без базы
-- они не наносили бы ничего.
--
-- Считается от ПОЛНОГО объёма вложенного, а не от избытка сверх
-- стоимости: применить заклинание дешевле его круга всё равно нельзя, и
-- от избытка приёмы высокого порядка не получали бы от вливания ничего.
--
-- Цифры — в SB.Data.Config (BaseDamage / DamagePerMana /
-- DamageScalePerMana / HitPerResource), там же объяснение, почему
-- именно так.
--
-- @param spell     table   Заклинание (нужен spell.level)
-- @param slotLevel number  Сколько ресурса вложено (0 = заговор/приём)
-- @return number damage, number hitBonus
-- ============================================================
function SB.Logic.GetCastPower(spell, slotLevel)
    local cfg  = SB.Data.Config
    local slot = math.max(0, tonumber(slotLevel) or 0)

    -- Именно level == 0, а не spell.isCantrip: поле isCantrip в данных
    -- расходится с кругом у десятка заклинаний (Вердикт Храмовника —
    -- третий круг с isCantrip = true) и в коде не читается больше нигде,
    -- то есть является оформлением карточки, а не механикой.
    local isCantrip = (tonumber(spell and spell.level) or 0) == 0
    local base      = isCantrip and (cfg.BaseDamage or 1) or 0

    return base + slot * (cfg.DamagePerMana or 0), slot * (cfg.HitPerResource or 0)
end

--- ============================================================
--- МОДИФИКАТОР БРОСКА ЗА КАСТ — ОДНОЙ ФУНКЦИЕЙ
---
--- Ровно то, что ProcessRollAndCast прибавит к кубику: общий реестр
--- модификаторов плюс скейлинг канала hit самого заклинания. Отдельно —
--- потому что число нужно ЗАРАНЕЕ, ещё до броска: заявка везёт его
--- Ведущему, чтобы тот увидел справедливую СЛ (см. SB.Logic.FairDC).
--- @return number
function SB.Logic.GetCastModifier(spell, slotLevel)
    local mod = SB.Logic.GetModifierBreakdown("attack",
        { spell = spell, slotLevel = slotLevel })
    return mod + (SB.Logic.GetSpellScaling(spell, "hit"))
end

--- ============================================================
--- СПРАВЕДЛИВАЯ СЛ — та, которую персонаж берёт примерно в половине
--- случаев.
---
--- ЗАЧЕМ. Ведущий выставляет СЛ вслепую: «сколько поставить пятому
--- уровню, чтобы это было не даром и не невозможно?» Бонус за уровень в
--- этой системе доходит до +30, мастерство даёт до +8, скейлинг ещё
--- сколько-то — и одна и та же цифра 60 для новичка невозможна, а для
--- развитого персонажа бессмысленна. Отсюда «шестьдесят на всех» и
--- ощущение, что броски ничего не решают.
---
--- КАК СЧИТАЕТСЯ. Успех — это total >= СЛ, где total = кубик + мод.
--- Значит СЛ, дающая ровно половину успехов, — это мод плюс середина
--- кубика: на d100 верхняя половина это 51..100, то есть СЛ = мод + 51.
--- Границы кубика берём у GetRollRange, а не константой: реалм вправе
--- играть на другом кубике.
---
--- Это ОРИЕНТИР, а не правило: Ведущий видит число в поле и двигает его
--- в обе стороны — вот и вся идея «пляшем от справедливой».
--- @param mod number  модификатор броска заклинателя
--- @return number  СЛ, дающая примерно 50% успеха
function SB.Logic.FairDC(mod)
    local lo, hi = SB.Logic.GetRollRange()
    local n = hi - lo + 1
    return (tonumber(mod) or 0) + hi - math.floor(n / 2) + 1
end

--- ============================================================
--- БАЗОВОЕ ИСЦЕЛЕНИЕ
---
--- Отдельно от GetCastPower, и разница ровно одна: база даётся ВСЕМ
--- лечащим заклинаниям, а не только заговорам. У урона база на высоком
--- круге размывала вклад характеристик, и её там убрали намеренно; у
--- лечения та же правка означала «удавшийся бросок восстановил 0 ХП»
--- каждый раз, когда у заклинания нет канала damage. Ноль в чате
--- читается как поломка аддона, а не как слабое лечение.
---
--- Вложенный ресурс считается так же, как у урона (Config.DamagePerMana
--- и множитель скейлинга) — иначе лечение и удар разошлись бы по двум
--- разным формулам, ровно от чего уходили в GetCastPower.
---
--- @param spell     table   Заклинание (нужен spell.level)
--- @param slotLevel number  Сколько ресурса вложено
--- @return number heal, number hitBonus
--- ============================================================
function SB.Logic.GetHealPower(spell, slotLevel)
    local cfg  = SB.Data.Config
    local slot = math.max(0, tonumber(slotLevel) or 0)
    local base = tonumber(cfg.BaseHeal) or 1
    -- У ЧИСТОЙ ПОЧИНКИ ДОСПЕХА БАЗЫ НЕТ. База лечения существует, чтобы
    -- удавшийся бросок не восстанавливал «0 ХП», — но заклинание, которое
    -- лечит не рану, а доспех, к здоровью отношения не имеет, и единица
    -- ХП сверху была бы подарком из ниоткуда (см. spell.repairArmor).
    if spell and spell.repairArmor and not spell.isHeal then
        return 0, 0
    end
    return base + slot * (cfg.DamagePerMana or 0), slot * (cfg.HitPerResource or 0)
end

--- НА СКОЛЬКО СДВИНУТО СВОЁ ИСХОДЯЩЕЕ ИСЦЕЛЕНИЕ — одним ответом.
---
--- Слагаемых два: канал "heal" висящих эффектов и профиль класса. Читать
--- их порознь нельзя, и это не вкусовщина: прибавка обязана попасть В ДВА
--- МЕСТА — в резолв лечения (SB.Logic.ResolveHeal) и в строку «Лечение»
--- на карточке заклинания. Пока слагаемое было одно, оба места считали
--- его одинаково по случайности; стоило появиться второму, и карточка
--- начала бы врать жрецу ровно на его классовую единицу.
---
--- ЭТО ОБЪЁМ, А НЕ БРОСОК. Профильные attack/defense живут в реестре
--- источников (SB.Logic.ModifierSources) и складываются в модификатор
--- d100; здесь другая шкала — единицы здоровья, — и общего с ними у
--- этого числа ничего нет, кроме того, что оба берутся из профиля.
---
--- НЕ ПУТАТЬ С "healTaken": тот двигает ПОЛУЧАЕМОЕ исцеление и считается
--- у того, кого лечат (см. врезку о каналах в Core/ActiveEffects.lua).
--- @return number
function SB.Logic.GetHealBonus()
    local eff = (SB.ActiveEffects and SB.ActiveEffects.GetMod)
        and (SB.ActiveEffects.GetMod("heal")) or 0
    local cls = (SB.Data and SB.Data.GetClassProfile
        and SB.Data.GetClassProfile().heal) or 0
    return eff + cls
end

-- ============================================================
-- ПОЧИНКА ДОСПЕХА КАСТОМ (spell.repairArmor)
--
-- Броня — расходуемый запас (см. врезку в Core/Skills.lua), и до сих
-- пор вернуть его можно было только Долгим Отдыхом. Заклинание с полем
-- repairArmor возвращает его посреди сцены:
--
--   repairArmor = 20,                  -- две поглощённых единицы урона
--   scaling = { armor = { ["Мощь"] = 5 } },   -- необязательный рост
--
-- ЕДЕТ ПО ТОМУ ЖЕ ПУТИ, ЧТО ЛЕЧЕНИЕ, и это не экономия, а требование:
-- запас брони живёт на клиенте носителя, значит починку обязан применить
-- он сам — ровно та же причина, по которой лечение резолвится у цели.
-- Поэтому здесь нет ни своего пакета, ни своего резолва: заклинание
-- проходит SB.Logic.ResolveHeal, а число едет в том же ответе.
--
-- Лечение и починка НЕ ИСКЛЮЧАЮТ ДРУГ ДРУГА: заклинание может делать и
-- то, и другое (isHeal = true вместе с repairArmor). Без isHeal оно чинит
-- только доспех и здоровья не касается.
-- ============================================================

--- Сколько единиц брони чинит этот каст (0 — заклинание не про доспех).
function SB.Logic.GetSpellRepair(spell, slotLevel)
    local flat = tonumber(spell and spell.repairArmor) or 0
    if flat == 0 then return 0 end
    -- Канал "armor" в scaling — необязательный, как и все прочие каналы.
    local scaled = SB.Logic.GetSpellScaling(spell, "armor", slotLevel)
    return math.max(0, flat + (tonumber(scaled) or 0))
end

--- Лечит ли это заклинание вообще — рану или доспех. Одна проверка на
--- все развилки маршрутизации: без неё чистая починка проваливалась бы в
--- заявку Ведущему, хотя решать ему тут нечего.
function SB.Logic.IsHealingCast(spell)
    if not spell then return false end
    return spell.isHeal == true or (tonumber(spell.repairArmor) or 0) > 0
end

--- ВРЕДОНОСНО ЛИ ЗАКЛИНАНИЕ — то есть делает ли оно цели плохо.
---
--- Два признака, и оба по делу: урон (canCrit) и дебафф. Всё прочее —
--- лечение, бафф, рассеивание, починка — на цель наводят с её согласия,
--- и прятаться от такого незачем (см. SB.Logic.GetStealthPenalty).
---
--- ДВОЙНОЕ ЗАКЛИНАНИЕ (isHeal + canCrit) считается вредоносным, и это
--- верно: своему оно лечит, чужому жжёт, а «свой» решается пометкой
--- друга — её и спрашивает тот, кому ответ нужен, а не эта функция.
function SB.Logic.IsHarmful(spell)
    if not spell then return false end
    return spell.canCrit == true or spell.debuff ~= nil
end

--- «БЕЗ СОПРОТИВЛЕНИЯ» (resistable = false) — ЗНАЧИТ БЕЗ ПРОВЕРКИ.
---
--- Одна точка на все пути резолва. Раньше поле честно выполнялось только
--- там, где заклинание уходило локальным броском против нуля
--- (ProcessRollAndCast) и на наложении эффекта (ResolveEffectCast) — то
--- есть у стоек, обликов и аур. Всё остальное его молча игнорировало:
---   • удар по игроку катил защитный бросок цели, и «Чародейские стрелы»
---     с resistable = false промахивались;
---   • площадной удар — то же самое, он идёт через тот же обработчик;
---   • лечение и площадное лечение брали порог 60 + уровень;
---   • площадной эффект брал порог у каждого задетого.
---
--- Проверяет КАЖДАЯ сторона у себя, а не только заклинатель: определение
--- заклинания лежит в библиотеке у всех одинаковое, и везти признак по
--- сети незачем — лишнее поле в пакете, которому к тому же пришлось бы
--- верить на слово.
---
--- ── ЧИСТЫЙ БАФФ НЕ БРОСАЕТ ВОВСЕ ────────────────────────────
---
--- Второе основание, и оно не поле, а ПРАВИЛО: заклинание, которое
--- только помогает, попадает всегда.
---
--- Бросок существует затем, чтобы решить спор. У баффа спорить не с кем:
--- цель либо ты сам, либо союзник, который её и ждёт. Провалившийся
--- самобафф — это не драматичный промах, а потраченный ход, за который
--- не случилось ровно ничего; такой исход ничего не рассказывает и
--- ничему не учит. Ста пятидесяти заклинаниям в библиотеке бросок был
--- проставлен просто потому, что resistable = true — умолчание.
---
--- ГРАНИЦА ПРОВЕДЕНА ПО ПОЛЕЗНОСТИ, а не по названию поля:
---
---   • урон и дебафф (IsHarmful) — спор есть, бросок остаётся;
---   • ЛЕЧЕНИЕ бросает по-прежнему. Это не придирка: «Милосердие»
---     покупает лекарю именно надёжность (см. SB.Skills.GetMercyHealBonus),
---     и без броска навык перестал бы значить хоть что-нибудь;
---   • кража (steal) — состязание по определению;
---   • рассеивание — тоже спор, там снимают чужое.
---
--- Заклинание с обоими концами (бафф себе плюс дебафф цели) остаётся
--- бросковым: решает вредная половина, а не добрая.
function SB.Logic.IsGuaranteed(spell)
    if spell == nil then return false end
    if spell.resistable == false then return true end

    -- СОТВОРЕНИЕ ПРЕДМЕТА — ТОЖЕ АВТОУСПЕХ, и по той же причине, что
    -- бафф: сопротивляться нечему. Маг творит воду маны себе в сумку,
    -- и «цель отвела» здесь означало бы, что сумка возразила.
    --
    -- Стоит ДО общей развилки: у creates-заклинаний нет ни buff, ни
    -- container (предмет — не эффект), и в helpsOnly они не попадали.
    if spell.creates and not SB.Logic.IsHarmful(spell) then return true end

    local helpsOnly = (spell.buff ~= nil or spell.container ~= nil)
        and not SB.Logic.IsHarmful(spell)
        and not SB.Logic.IsHealingCast(spell)
        and not spell.steal
        and not SB.Logic.GetDispelSchools(spell)
    return helpsOnly and true or false
end

--- Применяет критический удар к уже посчитанному урону.
---
--- Крит УМНОЖАЕТ итог, а не прибавляет к нему: плоская прибавка не
--- масштабировалась ни с чем и у развитого персонажа значила проценты,
--- а у заговора — половину урона, то есть работала ровно наоборот
--- задуманному (см. Config.CritDamageMultiplier).
---
--- ЗОВЁТСЯ ПОСЛЕДНИМ — ПОСЛЕ СОПРОТИВЛЕНИЯ И ДОСПЕХА.
---
--- Раньше было наоборот, и это оказалось главным источником разброса в
--- бою. Доспех вычитается плоско, поэтому на разных величинах он
--- работает совершенно по-разному:
---
---     обычный удар  5, доспех 4  →  1 прошло
---     крит         10, доспех 4  →  6 прошло     ← ×2 стало ×6
---
--- Доспех гасил обычный удар почти целиком и почти не мешал криту:
--- заявленное удвоение доходило до цели как ушестерение. В логах боя
--- это выглядело так, что обычные удары дают 1-3 при запасе в 15 ХП,
--- а крит — 12, то есть убивает с одного раза. Пятнадцать кругов
--- размена решались одним броском.
---
--- Теперь защита срабатывает по СИЛЕ УДАРА, а удвоение — по тому, что
--- сквозь неё прошло. Крит остаётся вдвое опаснее обычного удара — но
--- ровно вдвое, а не вшестеро.
---
--- Вторым значением отдаётся ИМЕННО ПРИБАВКА — сколько крит добавил
--- сверх обычного удара. Она нужна разбивке в подсказке (см.
--- SB.UI.AmountText). Слагаемые больше нигде не показываются, но
--- сойтись с итогом.
--- @return number total, number critAdd
function SB.Logic.ApplyCritDamage(sum, isCrit)
    sum = tonumber(sum) or 0
    if not isCrit then return sum, 0 end
    local mult  = tonumber(SB.Data.Config.CritDamageMultiplier) or 2
    local total = math.floor(sum * mult + 0.5)
    return total, total - sum
end

--- То же для исцеления: множитель свой (Config.CritHealMultiplier), сам
--- крит определяется тем же чистым кубиком, что и в бою.
--- @return number total, number critAdd
function SB.Logic.ApplyCritHeal(sum, isCrit)
    sum = tonumber(sum) or 0
    if not isCrit then return sum, 0 end
    local cfg   = SB.Data.Config
    local mult  = tonumber(cfg.CritHealMultiplier) or tonumber(cfg.CritDamageMultiplier) or 2
    local total = math.floor(sum * mult + 0.5)
    return total, total - sum
end

-- ============================================================
-- НАЛОЖЕНИЕ ЭФФЕКТА (баффа или дебаффа) НА СЕБЯ
--
-- Длительность берётся у САМОГО ЭФФЕКТА, а не у заклинания, которое его
-- наложило. Раньше сюда шла spell.duration заклинателя — и, например,
-- «Каменная кожа» (у заклинания duration = 1200, это минуты игрового
-- времени) висела 1200 ходов. Заодно это чинит поле «Длительность» в
-- редакторе контейнеров: ГМ его заполнял, а расчёт его игнорировал.
--
-- АПКАСТ РАСТЯГИВАЕТ ЭФФЕКТ. Считается не вся вложенная мана, а только
-- ИЗБЫТОК над собственным кругом заклинания:
--
--     множитель = 2 × (вложено − круг заклинания)
--
-- то есть 2 / 4 / 6 / 8 за один, два, три, четыре круга сверх. Раньше
-- здесь стояла степень двойки (2 / 4 / 8 / 16): заговор с дебаффом,
-- поднятый до 4-го круга, висел в ШЕСТНАДЦАТЬ раз дольше базы, и любой
-- контроль на максимальном апкасте переставал быть временным.
--
-- Заклинание 3-го круга, применённое 3-м кругом, держится базовое время;
-- поднятое до 4-го — вдвое дольше, до 5-го — вчетверо. Каст «в свой
-- круг» ничего не растягивает, поэтому заговор, применённый заговором,
-- работает ровно как раньше.
-- Бесконечные эффекты (duration = -1) умножению не подлежат.
--
-- @param effectID  string  id заклинания-контейнера
-- @param sourceSpell table|nil  заклинание, которое его наложило
-- @param slotLevel number|nil  сколько ресурса вложено в каст
-- ============================================================

--- Во сколько раз апкаст растягивает длительность: +1 базовая
--- длительность за каждый круг сверх собственного круга заклинания
--- (2 / 3 / 4 / 5). Каст «в свой круг» (и заговор заговором) даёт 1.
---
--- БЫЛО 2 × excess, то есть 2 / 4 / 6, и это не прибавка за круг, а
--- УДВОЕНИЕ прибавки: первый вложенный круг давал +1 длительность,
--- второй сразу +2, третий +2 сверх того. На заговоре в 3 хода это
--- читалось как 3 / 6 / 12 / 18 — каждый следующий круг стоил столько
--- же, а давал вдвое больше предыдущего, и вливать имело смысл только
--- по максимуму. Теперь шаг ровный: 3 / 6 / 9 / 12.
--- @return number
function SB.Logic.GetUpcastMultiplier(spell, slotLevel)
    local spellLevel = tonumber(spell and spell.level) or 0
    local excess     = (math.floor(tonumber(slotLevel) or 0)) - spellLevel
    if excess <= 0 then return 1 end
    return 1 + excess
end

--- Итоговая длительность эффекта в ходах (или SB.ActiveEffects.INFINITE).
--- Отдельной функцией, потому что то же число показывает пикер круга
--- ДО каста — а расходиться расчёт и обещание не должны.
--- @param extraTurns number|nil  прибавка ЗАКЛИНАТЕЛЯ, приехавшая вместе
---        с эффектом («Воодушевление», см. SB.Logic.EncouragementFor).
---        Своя длительность о ней знать не может: навык чужой.
--- @return number
function SB.Logic.GetEffectDuration(effectID, sourceSpell, slotLevel, extraTurns)
    -- СКОЛЬКО ЭФФЕКТ ПРОВИСИТ, РЕШАЕТ ТОЛЬКО ЗАКЛИНАНИЕ, которое его
    -- наложило. Так одна и та же «Каменная кожа» держится 3 хода от
    -- слабого заклинания и 10 от сильного, и правится это там же, где
    -- стоит сам container/buff/debuff.
    --
    -- СВОЕГО СРОКА У ЭФФЕКТА БОЛЬШЕ НЕТ ВОВСЕ, и это не упрощение ради
    -- красоты. Пока он был запасным значением, у одного и того же
    -- контейнера было два источника правды: у половины заклинаний срок
    -- стоял на заклинании, у половины молча брался из эффекта — и понять
    -- по карточке, откуда взялись эти шесть ходов, было нельзя. Хуже
    -- того, один эффект вешают РАЗНЫЕ заклинания, и «своя» длительность
    -- контейнера означала одинаковый срок у заговора и у третьего круга.
    --
    -- duration = -1 у заклинания означает БЕСКОНЕЧНЫЙ эффект: он не
    -- тикает вовсе и снимается только Долгим Отдыхом или вручную (ПКМ).
    -- Нет срока у заклинания — эффект висит один ход: меньше нельзя, а
    -- выдумывать за автора больше нечего.
    local turns = tonumber(sourceSpell and sourceSpell.duration) or 1
    if turns == 0 then turns = 1 end

    if turns < 0 then
        -- Бесконечность не умножается: «до конца сцены» вдвое — это всё
        -- та же «до конца сцены». И не продлевается: см. ниже.
        return SB.ActiveEffects.INFINITE
    end

    -- «ВООДУШЕВЛЕНИЕ» ПРИБАВЛЯЕТСЯ ПОСЛЕ УМНОЖЕНИЯ, а не до. Вложенный
    -- ресурс растягивает то, что заложено в заклинание, — навык
    -- заклинателя к этому отношения не имеет и умножаться вместе с ним
    -- не должен: иначе очко навыка стоило бы вчетверо больше на третьем
    -- круге, чем на нулевом.
    --
    -- Число приезжает СНАРУЖИ, потому что считает его заклинатель, а
    -- длительность собирает получатель (см. SB.Skills.GetEncouragementBonus).
    --
    -- И РАЗ СНАРУЖИ — ЗНАЧИТ ЗАЖИМАЕМ. Поле едет в пакете BUFF, а пакет
    -- пишет чужой клиент: без потолка присланное «enc = 9999» повесило бы
    -- эффект на девять тысяч ходов, и снять его можно было бы только
    -- Долгим Отдыхом. Это тот же принцип, по которому здесь сверяются
    -- броски (VerifyIncomingCast): своему клиенту верим, чужому — нет.
    --
    -- ПОТОЛОК ВЫВЕДЕН, А НЕ НАЗНАЧЕН: больше, чем даёт полностью
    -- вложенный навык, «Воодушевление» не даёт и у себя. Максимум навыка
    -- равен максимуму его атрибута-родителя, минус невложенная единица.
    -- ПРИБАВКА НЕ ПРИЕХАЛА — ЗНАЧИТ КАСТ СВОЙ, и навык читаем у себя.
    --
    -- Здесь, а не у пяти вызывающих: ровно этот же расчёт показывает
    -- пикер круга ДО каста (см. UI/MainFrame.lua), и разойтись обещание
    -- с исходом не должно. Чужой бафф сюда с nil прийти не может —
    -- ApplyEffect для fromOther передаёт число всегда, даже ноль.
    if extraTurns == nil then
        extraTurns = SB.Logic.EncouragementFor(effectID)
    end

    local cap = ((SB.Attributes and SB.Attributes.GetMaxValue
        and SB.Attributes.GetMaxValue()) or 5) - 1
    local extra = math.max(0, math.min(cap, math.floor(tonumber(extraTurns) or 0)))

    return math.max(1,
        math.floor(turns * SB.Logic.GetUpcastMultiplier(sourceSpell, slotLevel)) + extra)
end

--- Сколько ходов «Воодушевление» добавит ЭТОМУ эффекту.
---
--- ОДНО МЕСТО НА ВСЕ ПУТИ. Условие осталось одно: бафф ли это —
--- продлевать дебафф было бы прямо наоборот задуманному.
---
--- НА СЕБЯ НАВЫК ТЕПЕРЬ РАБОТАЕТ ТОЖЕ. Прежде стойки, ауры и облики
--- собственного каста навык не видели вовсе, и «Воодушевление»
--- оказывалось умением, которое ничего не даёт тому, кто играет один
--- или держит ауру на себе. Разменом это не было: класс просто платил
--- за навык, которым не мог пользоваться половину сцены.
--- @return number
function SB.Logic.EncouragementFor(effectID)
    if not (SB.Skills and SB.Skills.GetEncouragementBonus) then return 0 end
    local kind = SB.ActiveEffects and SB.ActiveEffects.GetKind
        and SB.ActiveEffects.GetKind(effectID) or "buff"
    if kind ~= "buff" then return 0 end
    return SB.Skills.GetEncouragementBonus()
end

-- ============================================================
-- ХОД ПОТРАЧЕН — тикнуть все висящие эффекты.
--
-- Раньше это делал только ПвЕ-каст (ProcessRollAndCast) и Короткий
-- Отдых. Любое ПвП-действие — атака, площадная атака, лечение, наложение
-- эффекта броском — ход тратило, а счётчики не трогало вовсе: в бою
-- игрок на игрока эффекты висели вечно и ни разу не тикали, то есть
-- периодический урон «Кровотечения» не приходил никогда.
--
-- @param skip table|nil { [spellID] = true } — что не трогать (только
--        что наложенный эффект: он не должен сгореть в тот же ход)
-- ============================================================
--- Человекочитаемое имя эффекта. Если эффект НЕ зарегистрирован (опечатка
--- в id, файл эффектов не загрузился), возвращает явную пометку вместо
--- голого id: в логе «eff_pain» выглядит как название заклинания, и
--- поломку данных легко принять за особенность оформления.
-- ============================================================
-- ПРОВЕРКА ЦЕЛОСТНОСТИ ССЫЛОК НА ЭФФЕКТЫ
--
-- Заклинание ссылается на эффект по строковому id, и если эффекта с
-- таким id нет, всё ломается ТИХО: SB.Logic.ApplyEffect выходит на
-- проверке `if not effectSpell then return end`, эффект не вешается, а в
-- логе печатается сам id. Со стороны это выглядит как «дебаффы работают
-- некорректно», а не как отсутствующая запись в библиотеке.
--
-- Поэтому один раз на входе проверяем все ссылки разом и говорим прямо.
-- ============================================================
--
-- Проверка отложена на следующий кадр НАМЕРЕННО. Обработчики SB_INIT
-- вызываются в порядке подписки, а Core/Logic.lua в .toc идёт раньше
-- Core/CustomSpells.lua — значит эта проверка успевала отработать ДО
-- SB.CustomSpells.Init(), которая чистит реестр от контейнеров-сирот.
-- Когда та чистка выносила живой эффект, проверка этого уже не видела
-- и молчала — ровно в том случае, ради которого её и писали.
SB.Events.On("SB_INIT", function()
  C_Timer.After(0, function()
    local broken = {}
    for id, sp in pairs(SB.Data.Spells) do
        for _, field in ipairs({ "container", "buff", "debuff", "carried" }) do
            local ref = sp[field]
            if type(ref) == "string" and ref ~= "" and not SB.Data.Spells[ref] then
                table.insert(broken, string.format("%s (%s) -> %s", sp.name or id, field, ref))
            end
        end
    end
    if #broken == 0 then return end

    table.sort(broken)
    print(SB.Theme.MSG_TAG .. "[Spellbreaker]|r: " .. SB.Theme.MSG_BAD ..
        "не найдено эффектов: " .. #broken ..
        ". Эти заклинания не смогут наложить свой эффект.|r")
    for i = 1, math.min(#broken, 10) do
        print("   " .. SB.Theme.MSG_BODY .. broken[i] .. "|r")
    end
    if #broken > 10 then
        print("   " .. SB.Theme.MSG_BODY .. "... и ещё " .. (#broken - 10) .. "|r")
    end
  end)
end)

--- @param notMyAction boolean|nil  ход потрачен НЕ собственным решением
---        игрока, а командой извне (Короткий Отдых, объявленный
---        Ведущим всей группе). Эффекты тикают и путь обнуляется как
---        обычно, но в очереди ходов такой ход не засчитывается: иначе
---        одно объявление отдыха закрывало бы круг всему рейду разом.
-- ============================================================
-- ХОД ТРАТИТСЯ, КОГДА ПРИШЁЛ ИТОГ
--
-- Удар по игроку разрешается у ЦЕЛИ: она бросает защиту, считает урон и
-- рассылает строку боя. Пока ход тратился в момент отправки, очередь
-- успевала сдвинуться раньше, чем приходил итог, и лог читался задом
-- наперёд: «Ходит: Натан» — и только потом удар, после которого он
-- ходит. У Ведущего так было всегда: его ход закрывается у него же,
-- без сети, мгновенно.
--
-- Теперь порядок причинный: удар → итог (и вампиризм, и отпись) → тики
-- эффектов → сдвиг очереди. Ход держится до ответа цели (одиночный
-- удар) или до печати блока залпа (площадь), а если ответа нет —
-- цель вышла, у неё нет аддона — тратится сам по истечении срока.
--
-- Вне пошагового режима ждать нечего: очереди нет, ход тратится сразу.
-- ============================================================
local heldTurn = nil
local HOLD_SINGLE = 4    -- секунд на ответ цели
local HOLD_AOE    = 7    -- дольше потолка окна залпа (REPORT_MAX = 6)

--- Отложить трату хода до итога.
--- @param skip   any          то, что ушло бы в SpendTurn первым доводом
--- @param isAoe  boolean|nil  площадь: ждём блок залпа, а не один ответ
function SB.Logic.HoldTurnUntilResult(skip, isAoe)
    if not (SB.TurnOrder and SB.TurnOrder.IsActive and SB.TurnOrder.IsActive()) then
        return SB.Logic.SpendTurn(skip)
    end
    -- Прошлый удержанный ход (не должен бы висеть) — закрываем сейчас.
    SB.Logic.ReleaseHeldTurn()
    local h = { skip = skip }
    heldTurn = h
    if SB.TurnOrder.SetAwaitingResult then SB.TurnOrder.SetAwaitingResult(true) end
    h.timer = C_Timer.NewTimer(isAoe and HOLD_AOE or HOLD_SINGLE, function()
        if heldTurn == h then SB.Logic.ReleaseHeldTurn() end
    end)
end

--- Итог пришёл (или вышел срок) — потратить удержанный ход.
function SB.Logic.ReleaseHeldTurn()
    local h = heldTurn
    if not h then return end
    heldTurn = nil
    if h.timer then h.timer:Cancel() end
    if SB.TurnOrder and SB.TurnOrder.SetAwaitingResult then
        SB.TurnOrder.SetAwaitingResult(false)
    end
    SB.Logic.SpendTurn(h.skip)
end

-- ============================================================
-- ВЫПЛАТА КАСТА — В СТРОКЕ КАСТА
--
-- Цена («Жизнеотвод: 1 урона») и содержимое склянки («+2 ХП») шли
-- отдельными строками, и раньше строки самого каста: выплата печаталась
-- сразу, а шапка залпа — когда соберутся ответы. Теперь выплата ждёт,
-- пока её заберёт строка каста (TakeCastPayload), и встаёт в неё:
-- «Денрук применяет [Жизнеотвод]: +2 Мана, 1 урона.». Не забрал никто
-- (например, удар по игроку — его строку пишет цель) — печатается
-- отдельно, как раньше, в конце кадра.
-- ============================================================
local castPayload = nil

--- Забрать текст выплаты этого каста (или nil). Забранный больше не
--- печатается отдельно.
function SB.Logic.TakeCastPayload(spellID)
    local p = castPayload
    if not p or (spellID and p.spellID ~= spellID) then return nil end
    castPayload = nil
    return p.text
end

function SB.Logic.SpendTurn(skip, notMyAction)
    -- БОНУСНОЕ ДЕЙСТВИЕ ХОДА НЕ СТОИТ, и «не стоит» здесь буквально: ни
    -- тика эффектам, ни отметки у Ведущего, ни кулдауна темпа. Выпитое
    -- зелье не двигает время — оно занимает свободную руку.
    if pendingBonusAction then
        pendingBonusAction = false
        if SB.TurnOrder and SB.TurnOrder.NoteBonusUsed then
            SB.TurnOrder.NoteBonusUsed()
        end
        return
    end
    -- В СВОБОДНОМ ХОДУ ЭФФЕКТЫ ТИКАЮТ ТОЛЬКО ПО ВРЕМЕНИ.
    --
    -- Пока пошагового режима нет, время идёт само: раз в шесть секунд
    -- Ведущий списывает ход всем эффектам разом (RTDECR, см.
    -- SyncRealtimeToTurnMode в UI/GMPanel.lua). Если вдобавок тикать от
    -- собственных действий, активный игрок сжигает свои эффекты вдвое
    -- быстрее пассивного — за то, что он что-то делает. «Ход» вне
    -- очереди вообще не определён: его не у кого отсчитывать.
    --
    -- В пошаговом режиме наоборот: таймер выключен, и единственный
    -- отсчёт — собственное действие игрока. Одно из двух работает
    -- всегда, оба сразу — никогда.
    local turnBased = (not SB.TurnOrder) or SB.TurnOrder.IsActive()
    if turnBased and SB.ActiveEffects and SB.ActiveEffects.TickAll then
        SB.ActiveEffects.TickAll(skip)
    end

    -- ПОШАГОВЫЙ РЕЖИМ: ход закрыт. Отметка живёт здесь по той же
    -- причине, что и сброс пройденного пути ниже, — через SpendTurn
    -- проходят ВСЕ пути действия (каст, отдых, пропуск хода), и
    -- отмечаться в каждом отдельно значило бы однажды забыть.
    if not notMyAction then
        if SB.TurnOrder and SB.TurnOrder.NoteLocalAction then
            SB.TurnOrder.NoteLocalAction()
        end
        -- Тот же кулдаун темпа, что и у каста: сюда приходят Короткий
        -- Отдых и пропуск хода, у которых своего CAST_CONFIRMED нет.
        if SB.Cooldowns then SB.Cooldowns.Start(SB.Cooldowns.TURN) end
    end
    -- ПУТЬ ЗДЕСЬ БОЛЬШЕ НЕ ОБНУЛЯЕТСЯ.
    --
    -- Раньше его обнуляло само действие, и граница хода получалась не
    -- там, где она есть на самом деле. Пробежал двенадцать метров,
    -- ударил — счётчик обнулился, — и оставшееся время до конца хода
    -- можно было бежать ещё двенадцать: они уже уходили в следующий ход
    -- и съедали его целиком. То есть перемещение растекалось между
    -- ходами, хотя предел задуман как «столько метров ЗА ХОД».
    --
    -- Теперь путь обнуляется в НАЧАЛЕ своего хода — там же, где для
    -- игрока начинается новый ход (см. NotifyTransitions в
    -- Core/TurnOrder.lua). Вне пошагового режима метры не копятся вовсе,
    -- так что сбрасывать там нечего.
    --
    -- Отдых и переключение режима обнуляют путь по-прежнему: это не ход,
    -- а обнуление сцены (см. PM.FullReset и TO.ApplyRemoteState).
end

--- Какие эффекты НЕ должен тикать ход, потраченный на это заклинание.
--- Собрано в одну функцию, потому что путей резолва пять (ПвЕ, ПвП,
--- площадь-урон, площадь-эффект, эффект на цель) и в каждом список
--- составлялся отдельно — а забытая строка означает эффект, который
--- сгорает на единицу в тот же миг, когда лёг.
---
--- ПРОПУСКАЕМ ТО, ЧТО НАЛОЖЕНО, А НЕ ТО, ЧТО ОБЪЯВЛЕНО.
---
--- Здесь стояла строка «есть поле container — не тикать его», и она
--- врала в двух случаях сразу, потому что спрашивала описание
--- заклинания вместо того, что реально произошло:
---
---   • удар по существу контейнер не вешает вовсе (своя ветка резолва,
---     см. SB.Logic.ResolveNpcAttack) — а тик всё равно пропускался.
---     «Призвать рой» чернокнижника поэтому не тикал сам себя: рой висел
---     сколько угодно, пока им же и бьёшь, и списывался только с чужого
---     каста;
---   • провалившийся ПвЕ-каст контейнер тоже не вешает — и там правило
---     приходилось ОТМЕНЯТЬ руками, строкой `skip[spell.container] = nil`
---     (см. ProcessRollAndCast). Отменять объявленное — верный признак
---     того, что объявлять его не следовало.
---
--- Теперь наложенное едет ТРЕТЬИМ АРГУМЕНТОМ, как уже ездило у площади
--- (landedOnSelf): путь, который эффект повесил, тот про него и говорит.
--- Заклинание объявляет ВОЗМОЖНОСТЬ, а не факт, и решать по нему —
--- значит поверить описанию против движка.
---
--- @param spell    table   заклинание
--- @param spellID  string
--- @param extra    string|nil  что этот каст ДЕЙСТВИТЕЛЬНО наложил на
---        заклинателя (контейнер, бафф на себя). Не наложил — не
---        передавай: тик этому эффекту положен.
--- @return table
function SB.Logic.TurnSkipFor(spell, spellID, extra)
    local skip = {}
    if spell then
        -- Держатель потока: его применение уже списала
        -- SB.ActiveEffects.Use, второй раз списывать нельзя — иначе
        -- поток на 3 применения кончался бы за два клика.
        if spell.channelEffect then skip[spell.channelEffect] = true end
        -- Сам контейнер, если применяют именно его (Use уже уменьшил).
        if spell.isContainer then skip[spellID] = true end
    end
    if extra then skip[extra] = true end
    return skip
end

-- ============================================================
-- РУЧНЫЕ ДЕЙСТВИЯ С БЕЙДЖЕЙ МОДИФИКАТОРОВ (шапка главного окна)
--
-- Обе кнопки нужны для ситуаций, которые аддон не разбирает сам:
-- защита против НПС (её бросает Ведущий, а не сеть) и «просто прошёл
-- ход» — сцена, где никто ничего не применял, но эффекты должны
-- отщёлкать.
-- ============================================================

--- Бросок АТАКИ вне заклинания — ПвЕ-утилита по требованию Ведущего.
--- Ровно те же кубик и источники, что уходят в каст, но без самого
--- заклинания: ни ресурс не тратится, ни ход, ни скейлинг конкретного
--- заклинания не участвует (он привязан к spell и добавляется только в
--- момент каста, см. SB.Logic.GetSpellScaling).
---
--- Нужно для сцен, где Ведущий просит «кинь атаку»: замахнуться веслом,
--- сбить замок, толкнуть противника — действие боевое, а заклинания под
--- него нет. Зеркало RollManualDefense ниже.
function SB.Logic.RollManualAttack()
    -- Тот же счётчик темпа, что у проверки навыка: ход не тратится,
    -- значит сдерживать нечему (см. Core/Cooldowns.lua).
    if SB.Cooldowns and not SB.Cooldowns.Check(SB.Cooldowns.ROLL) then return end
    if SB.Cooldowns then SB.Cooldowns.Start(SB.Cooldowns.ROLL) end

    local mod, modParts = SB.Logic.GetModifierBreakdown("attack")
    local lo, hi = SB.Logic.GetRollRange()
    local roll   = SB.Logic.Roll()
    local total  = roll + mod

    local G = SB.Theme.MSG_BODY
    SB.Events.Fire("BROADCAST_LOG",
        SB.Theme.MSG_TAG .. "[Spellbreaker]:|r " .. G .. UnitName("player") ..
        " атакует: |r" .. SB.UI.RollLine(roll, mod, total, G) .. G .. ".|r",
        SB.LogRank.ACTION)
    return total
end

--- Бросок ЗАЩИТЫ вне размена: тот же кубик и те же источники, что в
--- HandlePvpAttackReceived, но без атакующего. Нужен, когда бьёт НПС:
--- аддон о таком ударе не знает, и раньше игроку приходилось кидать
--- /roll и складывать модификаторы в уме.
function SB.Logic.RollManualDefense()
    if SB.Cooldowns and not SB.Cooldowns.Check(SB.Cooldowns.ROLL) then return end
    if SB.Cooldowns then SB.Cooldowns.Start(SB.Cooldowns.ROLL) end

    local mod, modParts = SB.Logic.GetModifierBreakdown("defense")
    local lo, hi = SB.Logic.GetRollRange()
    local roll   = SB.Logic.Roll()
    local total  = roll + mod

    local G = SB.Theme.MSG_BODY
    SB.Events.Fire("BROADCAST_LOG",
        SB.Theme.MSG_TAG .. "[Spellbreaker]:|r " .. G .. UnitName("player") ..
        " защищается: |r" .. SB.UI.RollLine(roll, mod, total, G) .. G .. ".|r",
        SB.LogRank.ACTION)
    return total
end

--- «Прошёл ход» вручную. Урон и лечение от тиков соберутся в одну
--- строку сами (см. FlushTickSummary в Core/ActiveEffects.lua).
---
--- Доступен ВСЕГДА, а не только когда есть что тикать. Раньше кнопка
--- молча отказывала при пустой панели эффектов, и «постоять этот ход»
--- было нечем — а пропуск нужен сам по себе: он закрывает ход, двигает
--- очередь и тикает эффектам, что бы у игрока ни висело.
function SB.Logic.SpendTurnManually()
    local PM = SB.PlayerModel

    -- Павший не пропускает ход, а лежит: очередь его и так пролистывает,
    -- а действовать он не может ничем (см. PM.IsDowned).
    if PM.IsDowned() then SB.UI.PrintMsg("downedCantAct") return end

    -- Пропуск хода — тоже ход: не свой черёд, значит и пропускать нечего
    -- (см. Core/TurnOrder.lua), и темп он держит наравне с кастом.
    if SB.TurnOrder and not SB.TurnOrder.CheckCanAct() then return end
    if SB.Cooldowns and not SB.Cooldowns.Check(SB.Cooldowns.TURN) then return end

    -- Пройденный путь читаем ДО SpendTurn: он там же и обнуляется,
    -- как и на любом другом потраченном ходу.
    local walked = SB.Movement and SB.Movement.GetDistance() or 0

    SB.Logic.SpendTurn()

-- ============================================================
    -- ПРОПУСК ХОДА БОЛЬШЕ НЕ ВОЗВРАЩАЕТ РЕСУРС
    --
    -- Здесь стояло «+1 ресурса за пропущенный ход»: ход, потраченный
    -- впустую, чем-то оплачивался. Заведено это было тогда, когда
    -- восполнять ресурс было больше нечем — и пропуск оставался
    -- единственным способом дотянуть до конца сцены.
    --
    -- Теперь способов хватает: классовые механики копят его сами (см.
    -- Core/ClassMechanics.lua), а сумка даёт зелья маны и ярости (см.
    -- Core/Items.lua). Прибавка за бездействие поверх этого создаёт
    -- профицит: выгодно СТОЯТЬ, а не действовать, — то есть правило
    -- работает против самой сцены.
    --
    -- Пропуск при этом остаётся полноценным ходом: эффекты тикают, путь
    -- обнуляется, очередь двигается. Он просто перестал быть выгодным.
    -- ============================================================
    local G = SB.Theme.MSG_BODY
    local parts = {}
    if walked >= 0.5 then
        table.insert(parts, string.format("переводит дух после %.0f м", walked))
    end
    local tail = (#parts > 0) and (" (" .. table.concat(parts, ", ") .. ")") or ""

    -- Жёлтым, как и всё про очередь ходов: пропуск — это ход, и соседям
    -- по сцене важно увидеть его так же быстро (см. Core/Theme.lua).
    SB.Events.Fire("BROADCAST_LOG",
        SB.Theme.MSG_TAG .. "[Spellbreaker]:|r " .. SB.Theme.MSG_TURN ..
        UnitName("player") .. " пропускает ход" .. tail .. ".|r", SB.LogRank.ACTION)

    SB.Events.Fire(SB.E.STATUS_CHANGED)
end

-- ============================================================
-- ПОБЕГ ИЗ БОЯ
--
-- Персонаж выходит из сцены. С этого мгновения очередь ходов его
-- пролистывает — ровно как павшего, — а вернуться в строй можно только
-- новым запуском пошагового режима (см. PM.HasFled и TO.Start).
--
-- ЭТО ПОТРАЧЕННЫЙ ХОД, а не бесплатная кнопка: убежать посреди схватки
-- стоит того же, что и любое другое действие. Отсюда и тик эффектов —
-- кровотечение догоняет беглеца.
--
-- РЕСУРС ЗА НЕГО НЕ ВОЗВРАЩАЕТСЯ, в отличие от пропуска хода. Пропуск —
-- это «стою и перевожу дух», побег — «бегу со всех ног»; платить за него
-- маной было бы странно, а доплачивать — тем более.
--
-- ПвП-размен при этом НЕ ЗАКРЫВАЕТСЯ: убежал один, а бой продолжается, и
-- объявлять группе Короткий Отдых по-прежнему нельзя.
--
-- ── БРОСОК ──────────────────────────────────────────────────
-- Побег не даётся сам: нужно взять порог 60 + свой уровень — тот же, по
-- которому считаются лечение и закрепление эффектов (см.
-- SB.Logic.EffectThreshold), и по той же эталонной шкале.
--
-- К броску прибавляются НЕПРОЙДЕННЫЕ метры, а не предел передвижения. Из
-- этого следует всё, ради чего механика и нужна: убегать надо ПЕРВЫМ
-- делом, пока ноги свежие. Отбегал полный ход и решил уйти — уходишь на
-- голом кубике; стоял и не двигался — прибавка полная. Предел здесь не
-- годится: он у всех разный и не зависит от того, что персонаж уже
-- сделал в этот ход, то есть был бы просто ещё одной надбавкой к броску.
--
-- ПРЕДЕЛ СНЯТ ВЕДУЩИМ (moveFree) ИЛИ ЕГО НЕТ ВОВСЕ — прибавки нет, а
-- бросок остаётся. Считать «бесконечный остаток» бесконечной прибавкой
-- значило бы, что на свободной сцене побег не проваливается никогда.
--
-- ПРОВАЛ ТОЖЕ СТОИТ ХОДА. Иначе кнопку жали бы до успеха, и бросок был
-- бы формальностью: сбежать всё равно получится, вопрос только — на
-- каком нажатии.
--
-- ── ПОПЫТКИ ─────────────────────────────────────────────────
-- И даже стоимости хода оказалось мало: кто жал кнопку каждый круг, в
-- конце концов уходил. Поэтому попыток на сцену — счётное число
-- (одна у каждого плюс ступени «Выживания», см. SB.Skills.GetFleeAttempts),
-- и тратит попытку ЛЮБОЙ исход: удачный и неудачный. Возвращает их
-- Долгий Отдых (см. PM.FullReset).
--
-- БЕЗ ПОПЫТОК — ОТКАЗ, А НЕ ДЕЙСТВИЕ: ход не тратится, бросок не
-- катится. Нажать то, что заведомо не может сработать, — это ошибка
-- интерфейса, а не решение персонажа, и брать за неё ход нечестно.
-- ============================================================

--- Порог побега и текущая прибавка к броску — наружу, чтобы подсказка
--- на кнопке показывала те же числа, по которым считает сама механика.
--- @return number threshold, number bonus
function SB.Logic.GetFleeOdds()
    -- Через общий расчёт порога, а не своей формулой: 60 и перевод
    -- уровня в эталонную шкалу живут там (см. SB.Logic.EffectThreshold),
    -- и вторая копия однажды разошлась бы с первой. onSelf = false —
    -- уровень в пороге нужен, вражда (isDebuff) здесь ни при чём.
    local threshold = SB.Logic.EffectThreshold("player", false, false)

    local bonus = 0
    if SB.Movement and SB.Movement.GetRemaining then
        local left = SB.Movement.GetRemaining()
        -- NO_LIMIT (-1) — это «предела нет», а не «осталось минус метр».
        if left and left > 0 then bonus = math.floor(left) end
    end
    return threshold, bonus
end

function SB.Logic.Flee()
    local PM = SB.PlayerModel

    -- Павший не убегает: он не может ни действовать, ни ползти
    -- (см. PM.IsDowned). Для очереди он и так уже пролистывается.
    if PM.IsDowned() then SB.UI.PrintMsg("downedCantAct") return end

    if PM.HasFled() then
        print(SB.Theme.MSG_BAD .. "[Spellbreaker]: Вы уже вышли из боя — " ..
            "вернёт в строй только новый запуск пошагового режима.|r")
        return
    end

    -- ДО проверки очереди и темпа: кончившиеся попытки — это «нельзя
    -- вовсе», и спрашивать про чужой ход тому, кто бежать не может,
    -- значило бы ответить не на тот вопрос.
    local left, max = PM.GetFleeAttempts()
    if left <= 0 then
        print(SB.Theme.MSG_BAD .. string.format(
            "[Spellbreaker]: Попытки побега кончились (0/%d) — вернёт их Долгий Отдых.|r",
            max))
        return
    end

    -- Тот же темп и та же очередь, что у любого действия: побег в чужой
    -- ход — это ход, украденный у соседа.
    if SB.TurnOrder and not SB.TurnOrder.CheckCanAct() then return end
    if SB.Cooldowns and not SB.Cooldowns.Check(SB.Cooldowns.TURN) then return end

    -- Метры читаем ДО SpendTurn: она обнуляет пройденный путь, как и на
    -- любом другом потраченном ходу.
    local walked = SB.Movement and SB.Movement.GetDistance() or 0
    local threshold, bonus = SB.Logic.GetFleeOdds()

    local roll    = SB.Logic.Roll()
    local total   = roll + bonus
    local escaped = total >= threshold

    if escaped then PM.SetFled(true) end
    -- Попытка тратится при ЛЮБОМ исходе — иначе лимит обходился бы
    -- провалами, и держал бы он только удачливых.
    PM.NoteFleeAttempt()
    -- Кулдаун темпа взводит сама SpendTurn — через неё проходят все пути
    -- действия, и второй раз здесь он был бы лишним.
    SB.Logic.SpendTurn()

    local G       = SB.Theme.MSG_BODY
    local rollTxt = SB.UI.RollLine(roll, bonus, total, G) ..
                    G .. " против " .. threshold .. ". |r"
    -- Прибавка объясняется прямо в строке: «+9» на пустом месте читается
    -- как случайное число, а «запас хода» сразу подсказывает, почему в
    -- следующий раз стоит бежать раньше.
    local why = (bonus > 0)
        and (G .. " (запас хода: " .. bonus .. " м)|r") or ""
    local walkTxt = (walked >= 0.5)
        and string.format(G .. " Позади %.0f м.|r", walked) or ""

    local outcome = escaped
        and (SB.Theme.MSG_GOOD .. "Удалось оторваться — ход к нему больше не переходит.|r")
        or  (SB.Theme.MSG_BAD  .. "Уйти не вышло: путь отрезан.|r")

    SB.Events.Fire("BROADCAST_LOG",
        SB.Theme.MSG_TAG .. "[Spellbreaker]:|r " .. SB.Theme.MSG_TURN ..
        UnitName("player") .. " пытается сбежать из боя!|r " .. G .. ": |r" ..
        rollTxt .. why .. walkTxt .. " " .. outcome, SB.LogRank.ACTION)

    SB.Logic.PlayOutcomeSound(escaped)
    SB.Events.Fire(SB.E.STATUS_CHANGED)
end

--- ПОДДЕРЖИВАЕТСЯ ЛИ ЗАКЛИНАНИЕ КОНЦЕНТРАЦИЕЙ — ОДИН ОТВЕТ НА ВОПРОС.
---
--- Флаг стоит в двух местах, и это не дублирование: `isConcentration` у
--- ЭФФЕКТА говорит «эту штуку надо держать», у ЗАКЛИНАНИЯ — «этот каст
--- переводит тебя в режим удержания». Обычно совпадает; расходится там,
--- где эффект вешают разными способами.
---
--- ПОРЯДОК ТОТ ЖЕ, ЧТО В ApplyEffect: эффект первым, заклинание запасным.
--- Именно из-за того, что интерфейс спрашивал ТОЛЬКО заклинание, пять
--- заклинаний работали концентрацией молча — «Незаметность» разбойника,
--- «Подготовка», «Безрассудство» воина, «Медитация дзен» монаха и
--- «Притвориться мертвым» охотника. Флаг у них стоит у контейнера.
---
--- СМОТРИМ container, А НЕ buff/debuff: концентрация — это то, что
--- держит ЗАКЛИНАТЕЛЬ, а buff и debuff уезжают на чужого персонажа, и
--- их поддерживаемость к моему слоту отношения не имеет (см. врезку
--- о fromOther в ApplyEffect).
--- @param spell table|string  запись заклинания или его id
--- @return boolean
function SB.Logic.IsConcentration(spell)
    if type(spell) == "string" then spell = SB.Data.Spells[spell] end
    if type(spell) ~= "table" then return false end

    local cont = spell.container and SB.Data.Spells[spell.container]
    if cont and cont.isConcentration ~= nil then
        return cont.isConcentration == true
    end
    return spell.isConcentration == true
end

--- @param fromOther boolean|nil  эффект пришёл от ЧУЖОГО каста: бафф
---        союзника, залп по площади, способность существа. Тогда моим
---        слотом концентрации он не считается — см. врезку ниже.
--- @param extraTurns number|nil  прибавка к сроку от ЗАКЛИНАТЕЛЯ
---        («Воодушевление»). Приезжает по сети вместе с эффектом: свой
---        клиент чужого навыка не видит (см. SB.Logic.GetEffectDuration).
--- @param source string|nil  кто наложил. Нужен только провокации
---        (см. врезку «ПРОВОКАЦИЯ» в Core/ActiveEffects.lua), и потому
---        передаётся лишь там, где имя и так на руках, — новых полей в
---        пакетах это не стоит нигде.
function SB.Logic.ApplyEffect(effectID, sourceSpell, slotLevel, fromOther, extraTurns, source)
    if not effectID or not SB.ActiveEffects or not SB.ActiveEffects.Add then return end
    local effectSpell = SB.Data.Spells[effectID]
    if not effectSpell then return end

    -- ЧУЖОЙ БАФФ ВЕЗЁТ СВОЁ ЧИСЛО, И ОНО МОЖЕТ БЫТЬ НУЛЁМ. Ноль в
    -- пакете не едет (лишнее поле ради навыка, которого у большинства
    -- нет), поэтому подставляем его здесь — иначе GetEffectDuration
    -- принял бы отсутствие прибавки за свой каст и добавил бы к чужому
    -- баффу МОЙ навык.
    if fromOther then extraTurns = tonumber(extraTurns) or 0 end
    local turns = SB.Logic.GetEffectDuration(effectID, sourceSpell, slotLevel, extraTurns)

    -- ── КОНЦЕНТРИРУЕТСЯ ТОТ, КТО КАСТОВАЛ ───────────────────
    --
    -- Своя аура занимает свой слот: концентрация одна, новая снимает
    -- прежнюю (см. SB.ActiveEffects.Add). Чужая — не занимает ничего.
    --
    -- ПОЧЕМУ ЭТО БЫЛО СЛОМАНО. Ниже стоял запасной вариант «нет флага у
    -- эффекта — спроси заклинание», и он верен для СВОЕГО каста: у
    -- «Духа ястреба» флаг стоит именно на заклинании. Но ту же функцию
    -- зовёт HandleBuffReceived для ЧУЖОГО баффа — и концентрация
    -- союзника приезжала помеченной как моя. Дальше Add честно снимал
    -- всё, что помечено концентрацией, и площадная «Аура верного
    -- выстрела» дружественного охотника сносила мой собственный «Дух
    -- ястреба»: ход потрачен впустую, причём чужими руками. Таких
    -- заклинаний, дотягивающихся до союзника, одиннадцать.
    --
    -- ЧУЖАЯ АУРА — ОБЫЧНЫЙ БАФФ. Не «хрупкая концентрация на мне»: она
    -- живёт свой срок, мой урон её не сбивает и мою концентрацию она не
    -- трогает. Держит её тот, кто её наложил, — на его клиенте, его
    -- слотом, и сбивается она его уроном.
    local isConc
    if not fromOther then
        isConc = effectSpell.isConcentration
        if isConc == nil then isConc = sourceSpell and sourceSpell.isConcentration end
    end

    SB.ActiveEffects.Add(effectID, turns, isConc or false, source)
end

-- ============================================================
-- СОБСТВЕННЫЙ КОНТЕЙНЕР ЗАКЛИНАТЕЛЯ — ОДНО МЕСТО НА ВСЕ ПУТИ
--
-- container — это то, что заклинание оставляет НА САМОМ ЗАКЛИНАТЕЛЕ:
-- стойка, аура, буря вокруг себя, рой мошкары. Вешать его обязан каждый
-- путь резолва, а путей пять — ПвЕ-бросок, форсированный исход, ПвП-удар,
-- площадь и размен с существом.
--
-- ПОЧЕМУ ФУНКЦИЯ, А НЕ ПЯТЬ ОДИНАКОВЫХ ВЕТОК. Пять веток и были, точнее
-- четыре: размен с существом отпочковался позже всех и шага не
-- унаследовал вовсе. Наружу это вышло тем, что «Призвать рой», применённый
-- по волку, не давал чернокнижнику ничего — чтобы призвать рой, надо было
-- им НЕ бить. Пятая забытая ветка — это не случайность, а свойство
-- правила, размазанного по пяти файлам.
--
-- ── КОГДА ИМЕННО ЛОЖИТСЯ ────────────────────────────────────
--
-- ПО ТОМУ, ЧТО ИЗВЕСТНО ЭТОЙ ВЕТКЕ, — то же правило, по которому здесь
-- решается вообще всё спорное: порог считает тот, у кого есть числа;
-- пропуск тика считается по наложенному, а не по объявленному; вампиризм
-- берёт фактический урон из ответа, а не свою заявку.
--
--   исход известен и положителен  → вешаем;
--   исход известен и отрицателен  → не вешаем;
--   исход НЕ известен             → вешаем сразу.
--
-- Третья строка — не поблажка, а честность: в ПвП исход считает
-- защищающийся и присылает ответом позже, у площади целей много и общего
-- исхода нет вовсе. Ждать там нечего, а поле вокруг заклинателя уже
-- бушует. Гадать за отсутствующий ответ — значит завести шестое правило.
--
-- Ни одно заклинание здесь не упоминается и упоминаться не должно:
-- ветка выбирается по тому, что знает ПУТЬ, а не по тому, какой спелл
-- по нему поехал.
-- ============================================================

--- @param spell     table       заклинание
--- @param slotLevel number|nil  вложенный круг (растягивает срок)
--- @param landed    boolean|nil исход, ЕСЛИ он известен этой ветке;
---        nil — не известен (ответ по сети, много целей, воля Ведущего)
--- @return string|nil  что легло на заклинателя — сразу в TurnSkipFor
function SB.Logic.ApplyOwnContainer(spell, slotLevel, landed)
    local id = spell and spell.container
    if not id then return nil end
    if landed == false then return nil end

    SB.Logic.ApplyEffect(id, spell, slotLevel)
    -- Возвращаем id, а не true: вызывающий отдаёт его в TurnSkipFor, и
    -- «что наложено» с «что не тикать» так не могут разойтись в принципе.
    return id
end

-- ============================================================
-- ЗАКЛИНАНИЕ, КОТОРОЕ КЛАДЁТ ПРЕДМЕТ В СУМКУ
--
--     creates = "item_mana_water"        -- полная пачка
--     creates = { item = "...", count = 2 }
--
-- Раньше «Создание воды маны» вешало на мага бафф, и «выпить воду»
-- означало дождаться, пока бафф спадёт (см. врезку в Spells/Conjured.lua).
-- Теперь вода ложится в «Предметы» и применяется оттуда — тем же
-- нажатием и тем же кодом, что склянка алхимика.
--
-- ЗОВЁТСЯ ТАМ ЖЕ, ГДЕ ВЕШАЕТСЯ КОНТЕЙНЕР, и по той же причине: путей
-- резолва несколько, и заклинание, забывшее сработать в одном из них, —
-- ровно тот баг, который однажды уже был у onCast.
--
-- ── СОТВОРЕНИЕ — ЭТО ИСХОД, А НЕ ОТДЕЛЬНЫЙ ВИД КАСТА ────────
--
-- Долгое время creates означало «заклинание, которое только и делает,
-- что кладёт вещь в сумку»: шесть таких, у всех ни цели, ни броска.
-- «Похищение души» ломает это допущение — оно БЬЁТ и при этом добывает
-- осколок, — и допущение пришлось разобрать надвое:
--
--   • МАРШРУТ выбирается по тому, что заклинание делает с ЦЕЛЬЮ
--     (см. развилку в ConfirmCast): бьёт — значит идёт ударом;
--   • СОТВОРЕНИЕ срабатывает по ИСХОДУ, здесь.
--
-- ИСХОД СПРАШИВАЕМ ТЕМ ЖЕ ПРАВИЛОМ, что у собственного контейнера
-- заклинателя (SB.Logic.ApplyOwnContainer): известен и положителен —
-- кладём; известен и отрицателен — нет; НЕ известен (ответ придёт по
-- сети) — кладём сразу. Второе правило на тот же вопрос заводить незачем.
--- @param landed boolean|nil  исход, ЕСЛИ он известен этой ветке
--- @return number сколько штук легло
function SB.Logic.GrantCreatedItems(spell, landed)
    local c = spell and spell.creates
    if not c then return 0 end
    if landed == false then return 0 end
    local id    = (type(c) == "table") and c.item or c
    local count = (type(c) == "table") and c.count or nil
    if type(id) ~= "string" then return 0 end

    local got, why = SB.Items.Grant(id, count)
    local sp = SB.Data.Spells[id]
    local nm = (sp and sp.name) or id

    if got > 0 then
        print(SB.Theme.MSG_TAG .. "[Spellbreaker]|r: " .. SB.Theme.MSG_GOOD ..
            "«" .. nm .. "» — в сумке " .. SB.Items.CountOf(id) .. ".|r")
    elseif why == "no_slot" then
        -- ГОВОРИМ, ПОЧЕМУ НЕ ВЫШЛО. Молчащий каст, потративший ресурс и
        -- ход, читается как поломка аддона — а причина в том, что все
        -- ячейки заняты, и это игрок может исправить сам.
        print(SB.Theme.MSG_TAG .. "[Spellbreaker]|r: " .. SB.Theme.MSG_BAD ..
            "«" .. nm .. "» некуда положить: все ячейки предметов заняты.|r")
    elseif why == "full_stack" then
        print(SB.Theme.MSG_TAG .. "[Spellbreaker]|r: " .. SB.Theme.MSG_BAD ..
            "«" .. nm .. "» больше не держится: " ..
            SB.Items.CountOf(id) .. " и так предел.|r")
    end
    return got
end

-- ============================================================
-- НАЛОЖЕНИЕ ЭФФЕКТА НА ЦЕЛЬ ИЛИ НА СЕБЯ (spell.buff)
--
-- Три поля описывают три разных адресата, и путать их не надо:
--
--   container = "eff_x"  — ВСЕГДА на себя. Для того, что физически
--                          нельзя навести на другого: боевые стойки,
--                          собственные ауры, обликы.
--   buff      = "eff_x"  — на ЦЕЛЬ, если в цели дружественный игрок;
--                          иначе на себя. Это тот самый случай «Щит
--                          Жреца»: одно и то же заклинание кастуется и
--                          на себя, и на союзника, и разводить его на
--                          два разных заклинания незачем.
--   debuff    = "eff_x"  — на цель при попадании в ПвП (вешает себе сам
--                          защищающийся, см. HandlePvpAttackReceived).
--
-- Пакет уходит адресно тому, на кого кастовали. Проверки на лидера тут
-- нет и быть не может (баффует кто угодно кого угодно) — это тот же
-- уровень доверия, что и у лечения, которое так работает давно.
-- ============================================================

--- @param spell table  заклинание с полем buff
--- @param slotLevel number|nil  вложенный ресурс (растягивает длительность)
--- @return string|nil  имя цели, если эффект ушёл ей (для лога)
function SB.Logic.ApplyBuffToTarget(spell, slotLevel)
    if not spell or not spell.buff then return nil end

    local me = UnitName("player")
    local staysOnMe = ItemStaysOnCaster(spell, pendingTargetName ~= "")
    local onAlly = pendingTargetIsAlly
        and pendingTargetName ~= ""
        and pendingTargetName ~= me
        and not staysOnMe

    if onAlly and IsInGroup() and SB.Net and SB.Net.SendBuff then
        SB.Net.SendBuff(pendingTargetName, spell.id, spell.buff, slotLevel)
        return pendingTargetName
    end

    -- ТО ЖЕ ПРАВИЛО, ЧТО В GetTargetedEffect, и это не дублирование, а
    -- вторая половина одной развилки: туда попадают касты, которые аддон
    -- разрешает сам, сюда — те, что вернулись от Ведущего или прошли без
    -- сопротивления.
    --
    -- Эффект остаётся на заклинателе, только если заклинание про себя
    -- (дальность 0) или в цели мы сами. Иначе цель — то, чего аддон не
    -- видит: НПС, персонаж вне группы, декорация сцены. Раньше такой
    -- бафф молча ложился на заклинателя.
    --
    -- ПЛОЩАДЬ ИСКЛЮЧЕНА, как и в GetTargetedEffect: её аура вокруг
    -- заклинателя и должна лечь на него, таргета у неё нет по устройству.
    -- ПРЕДМЕТ БЕЗ ЦЕЛИ ЛОЖИТСЯ НА ВЫПИВШЕГО (см. ItemStaysOnCaster).
    -- Пока этой ветки не было, зелье с дальностью «ближний бой» и без
    -- таргета уходило по последней строке — «цели Ведущего»: склянка
    -- расходовалась, в лог шло «эффект -> цель Ведущего», а на игроке не
    -- оказывалось ничего.
    if staysOnMe or spell.aoe or pendingTargetName == me
       or (tonumber(spell.distance) or 0) <= 0 then
        SB.Logic.ApplyEffect(spell.buff, spell, slotLevel)
        return nil
    end
    return nil, true    -- ушёл цели Ведущего, локально не легло
end

--- Принимающая сторона: на нас навесили эффект.
--- slotLevel приходит по сети от заклинателя: длительность зависит от
--- того, сколько ресурса влил ОН, а нам это неоткуда узнать локально.
--- @param total number|nil  итог броска заклинателя. Есть он — ПОРОГ
---        БЕРЁМ У СЕБЯ и решаем сами; нет — эффект ложится безусловно
---        (старая сборка, приказ Ведущего, отдача щита, бафф союзнику —
---        там броска и не было).
--- @param sender string|nil  настоящее имя отправителя: casterName может
---        оказаться именем существа, от чьего лица бьёт Ведущий.
--- @param extraTurns number|nil  прибавка к сроку от «Воодушевления»
---        заклинателя. Считает её ОН и шлёт вместе с эффектом: своего
---        клиента чужой навык не касается (см. SB.Logic.EncouragementFor).
function SB.Logic.HandleBuffReceived(casterName, spellID, effectID, slotLevel,
                                     roll, mod, total, sender, extraTurns)
    local sourceSpell = SB.Data.Spells[spellID]

    -- Называем ЗАКЛИНАНИЕ, а не эффект: ссылка кликабельна, и в карточке
    -- написано, что именно она вешает. Имя эффекта в строке было
    -- пересказом того же самого — только без возможности прочитать
    -- подробности.
    local what = sourceSpell and SB.UI.MakeSpellLink(sourceSpell)
                 or (SB.Theme.MSG_BODY .. "заклинание|r")
    local who  = SB.Theme.MSG_BODY .. (casterName or "Кто-то") ..
                 " применяет на вас |r" .. what

    if total == nil then
        -- fromOther: каст чужой, концентрацию держит заклинатель.
        -- casterName, а не sender: провокацию мог наложить и НПС от лица
        -- Ведущего, и цель приковано именно к существу, а не к тому, чей
        -- клиент прислал пакет.
        SB.Logic.ApplyEffect(effectID, sourceSpell, slotLevel, true, extraTurns,
                             casterName)
        print(SB.Theme.MSG_TAG .. "[Spellbreaker]|r: " .. who)
        return
    end

    -- Та же сверка, что у ПвП-удара и площадного эффекта: порог берёт
    -- присланный итог, и завышенный итог навязал бы эффект в обход броска.
    local tamperNote
    total, tamperNote = SB.Logic.VerifyIncomingCast(sender or casterName,
        spellID, roll, mod, total, slotLevel)
    if tamperNote then
        print(SB.Theme.MSG_BAD .. "[Spellbreaker]: " .. (sender or casterName or "?") ..
            " — цифры не сходятся: " .. tamperNote .. ".|r")
    end

    -- ЧЕМ СОПРОТИВЛЯЕМСЯ — СПРАШИВАЕМ У СЕБЯ. Заклинатель этих чисел не
    -- знает и знать не может: игровое API отдаёт про цель уровень, но не
    -- характеристики. Раньше их везли отдельным полем статуса — лишняя
    -- работа ради решения, которое всё равно принимается здесь.
    local isDebuff  = sourceSpell and sourceSpell.debuff == effectID
    local resistMod = isDebuff
        and SB.Logic.OwnResistMod(SB.Logic.DebuffResistStat(effectID, sourceSpell))
        or 0
    local threshold = SB.Logic.EffectThreshold("player", isDebuff, false, resistMod)
    -- Определение заклинания у нас своё, из библиотеки, — «без
    -- сопротивления» проверяем сами, а не верим присланным числам.
    local ok = SB.Logic.IsGuaranteed(sourceSpell) or (total >= threshold)

    if ok then
        SB.Logic.ApplyEffect(effectID, sourceSpell, slotLevel, true, extraTurns,
                             casterName)
    end

    -- СТРОКУ ПИШЕТ ЗАКЛИНАТЕЛЬ, А НЕ МЫ. Здесь стояла своя печать —
    -- «Зольц применяет на вас [Проклятие Тьмы]: [56][+28]=84 против 99.
    -- Провал.», — и это была вторая копия того же события: порог и исход
    -- уезжают ответом (SendBuffResult), заклинатель дожидается их и
    -- печатает ОДНУ строку на всю группу, с теми же числами
    -- (см. Announce в ProcessRollAndCast). Локальная при этом в лог не
    -- попадала вовсе — то есть в чате двоилось, а в логе оставалось одно.
    --
    -- Потеряться строка не может: BUFF с броском шлётся только внутри
    -- группы (SB.Net.SendBuff начинается с IsInGroup), а значит и
    -- общая строка заклинателя до нас дойдёт.
    if SB.Net and SB.Net.SendBuffResult then
        SB.Net.SendBuffResult(sender or casterName, spellID, threshold, ok)
    end
end

-- ============================================================
-- Склонение имени цели (ruRU)
-- Возвращает таблицу всех шести падежей.
-- На enUS или если для имени нет данных — все падежи = оригинал.
-- ============================================================
local function DeclineUnitName(name, gender)
    local f = { gen=name, dat=name, acc=name, ins=name, pre=name, nom=name }
    if DeclineName and GetNumDeclensionSets then
        local sets = GetNumDeclensionSets(name, gender)
        if sets and sets > 0 then
            local gen,dat,acc,ins,pre,nom = DeclineName(name, gender, 1)
            f.gen = gen or name
            f.dat = dat or name
            f.acc = acc or name
            f.ins = ins or name
            f.pre = pre or name
            f.nom = nom or name
        end
    end
    return f
end

-- Публичная обёртка — тем же алгоритмом склонения пользуются и другие
-- файлы (например ResourceGrant.lua для сообщения «кому выдали ресурс»),
-- не дублируя логику работы с DeclineName/GetNumDeclensionSets.
function SB.Logic.DeclineName(name, gender)
    return DeclineUnitName(name, gender)
end
 
-- ============================================================
-- Подстановка плейсхолдеров цели в текст отписи. (Работает странно)
--
--   {target} / {target_nom} — именительный  (кто?)   «Горный Тролль»
--   {target_gen}            — родительный   (кого?)  «Горного Тролля»
--   {target_dat}            — дательный     (кому?)  «Горному Троллю»
--   {target_acc}            — винительный   (кого?)  «Горного Тролля»
--   {target_ins}            — творительный  (кем?)   «Горным Троллем»
--   {target_pre}            — предложный    (о ком?) «Горном Тролле»
--
-- Если цели нет — все плейсхолдеры заменяются на «цель».
-- ============================================================
local function ApplyTemplates(text)
    if not text then return "" end
    if pendingTargetName == "" then
        text = text:gsub("{target_nom}", "цель")
        text = text:gsub("{target_gen}", "цели")
        text = text:gsub("{target_dat}", "цели")
        text = text:gsub("{target_acc}", "цель")
        text = text:gsub("{target_ins}", "целью")
        text = text:gsub("{target_pre}", "цели")
        text = text:gsub("{target}",     "цель")
        return text
    end
    local f = DeclineUnitName(pendingTargetName, pendingTargetGender)
    text = text:gsub("{target_nom}", f.nom)
    text = text:gsub("{target_gen}", f.gen)
    text = text:gsub("{target_dat}", f.dat)
    text = text:gsub("{target_acc}", f.acc)
    text = text:gsub("{target_ins}", f.ins)
    text = text:gsub("{target_pre}", f.pre)
    text = text:gsub("{target}",     f.nom)
    return text
end

--- Отпись по итогу заклинания: взять текст из своих отписей, подставить
--- склонения цели и отправить эмоутом. Публичная, потому что нужна
--- резолву, который живёт в другом файле (площадное лечение,
--- Core/Logic/Aoe.lua), а ApplyTemplates — локальная и такой останется.
function SB.Logic.SendOutcomeEmote(spellID)
    local text = SB.SpellOutcomes and SB.SpellOutcomes.Get(spellID)
    if not text or text == "" then return end
    if SpellbreakerAccountDB and SpellbreakerAccountDB.sendEmotes == false then return end
    SendChatMessage(ApplyTemplates(text), "EMOTE")
end

-- ============================================================
-- ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ
-- ============================================================

-- ============================================================
-- ПРОВЕРКА ДАЛЬНОСТИ
-- ============================================================

-- ============================================================
-- ПРОВЕРКА НАВЫКА / АТРИБУТА
-- Свободный бросок «на характеристику», не привязанный к заклинанию:
-- бросок кубика + модификатор самой характеристики + бонус за уровень
-- персонажа. Мастерство сюда НЕ входит — это ранг заклинателя, к
-- проверке Атлетики или Скрытности он отношения не имеет.
-- ============================================================

--- @param key string  Имя атрибута ИЛИ навыка (SB.Attributes.Get
---                    полиморфен и принимает оба).
function SB.Logic.RollCheck(key)
    if not key then return end
    -- Свободный бросок хода не тратит, и удержать его темп больше нечем:
    -- без счётчика проверка навыка нажимается сколько угодно раз подряд,
    -- и каждая уходит в групповой канал (см. Core/Cooldowns.lua).
    if SB.Cooldowns and not SB.Cooldowns.Check(SB.Cooldowns.ROLL) then return end
    if SB.Cooldowns then SB.Cooldowns.Start(SB.Cooldowns.ROLL) end

    local roll      = SB.Logic.Roll()
    local levelMod  = SB.PlayerModel.GetLevelModifier()

    local isSkill = SB.Skills and SB.Skills.IsSkillKey and SB.Skills.IsSkillKey(key)
    local kindTxt = isSkill and "навык" or "атрибут"

    -- ПРОВЕРКА НАВЫКА СЧИТАЕТ И ЕГО АТРИБУТ (см. SB.Skills.GetCheckModifier).
    -- У атрибута родителя нет, и там эта же функция вернёт его собственный
    -- модификатор без прибавок — развилки на два случая здесь не нужно.
    local statMod, skillMod, attrMod = key, 0, 0
    if SB.Skills and SB.Skills.GetCheckModifier then
        statMod, skillMod, attrMod = SB.Skills.GetCheckModifier(key)
    else
        statMod = SB.Attributes.GetModifier(key)
    end
    local total = roll + statMod + levelMod

    -- Разбивку собираем вручную (а не через реестр модификаторов) —
    -- у проверки характеристики свой состав слагаемых, и подмешивать
    -- сюда боевые источники было бы неверно.
    --
    -- key первого слагаемого — само имя характеристики, а не служебное
    -- "stat": подпись ищется через SB.Logic.ModifierSources[key] с
    -- фолбэком на сам ключ, а для характеристики источника в реестре
    -- нет — значит фолбэк обязан быть человекочитаемым.
    -- РАЗБИВКА ИДЁТ В САМУ СТРОКУ, а не в подсказку на числе.
    --
    -- Раньше она собиралась здесь и не читалась никем: строка показывала
    -- готовое «+48», и откуда оно взялось, узнать было негде. С тех пор
    -- как проверка навыка складывает ТРИ слагаемых (свой навык, его
    -- атрибут, уровень), это перестало быть мелочью: игрок видит число,
    -- которое не сходится ни с одной цифрой в его листе.
    --
    -- Печатаем ТОЛЬКО ненулевые и только когда их больше одного: у
    -- нетронутого навыка на первом уровне слагаемое одно, и скобка
    -- «(Сила +12)» рядом с «+12» — это шум.
    local parts = {}
    local function Part(label, value)
        if value ~= 0 then
            parts[#parts + 1] = string.format("%s %s%d", label,
                (value > 0) and "+" or "", value)
        end
    end
    Part(key, skillMod)
    if isSkill then Part(SB.Skills.ParentOf(key) or "", attrMod) end
    Part("уровень", levelMod)
    local partsTxt = (#parts > 1)
        and (SB.Theme.MSG_BODY .. " (" .. table.concat(parts, ", ") .. ")|r") or ""

    local G        = SB.Theme.MSG_BODY
    local modLink  = SB.UI.ModText(statMod + levelMod)
    local rollLink = SB.UI.RollText(roll)

    -- ВНИМАНИЕ на баланс |c…|r: каждый открытый цвет обязан быть закрыт.
    -- В первой версии этой строки оставалось ДВА незакрытых кода, и цвет
    -- перетекал на все последующие сообщения окна логов — то самое
    -- «закрашивание» кусков лога.
    local msg = SB.Theme.MSG_TAG .. "[Spellbreaker]:|r " ..
        G .. UnitName("player") .. " проверяет " .. kindTxt .. " |r" ..
        "|cFFFFD100" .. key .. "|r" ..
        G .. ": |r" .. rollLink ..
        G .. " + |r" .. modLink ..
        G .. " = |r" .. "|cFFFFD100" .. total .. "|r" .. partsTxt

    SB.Events.Fire(SB.E.BROADCAST_LOG, msg, SB.LogRank.ACTION)
    return total, roll, statMod + levelMod
end

-- ============================================================
-- ЧТО ЭТО ЗАКЛИНАНИЕ ДАЁТ ИМЕННО ЭТОМУ ПЕРСОНАЖУ
--
-- Раньше карточка перечисляла ИСТОЧНИКИ: «Атака: Дух, Религия», «Урон:
-- Дух x1.5». Формально это правда, а практически — задача на дом: чтобы
-- узнать, что выйдет при касте, игрок должен был знать свои значения,
-- шаг очка за характеристику и множитель круга, и всё это перемножить.
-- Коэффициенты x1.5 при этом ничего ему не говорили: они относятся к
-- внутреннему шагу, которого в интерфейсе нет нигде.
--
-- Теперь строка показывает ИТОГ, а источники уходят в скобки — это то,
-- что игрок действительно хочет знать, и то, что он всё равно
-- пересчитывал в уме:
--
--     Атака: 15 (Религия + Дух)
--     Крит: 14% (Меткость)
--     Лечение: 2 (Дух)
--
-- Числа — как при касте В СВОЙ КРУГ, без вливания сверху: это базовый
-- случай, а прибавку от вливания игрок и так видит прямо в окне выбора
-- круга (см. GainTag в UI/MainFrame.lua).
--
-- «Атака» — ПОЛНЫЙ модификатор броска (ранг, уровень, навыки, скейлинг,
-- висящие баффы), то есть ровно то число, которое ляжет рядом с кубиком.
-- Скобки при этом называют только собственные характеристики
-- заклинания: остальные слагаемые одинаковы для всех его заклинаний и
-- в карточке были бы шумом.
-- ============================================================
--- Имена характеристик канала, готовой подписью «Религия + Дух».
--- @return string|nil  nil — у канала нет источников вовсе
local function ScalingSourceNames(spell, channel)
    local sources = spell.scaling and spell.scaling[channel]
    if sources == nil then
        sources = spell.attributes and spell.attributes[channel]
    end
    if type(sources) == "string" then sources = { [sources] = 1 } end
    if type(sources) ~= "table" then return nil end

    local names = {}
    for statKey, coeff in pairs(sources) do
        if (tonumber(coeff) or 0) ~= 0 then names[#names + 1] = statKey end
    end
    if #names == 0 then return nil end
    table.sort(names)   -- pairs() непредсказуем, подписи не должны прыгать
    return table.concat(names, " + ")
end

--- Шанс крита в процентах для ТЕКУЩЕГО персонажа с этим заклинанием.
--- Считается от той же полосы, что и в бою (см. GetCritThreshold), и по
--- реальному диапазону кубика: расовый пол броска сужает число граней, и
--- без него процент врал бы.
function SB.Logic.GetCritChance(spell)
    local lo, hi   = SB.Logic.GetRollRange()
    local faces    = hi - lo + 1
    if faces <= 0 then return 0 end
    local critBonus = SB.Logic.GetSpellScaling(spell, "crit")
    local threshold = math.max(lo, SB.Logic.GetCritThreshold(critBonus, hi))
    return (hi - threshold + 1) / faces * 100
end

--- @return string[]  По строке на канал, у которого есть что показать.
---                    Пустой список — заклинание ничего не считает.
function SB.Logic.GetSpellScalingLines(spell)
    local lines = {}
    if not spell then return lines end

    -- Круг самого заклинания: «сколько будет, если применить как
    -- обычно». Ноль у заговоров — тоже честный круг.
    local slot = tonumber(spell.level) or 0

    local function Line(label, value, sources)
        lines[#lines + 1] = string.format("|cFFFFD100%s:|r %s%s",
            label, value, sources and (" (" .. sources .. ")") or "")
    end

    -- ── Атака ───────────────────────────────────────────────
    -- Полный модификатор броска. Показываем даже без собственного
    -- скейлинга: ранг и уровень персонаж вкладывает в КАЖДОЕ заклинание,
    -- и знать итог он хочет для каждого.
    -- «БЕЗ СОПРОТИВЛЕНИЯ» — ЗНАЧИТ БРОСКА НЕТ ВОВСЕ, и число здесь врёт.
    --
    -- Модификатор атаки показывался всем подряд, включая заклинания с
    -- resistable = false. У них бросок не катится (см. SB.Logic.IsGuaranteed):
    -- они попадают всегда. Строка «Атака: 42» на таком заклинании
    -- обещает состязание, которого не будет, и заставляет игрока
    -- сравнивать своё число с чужой защитой — впустую.
    if SB.Logic.IsGuaranteed(spell) then
        Line("Атака", SB.Theme.MSG_GOOD .. "Автоуспех|r")
    else
        local atk = SB.Logic.GetCastModifier(spell, slot)
        Line("Атака", tostring(atk), ScalingSourceNames(spell, "hit"))
    end

    -- ── Крит ────────────────────────────────────────────────
    -- Только там, где крит вообще бывает: удары и лечение. У чистого
    -- баффа полоса крита есть в формулах, но не срабатывает никогда, и
    -- строка о ней была бы обещанием того, чего не будет.
    if spell.canCrit or SB.Logic.IsHealingCast(spell) then
        Line("Крит", string.format("%.0f%%", SB.Logic.GetCritChance(spell)),
             ScalingSourceNames(spell, "crit"))
    end

    -- ── Урон или Лечение ────────────────────────────────────
    local dmgSources = ScalingSourceNames(spell, "damage")
    if spell.isHeal then
        local base = SB.Logic.GetHealPower(spell, slot)
        -- Тем же ответом, что уйдёт в резолв: карточка обязана показывать
        -- то, что персонаж реально вылечит (см. SB.Logic.GetHealBonus).
        local eff  = SB.Logic.GetHealBonus()
        local sum  = base + SB.Logic.GetSpellScaling(spell, "damage", slot) + eff
        Line("Лечение", tostring(math.max(0, sum)), dmgSources)
    elseif spell.canCrit or dmgSources then
        -- (ветка урона ниже)
        local base = SB.Logic.GetCastPower(spell, slot)
        -- Та же школьная прибавка, что уйдёт в бросок: карточка обязана
        -- показывать то, что персонаж реально нанесёт, а «+2 огню» на
        -- ледяной стреле не работает.
        local eff  = (SB.ActiveEffects and SB.ActiveEffects.GetDamageMod)
            and (SB.ActiveEffects.GetDamageMod(spell)) or 0
        local sum  = base + SB.Logic.GetSpellScaling(spell, "damage", slot) + eff
        -- Тот же пол, что и в резолве: попавший удар не стоит ноль
        -- (см. Config.MinDamageOnHit). Без него карточка обещала бы
        -- «Урон: 0» там, где удар снимет единицу.
        local shown = tostring(math.max(SB.Data.Config.MinDamageOnHit or 1, sum))

        -- ТИП УРОНА — ЦВЕТОМ И СЛОВОМ СРАЗУ (см. Core/DamageTypes.lua).
        --
        -- Цвета одного мало, и дело не в придирчивости. Семь школ, а
        -- различимых оттенков среди них меньше: тайная магия и тьма обе
        -- лиловые, огонь и Свет обе тёплые. Плюс каждый двенадцатый
        -- мужчина не различает часть из них вовсе. Подпись рядом с
        -- числом снимает вопрос целиком, а цвет остаётся тем, ради чего
        -- он и нужен, — по нему тип видно, не читая.
        --
        -- НЕТ ТИПА — «ЧИСТЫЙ», а не пустое место: такой урон не гасит
        -- ни одно сопротивление, и узнать об этом игрок должен здесь, до
        -- того, как положится на свой резист (см. SB.Data.PURE_DAMAGE).
        local dt = SB.Data.GetDamageType and SB.Data.GetDamageType(spell)
        if dt then
            shown = SB.Data.ColorByDamageType(dt, shown .. " — " .. dt.name)
        end
        Line("Урон", shown, dmgSources)
    end

    -- ── Починка доспеха ─────────────────────────────────────
    -- Своей строкой, а не в «Лечении»: шкала другая (единицы брони, где
    -- десятка = один вычтенный из удара урон), и складывать их в одно
    -- число значило бы обещать здоровье там, где чинят железо.
    local repair = SB.Logic.GetSpellRepair(spell, slot)
    if repair > 0 then
        local perDR = SB.Data.ArmorPerDR or 10
        Line("Броня", string.format("+%d ед. (%d урона)", repair,
            math.floor(repair / perDR)), ScalingSourceNames(spell, "armor"))
    end

    -- Вампиризм — там же: это тоже правило про числа заклинания, а не
    -- про его описание (см. SB.Logic.GetLeechShare).
    local leech = SB.Logic.GetLeechShare(spell)
    if leech > 0 then
        Line("Вампиризм", string.format("%g%% нанесённого урона", leech * 100))
    end

    -- ── Рассеивание ─────────────────────────────────────────
    -- СКОЛЬКО И ЧЕГО — на самой карточке. Числа не было нигде: круг
    -- заклинания игрок видит, а правило «снимает столько, какой круг»
    -- (см. GetDispelCount) держать в голове не обязан, и школы —
    -- единственное, что отличает «Очищение» от «Рассеивания магии», —
    -- лежали только в данных.
    local schools = SB.Logic.GetDispelSchools and SB.Logic.GetDispelSchools(spell)
    if schools then
        local names = {}
        for key in pairs(schools) do
            local info = SB.Data.EffectSchools and SB.Data.EffectSchools[key]
            names[#names + 1] = (info and info.label) or key
        end
        table.sort(names)   -- pairs() непредсказуем, подписи не прыгают
        local n = SB.Logic.GetDispelCount(spell, slot)
        local word = "эффектов"
        if n % 10 == 1 and n % 100 ~= 11 then
            word = "эффект"
        elseif n % 10 >= 2 and n % 10 <= 4 and (n % 100 < 12 or n % 100 > 14) then
            word = "эффекта"
        end
        Line("Рассеивает", string.format("%d %s", n, word), table.concat(names, ", "))
    end

    -- ── Что каст делает с самим заклинателем (onCast) ───────
    -- Канал был у резолва с самого начала, а у карточки его не было:
    -- «Удар щитом» чинит пятнадцать брони и не говорил об этом ни
    -- слова, «Жизнеотвод» платит кровью — тоже молча. Собирает строку
    -- та же функция, что и карточка эффекта: формат выплаты один на
    -- оба места (см. SB.ActiveEffects.PayloadText).
    --
    -- БЕЗ ШКОЛЫ УРОНА, и это не упущение: своя цена не сопротивляется
    -- (ApplyPayload зовётся не через "tick"), и подпись «(Тьма)» на
    -- ней обещала бы резист, которого нет.
    local castTxt = SB.ActiveEffects and SB.ActiveEffects.PayloadText
        and SB.ActiveEffects.PayloadText(spell.onCast)
    if castTxt then Line("При применении", castTxt) end

    return lines
end

-- ============================================================
-- ДИАПАЗОН КУБИКА
--
-- КУБИК ВСЕГДА d100. Верхняя грань зафиксирована и не настраивается.
--
-- Раньше границы брались из настроек аккаунта (rollMin/rollMax), чтобы
-- Ведущий мог перевести стол на d20 или любую другую шкалу. На практике
-- это оказалось не гибкостью, а дырой: вся система порогов, критов и
-- модификаторов откалибрована под сотню (СЛ, полоса крита, шаг навыка
-- в 3, пороги эффектов 60+уровень), и сдвиг верхней грани ломал их все
-- разом. Хуже того, настройка была ЛИЧНОЙ и по сети не ехала — то есть
-- игрок мог поменять её себе и выглядеть удачливее остальных, а со
-- стороны это неотличимо от мухлежа.
--
-- Единственное, что осталось подвижным, — НИЖНЯЯ грань, и она приходит
-- не из настроек, а из расы или класса (rollFloor). Она не прибавляет к
-- результату, а СРЕЗАЕТ САМЫЕ НЕУДАЧНЫЕ грани: Орк с полом 6 бросает
-- 6-100 — в среднем чуть выше, и глухих провалов у него меньше.
--
-- Почему пол, а не «+2 к броску»: на итог и без того влияют ранг,
-- уровень, характеристики, вложенный ресурс, профиль класса, навыки и
-- висящие эффекты. Ещё одно слагаемое там ничего не выражало бы.
-- ============================================================
SB.Logic.ROLL_MAX = 100

-- ============================================================
-- ПРОВЕРКА ЧУЖОГО КАСТА
--
-- Никакая ПОДСКАЗКА защитой не была и быть не может: числа в ней рисует
-- тот же клиент, что и присылает их. Ни оранжевая ссылка на бросок с
-- гранями, ни синяя на модификатор с разбивкой ничего не проверяли —
-- подделав удар, модифицированный клиент подделал бы и обе подсказки.
--
-- Проверять надо не то, что атакующий О СЕБЕ РАССКАЗАЛ в этом же
-- пакете, а то, что о нём ЗАРАНЕЕ ИЗВЕСТНО ИЗ ДРУГОГО ИСТОЧНИКА. Такой
-- источник есть: STATUS, который каждый рассылает группе постоянно и
-- независимо от боя (SB.Data.PlayersStatus). Оттуда видны класс, ранг,
-- запас ресурса и список подготовленных заклинаний — и по ним ловится
-- то, что раньше не ловилось вовсе:
--
--   • удар заклинанием, которое атакующий НЕ ПОДГОТОВИЛ;
--   • круг заклинания выше того, что открыт его РАНГОМ (и на круг ниже
--     для чужой школы — то же правило мультикласса, что у нас самих);
--   • вложено ресурса больше, чем у него есть МАКСИМУМ.
--
-- Плюс то, что проверялось и раньше и не требует ничего чужого:
-- бросок обязан лежать на кубике, а итог — быть суммой броска и
-- модификатора.
--
-- Подделать это уже не «поправить одно число»: пришлось бы согласованно
-- врать ещё и в фоновом STATUS, который видит вся группа и Ведущий —
-- причём врать ЗАРАНЕЕ, до боя.
--
-- Сеть от замены не выросла, а сократилась: разбивка modParts, на
-- которой держалась прежняя проверка, больше не отправляется вовсе.
--
-- @param attacker string|nil  имя атакующего (ключ в PlayersStatus)
-- @param spellID  string|nil  чем бьёт
-- @param roll  number|nil  бросок кубика
-- @param mod   number|nil  заявленный модификатор
-- @param total number|nil  заявленный итог
-- @param slot  number|nil  сколько ресурса вложено
-- @return number total  итог, которому можно верить
-- @return string|nil note  человекочитаемая претензия (nil — всё сошлось)
-- ============================================================
-- ============================================================
-- ПОТОЛКИ: ЧТО ВООБЩЕ МОЖЕТ ПРИЛЕТЕТЬ ЧЕСТНО
--
-- Сверка броска ловила ровно две вещи: кубик вне диапазона и итог, не
-- равный сумме. Всё остальное в пакете принималось на веру — а именно
-- там и лежат числа, которыми бьют: модификатор, база урона и скейлинг.
-- Подменённый клиент присылал «+100 урона», и получатель послушно
-- отнимал сотню здоровья.
--
-- ЧТО МОЖНО ПРОВЕРИТЬ ТОЧНО. База урона — чистая функция заклинания и
-- вложенного круга (SB.Logic.GetCastPower), а оба они едут в том же
-- пакете. Тут не потолок, а равенство: любое расхождение — подлог.
--
-- ЧТО НЕЛЬЗЯ — И ЧТО ДЕЛАЕМ ВМЕСТО. Скейлинг и модификатор считаются от
-- характеристик атакующего, а их у нас нет и быть не может. Зато можно
-- посчитать ПОТОЛОК: сколько получил бы персонаж, у которого всё
-- выкручено на максимум. Честный игрок под него не подпадает никогда, а
-- «+100» подпадает сразу.
--
-- ПОТОЛОК НАРОЧНО ЩЕДРЫЙ. Эффекты поднимают характеристики выше предела
-- вложения, и потолок обязан это учитывать — иначе он ловил бы не
-- мухлёж, а удачный бафф. Цель тут не «поймать на единице», а отсечь
-- порядок величины: тот, кто крутит числа, крутит их не на единицу.
--
-- И ГЛАВНОЕ — ЗАЖИМАЕМ, А НЕ ОТБРАСЫВАЕМ. Отброшенный удар для
-- атакующего выглядит как попадание: он видит свой бросок и свою строку.
-- Зажатый до законного максимума удар доходит, урон считается по
-- правилам, а в общей строке боя стоит пометка — её видят все.
-- ============================================================

-- Насколько выше предела вложения эффекты вправе поднять характеристику
-- для целей ПОТОЛКА. Не механика, а запас прочности.
--
-- ЧЕТЫРЕ, А НЕ ДЕСЯТЬ, и это правка по замеру. С десяткой потолок для
-- «Проверочного удара» выходил 156 при настоящем максимуме в 42 — то
-- есть вчетверо, и накрутка на сотню под него спокойно подпадала.
-- Смысл потолка в том, чтобы честный максимум под него не подпадал, а
-- всё, что заметно выше, — подпадало; вчетверо это уже не потолок, а
-- декорация. Реальные баффы библиотеки дают единицы.
local CEILING_STAT_HEADROOM = 4

--- Чем мерить характеристику, когда считаем потолок: всё на максимуме.
local function CeilingStat()
    local maxAttr = (SB.Attributes.GetMaxValue and SB.Attributes.GetMaxValue()) or 5
    local cap = maxAttr + CEILING_STAT_HEADROOM
    return function() return cap end
end

--- Наибольший модификатор атаки, какой вообще может быть у игрока.
---
--- Складываем максимумы всех слагаемых, а не спрашиваем реестр
--- источников: реестр считает по НАШЕМУ персонажу, а нужен потолок по
--- чужому, о котором мы почти ничего не знаем.
function SB.Logic.MaxPlausibleAttackMod(spell)
    local cfg  = SB.Data.Config
    local step = cfg.SkillRollStep or 3
    local maxAttr = (SB.Attributes.GetMaxValue and SB.Attributes.GetMaxValue()) or 5
    local cap = maxAttr + CEILING_STAT_HEADROOM

    -- Ранг школы: наибольшая прибавка из таблицы рангов.
    local rank = 0
    for _, v in pairs(cfg.Modifiers or {}) do
        if (tonumber(v) or 0) > rank then rank = tonumber(v) end
    end

    -- Уровень: на потолке реалма.
    local lvl = SB.PlayerModel.LevelModifierFor
        and SB.PlayerModel.LevelModifierFor(SB.Data.ToReferenceLevel(
                (SB.Data.GetRealm() or {}).maxLevel or 25)) or 0

    -- Скейлинг самого заклинания в канале hit — по его же коэффициентам,
    -- но с характеристиками на максимуме.
    local hit = SB.Logic.GetSpellScaling(spell, "hit", nil, CeilingStat())

    -- Навыки, влияющие на бросок («Внушение» и родня), и профиль класса
    -- одним слагаемым: их несколько, шаг у всех общий, а точность здесь
    -- и не нужна. ОДНА порция, а не две: сложенные вдвое, они и раздували
    -- потолок вчетверо против настоящего максимума.
    local skills = step * (cap - (SB.Data.STAT_BASE or 0))

    -- Висящие эффекты канала attack. Конкретных чисел чужих баффов мы не
    -- знаем, но и десятикратного запаса им не надо.
    local effects = step * 3

    -- Оружие канала attack (топоры в обеих руках).
    local weapon = SB.Logic.MaxWeaponBonus("attack")

    return math.floor(rank + lvl + hit + skills + effects + weapon)
end

--- Самый низкий кубик, на котором крит МОЖЕТ случиться у кого угодно.
---
--- ЗАЧЕМ ОТДЕЛЬНАЯ ПРОВЕРКА. Крит теперь не только удваивает урон, но и
--- пробивает защиту без броска (см. HandlePvpAttackReceived), а флаг
--- крита считает АТАКУЮЩИЙ и присылает готовым: своего скейлинга канала
--- crit он нам не показывает, и проверить число в лоб нечем. Зато есть
--- потолок полосы (Config.CritBandMaxPct) — выше него полоса не растёт
--- ни от чего, а значит крит на кубике ниже этой грани не бывает ни у
--- кого. Тот же приём и тот же довод, что у MaxPlausibleAttackMod:
--- ловим не ложь, а невозможное.
--- @param rollMax number|nil  верхняя грань кубика (по умолчанию 100)
function SB.Logic.MinPlausibleCritRoll(rollMax)
    rollMax = tonumber(rollMax) or SB.Logic.ROLL_MAX or 100
    local capPct = tonumber(SB.Data.Config.CritBandMaxPct) or 25
    return rollMax - math.floor(rollMax * capPct / 100) + 1
end

--- Наибольший урон, какой заклинание может нанести честно.
--- @return number base, number bonus
function SB.Logic.MaxPlausibleDamage(spell, slot)
    local base = SB.Logic.GetCastPower(spell, slot)
    local bonus = SB.Logic.GetSpellScaling(spell, "damage", slot, CeilingStat())
    -- Запас на висящие эффекты канала damage — той же щедрой рукой.
    return base, math.floor(bonus + CEILING_STAT_HEADROOM)
end

--- СВЕРКА ЧИСЕЛ УДАРА. Возвращает выправленные значения и претензию.
---
--- Зовётся у ЗАЩИЩАЮЩЕГОСЯ — единственной стороны, которой подлог не
--- выгоден (то же правило, что у SB.Logic.VerifyIncomingCast).
--- @param fromNpc boolean|nil  удар нанесло СУЩЕСТВО.
---        Потолки к нему не применяются, и это не поблажка, а разные
---        источники доверия. Потолок считается от предела вложения
---        ИГРОКА (пять очков в характеристику); у существа предела нет —
---        рейдовому боссу Ведущий ставит хоть девяносто девять, ради
---        того цифры и открыты. А сам пакет от лица существа принимается
---        только от лидера (см. ActorOf в Core/Network.lua), то есть от
---        того, кто эти цифры и назначил: зажимать их своим потолком
---        значило бы спорить с автором сцены.
--- @return number base, number bonus, string|nil note
function SB.Logic.VerifyIncomingDamage(spell, slot, baseDmg, dmgBonus, fromNpc)
    if not spell or fromNpc then return baseDmg, dmgBonus, nil end

    local okBase, ceilBonus = SB.Logic.MaxPlausibleDamage(spell, slot)
    local base  = tonumber(baseDmg)  or okBase
    local bonus = tonumber(dmgBonus) or 0
    local notes = nil

    -- База — РАВЕНСТВО, а не потолок: она считается из заклинания и
    -- круга, и обе величины приехали в том же пакете.
    if base ~= okBase then
        notes = string.format("база урона %d вместо %d", base, okBase)
        base = okBase
    end

    if bonus > ceilBonus then
        local extra = string.format("скейлинг %d при потолке %d", bonus, ceilBonus)
        notes = notes and (notes .. "; " .. extra) or extra
        bonus = ceilBonus
    end

    -- Отрицательный скейлинг законен: характеристику могли увести в
    -- минус дебаффом (см. врезку о значениях ниже единицы в
    -- Core/Skills.lua). Пола тут нет намеренно.
    return base, bonus, notes
end

--- @param fromNpc boolean|nil  бьёт существо: потолок модификатора не
---        применяется по той же причине, что и потолок урона
---        (см. SB.Logic.VerifyIncomingDamage).
function SB.Logic.VerifyIncomingCast(attacker, spellID, roll, mod, total, slot, fromNpc)
    roll  = tonumber(roll)  or 0
    mod   = tonumber(mod)   or 0
    total = tonumber(total) or 0
    slot  = tonumber(slot)  or 0

    -- Бросок обязан лежать на кубике. Нижнюю грань не проверяем: у
    -- атакующего мог быть расовый пол (Орк бросает 6-100), и его
    -- значение нам не известно — а вот выйти за сотню или уйти ниже
    -- единицы честный бросок не может никак.
    if roll < 1 or roll > SB.Logic.MaxPlausibleRoll() then
        return roll + mod, string.format("бросок вне кубика (%d)", roll)
    end

    -- Итог обязан быть суммой броска и модификатора.
    if total ~= roll + mod then
        return roll + mod, string.format(
            "итог не сходится (%d против %d)", total, roll + mod)
    end

    -- МОДИФИКАТОР — ПРОТИВ ПОТОЛКА. Сумма сходилась и раньше: подменённый
    -- клиент присылал согласованную тройку с «модификатором» в сотню, и
    -- проверка её пропускала, потому что арифметика в ней честная.
    -- Потолок считается от правил, а не от слов атакующего
    -- (см. SB.Logic.MaxPlausibleAttackMod).
    local spellForCap = (not fromNpc) and spellID and SB.Data.Spells[spellID]
    if spellForCap then
        local capMod = SB.Logic.MaxPlausibleAttackMod(spellForCap)
        if mod > capMod then
            return roll + capMod, string.format(
                "модификатор %d при потолке %d", mod, capMod)
        end
    end

    -- Дальше — сверка с фоновым статусом. Его может не быть: игрок
    -- только вошёл в группу, или у него старая сборка. Отсутствие
    -- данных претензией НЕ считаем — иначе каждый новичок выглядел бы
    -- мухлюющим первые несколько секунд.
    local st = SB.Data.PlayersStatus and attacker and SB.Data.PlayersStatus[attacker]
    if not st then return total, nil end

    local spell = spellID and SB.Data.Spells[spellID]

    -- Подготовлено ли. Контейнеры (эффекты, держатели потоков) в списке
    -- подготовленных не лежат по определению — их не готовят.
    if spell and not spell.isContainer and type(st.preparedSpells) == "table" then
        local found = false
        for _, id in ipairs(st.preparedSpells) do
            if id == spellID then found = true; break end
        end
        if not found then
            return total, string.format("заклинание «%s» не подготовлено",
                spell.name or spellID)
        end
    end

    -- ============================================================
    -- КРУГ ПРОТИВ РАНГА — ПО РАНГУ ТОЙ ШКОЛЫ, ЧЬЁ ЗАКЛИНАНИЕ
    --
    -- Здесь стояло прежнее правило мультикласса: своя школа по рангу
    -- героя, чужая на круг ниже. С тех пор как ранг разъехался по
    -- школам, оно даёт ЛОЖНЫЕ ОБВИНЕНИЯ — а они печатаются публично, в
    -- общую строку боя. Жрец-неофит с паладинской вещью эксперта
    -- законно кастует паладинский третий круг, а проверка по его
    -- собственному рангу объявляет это мухлежом при всех.
    --
    -- Теперь ранги открытых школ приезжают в самом статусе
    -- (см. PM.PackClassRanks). Проверка от этого не стала строже: всё в
    -- статусе игрок сообщает о себе сам, и ловит она не ложь, а
    -- НЕСОГЛАСОВАННОСТЬ — «сказал одно, ударил по другому». Тем же она
    -- была и раньше.
    --
    -- СТАРЫЙ КЛИЕНТ РАНГОВ НЕ ПРИСЫЛАЕТ. Тогда проверяем по потолку
    -- реалма — это ловит только явную нелепицу («пятый круг там, где
    -- рангов три»), зато не обвиняет honest-игрока за чужую сборку.
    -- ============================================================
    if spell then
        local lvl  = tonumber(spell.level) or 0
        local cls  = spell.class
        local cap, capName

        local known = st.classRanks and cls and st.classRanks[cls]
        if known then
            capName = SB.Data.Masteries[known]
            cap     = SB.Data.MaxOrderFor(capName)
        elseif st.classRanks and cls and SB.Data.IsRealClass(cls) then
            -- Ранги прислал, но этой школы среди них нет — школа ему не
            -- открыта вовсе, и заклинание он применить не мог.
            --
            -- Только для НАСТОЯЩЕЙ школы из списка: у кастомного
            -- заклинания Ведущего в class может стоять что угодно
            -- («Проверка», «Эффект», выдуманное имя), и такому мы про
            -- «не открыта» ничего сказать не можем.
            return total, string.format("школа «%s» ему не открыта", cls)
        else
            capName = SB.Data.GetMaxMastery()
            cap     = SB.Data.MaxOrderFor(capName)
        end

        if lvl > cap then
            return total, string.format("круг %d недоступен рангу «%s»", lvl, capName)
        end
        if slot > cap then
            return total, string.format("вложено %d при потолке %d", slot, cap)
        end
    end

    -- Вложено больше, чем у него вообще бывает ресурса.
    local maxRes = tonumber(st.maxZeal)
    if maxRes and slot > maxRes then
        return total, string.format("вложено %d при запасе %d", slot, maxRes)
    end

    return total, nil
end

--- Прибавка оружия к грани кубика (rollFloor / rollCeil).
local function WeaponRoll(channel)
    if SB.Skills and SB.Skills.GetWeaponBonus then
        return (SB.Skills.GetWeaponBonus(channel)) or 0
    end
    return 0
end

function SB.Logic.GetRollRange()
    -- ПОТОЛОК ДВИГАЕТ ОРУЖИЕ: кинжал поднимает верхнюю грань (1-105, с
    -- двумя — 1-110). Всё, что считает крит, берёт границу из Roll(), а
    -- не сотню литералом — иначе 101+ критовал бы всегда.
    local rollMax = SB.Logic.ROLL_MAX + WeaponRoll("rollCeil")
    local rollMin = 1

    -- ПОЛ ДВИГАЮТ И ЭФФЕКТЫ, А НЕ ТОЛЬКО ПРОИСХОЖДЕНИЕ. Раньше здесь
    -- читался один профиль расы и класса, то есть пол был свойством, с
    -- которым рождаются, и выразить «пока на тебе благословение, худшее
    -- не случается» было нечем.
    --
    -- Канал общий с профилем намеренно: и то и другое отвечает на один
    -- вопрос — с какой грани начинается кубик, — и складывать их в разных
    -- местах значило бы завести два ответа. Гном под «Благословением»
    -- получает сумму, а не большее из двух, и это верно: и кровь, и чары
    -- работают в одну сторону.
    -- Оружие — третьим слагаемым того же канала: кистевое и свободная
    -- рука по +5 каждая (Орк с двумя пустыми руками под «Благословением»
    -- — 25 + 15 + 10 = 50, ровно половина кубика).
    local floor = SB.Data.GetSoftBonus("rollFloor")
        + ((SB.ActiveEffects and SB.ActiveEffects.GetMod)
            and (SB.ActiveEffects.GetMod("rollFloor")) or 0)
        + WeaponRoll("rollFloor")
    if floor > rollMin then rollMin = floor end
    -- Пол не должен схлопнуть диапазон: оставляем хотя бы половину граней.
    if rollMin > math.floor(rollMax / 2) then rollMin = math.floor(rollMax / 2) end
    if rollMin < 1 then rollMin = 1 end

    return rollMin, rollMax
end

--- Бросок кубика по текущему диапазону. Границы возвращаются вторым и
--- третьим значением — они нужны расчёту крита (GetCritThreshold) и
--- проверке чужого каста (VerifyIncomingCast).
--- @return number roll, number rollMin, number rollMax
function SB.Logic.Roll()
    local lo, hi = SB.Logic.GetRollRange()
    return math.random(lo, hi), lo, hi
end

--- ГОЛЫЙ КУБИК 1-100 — для бросков, которые делает НЕ персонаж.
---
--- Защита НПС и атака НПС катятся на машине Ведущего, и Roll() отдавал
--- им ЕГО диапазон: расовый пол Орка-Ведущего доставался каждому
--- стражнику, а с бонусами оружия туда же ушли бы и кинжалы Ведущего.
--- У НПС нет ни расы игрока, ни его рук — у него ровный кубик.
--- @return number roll, number rollMin, number rollMax
function SB.Logic.RollPlain()
    local hi = SB.Logic.ROLL_MAX
    return math.random(1, hi), 1, hi
end

--- Наибольший бросок, какой бывает честно: сотня плюс кинжалы в обеих
--- руках. Точного оружия атакующего мы не знаем, и проверка ловит не
--- ложь, а невозможное — как MaxPlausibleAttackMod.
function SB.Logic.MaxPlausibleRoll()
    return SB.Logic.ROLL_MAX + SB.Logic.MaxWeaponBonus("rollCeil")
end


-- ============================================================
-- ЛОКАЛЬНОЕ ВОССТАНОВЛЕНИЕ
-- Вызывается как лидером, так и всеми участниками
-- при получении REST-пакета по сети.
-- ============================================================

function SB.Logic.LocalRest()
    -- Эффекты снимаем ПЕРВЫМИ, и только потом восстанавливаем здоровье.
    -- Обратный порядок наливал ХП до максимума, раздутого «Стойкостью»
    -- или «Обликом медведя», а через мгновение эффект снимался — и
    -- персонаж оставался с запасом выше собственного максимума.
    if SB.ActiveEffects then SB.ActiveEffects.Clear() end
    SB.PlayerModel.FullReset()
    SB.Events.Fire("STATUS_CHANGED")
end

-- ============================================================
-- ЗДЕСЬ БЫЛ КОРОТКИЙ ОТДЫХ
--
-- Три функции: LocalShortRest (отдых на своём персонаже),
-- MakeShortRestMessage (строка «перевёл дух») и ShortRest (точка
-- входа с кнопки). Механики больше нет — нет и их.
--
-- ОТДЫХ В АДДОНЕ ОСТАЛСЯ ОДИН — Долгий, ниже. Это конец сцены, а
-- не передышка посреди неё: полное восстановление, снятие
-- эффектов, починка доспеха и запасов.
--
-- Передышку заменил ручеёк от «Лидерства»: единица ресурса каста
-- раз в 4/3/2/1 хода по вложенному навыку. Разница не в числах, а
-- в том, что за неё не платят ходом и её не надо объявлять.
-- ============================================================

-- ============================================================
-- ДОЛГИЙ ОТДЫХ
-- В группе — только лидер.
-- ============================================================
function SB.Logic.Rest()
    if IsInGroup() and not UnitIsGroupLeader("player") then
        SB.UI.PrintMsg("leaderOnlyLongRest")
        return
    end
    -- Долгий Отдых — это конец сцены: полное восстановление всем и снятие
    -- всех эффектов. Объявлять его посреди пошагового режима бессмысленно
    -- и разрушительно — сначала выйти из режима (см. Core/TurnOrder.lua).
    if SB.TurnOrder and SB.TurnOrder.IsActive() then
        SB.UI.PrintMsg("noLongRestInTurnMode")
        return
    end
    -- Объявление Ведущего меняет состояние ВСЕЙ группы: рассылка всем,
    -- полное восстановление и перерисовка у каждого. Такое не должно
    -- уходить очередью по щелчкам (см. Core/Cooldowns.lua).
    if SB.Cooldowns and not SB.Cooldowns.Check(SB.Cooldowns.GM) then return end
    if SB.Cooldowns then SB.Cooldowns.Start(SB.Cooldowns.GM) end
    SB.Logic.LocalRest()
    local sysMsg = "|cFF9933FF[Spellbreaker]:|r " .. UnitName("player") ..
                   " объявляет Долгий Отдых. Ресурсы и здоровье восстановлены у всех!"
    SB.Events.Fire("BROADCAST_LOG", sysMsg, SB.LogRank.ACTION)
    SB.Events.Fire("BROADCAST_REST", "LONG")
end


-- ============================================================
-- ПОДТВЕРЖДЕНИЕ КАСТА
-- Списывает ресурсы и инициирует проверку броска.
-- slotLevel == 0 → заговор (ресурсы не тратятся).
-- ============================================================
--- @param spellID   string
--- @param slotLevel number   сколько ресурса вливаем (0 — заговор/приём)
--- @param opts      table|nil  { channelStep = true } — это ПРОДОЛЖЕНИЕ
---        потока по клику на держателе, а не новый каст: держатель
---        вешать заново не нужно (иначе счётчик применений возвращался
---        бы к полному на каждом продолжении, и поток не кончался бы
---        никогда), см. SB.Data.GetChannelUses в Core/Database.lua.
-- ============================================================
-- МОЖНО ЛИ СЕЙЧАС ДЕЙСТВОВАТЬ ЭТИМ ЗАКЛИНАНИЕМ
--
-- Одна функция на все запреты, не зависящие от того, ОТКУДА пришло
-- действие: кнопка «Применить», клик по иконке активного эффекта,
-- продолжение потока. Печатает причину отказа сама — вызывающему хватает
-- одной строки.
--
-- ПОЧЕМУ ОТДЕЛЬНО. Запреты жили внутри ConfirmCast, а клик по иконке
-- эффекта списывает применение ДО того, как дойдёт до каста, и потому
-- проверял их у себя — своим списком. Списки разошлись: в клике не
-- хватало дистанции, и попытка продолжить поток из-за предела дальности
-- сжигала применение впустую. Разойтись снова они уже не могут.
--
-- Здесь ТОЛЬКО запреты «нельзя действовать вообще». Проверки, зависящие
-- от круга вливания (ранг, хватает ли ресурса), остаются в ConfirmCast:
-- у клика по иконке круга нет, продолжение потока всегда бесплатно.
--
-- Вторым значением отдаётся ПРИЧИНА отказа ("downed" | "turn" |
-- "cooldown" | "group" | "range" | "move"). Нужна она одному месту:
-- предел передвижения не пишет в чат намеренно (см.
-- SB.Movement.CheckCanAct), и клик по иконке эффекта показывает его сам.
-- @param onSelf boolean|nil  каст объявлен «на себя»: цели у него нет
--        вовсе, и все проверки цели ниже к нему не относятся. Иначе
--        выбранный на другом конце площади союзник запрещал бы выпить
--        собственное зелье — «цель вне досягаемости».
-- @param bonus boolean|nil  это БОНУСНОЕ действие (предмет в свой ход):
--        общий темп в шесть секунд к нему не относится — он меряет
--        обычные действия, а бонусное на них не похоже ничем, кроме
--        кнопки. Всё прочее — павший, очередь, снаряжение, дальность,
--        предел передвижения — проверяется как обычно.
-- @return boolean ok, string|nil reason
-- ============================================================
function SB.Logic.CanCastNow(spell, onSelf, bonus)
    if not spell then return false end
    local PM = SB.PlayerModel

    -- ПАВШИЙ НЕ ДЕЙСТВУЕТ. Ноль здоровья — это не «мало ХП», а выход из
    -- сцены до лечения или Отдыха (см. PM.IsDowned и CheckPvpDeath).
    if PM.IsDowned() then
        SB.UI.PrintMsg("downedCantAct")
        return false, "downed"
    end

    -- ОЧЕРЕДЬ ХОДОВ: чужой ход не должен стоить игроку ни маны, ни
    -- применения (см. Core/TurnOrder.lua).
    if SB.TurnOrder and not SB.TurnOrder.CheckCanAct() then return false, "turn" end

    -- ТЕМП. Шесть секунд между действиями — предохранитель от спама
    -- способностями, в первую очередь вне пошагового режима, где очередь
    -- ходов не сдерживает вообще ничем (см. Core/Cooldowns.lua).
    if SB.Cooldowns and not bonus
       and not SB.Cooldowns.Check(SB.Cooldowns.TURN) then return false, "cooldown" end

    -- СНАРЯЖЕНИЕ. Выстрел без лука — не выстрел (см. врезку о
    -- SB.Data.KeyRequirements в Core/Database.lua). Проверка своя, до
    -- любых проверок цели: не хватает не цели, а руки.
    local need = SB.Data.GetEquipRequirement and SB.Data.GetEquipRequirement(spell)
    local req  = need and SB.Data.EquipRequirements[need]
    if req and not req.check() then
        print(SB.Theme.MSG_BAD .. "[Spellbreaker]: " .. req.deny .. "|r")
        return false, "equip"
    end

    -- У КРАЖИ ОБЯЗАНА БЫТЬ ЖЕРТВА, И ЭТО НЕ ТЫ.
    --
    -- Обшарить собственный карман — не бросок и не действие, и раньше
    -- такой каст НЕ ОТСЕИВАЛСЯ, а проваливался в самый низ цепочки
    -- резолва — заявкой Ведущему. Стоило это дорого:
    --
    --   • CAST_CONFIRMED поднимается ДО развилки резолва, а с ним
    --     срабатывают классовые механики. У разбойника триггер —
    --     «применён приём», так что ресурс капал за саму попытку;
    --   • ветка заявки ход НЕ ТРАТИТ: он спишется, когда ответит
    --     Ведущий. То есть игрок платил за кражу у себя ничем, получал
    --     ресурс и оставался непоходившим;
    --   • и каждый такой каст ложился Ведущему в очередь заявок.
    --
    -- ОТКАЗ ЗДЕСЬ, А НЕ В РЕЗОЛВЕ, — в этом вся суть правки: до списания,
    -- до CAST_CONFIRMED и до заявки. Рядом стоят отказы того же рода:
    -- «выстрел без лука» и «цель вне группы».
    --
    -- ПРАВИЛО, А НЕ ЗАПЛАТКА НА «КАРМАННУЮ КРАЖУ»: спрашиваем поле steal,
    -- поэтому любое будущее воровство отсеется тем же кодом. Условие «кто
    -- годится в жертвы» не дублируется — его знает SB.Logic.CanSteal, та
    -- же функция, по которой каст потом и маршрутизируется.
    if SB.Logic.GetStealKind(spell) and not SB.Logic.CanSteal(spell, not onSelf) then
        print(SB.Theme.MSG_BAD .. "[Spellbreaker]: " ..
            "Обшарить можно только чужой карман — выберите цель.|r")
        return false, "steal_target"
    end

    local targetIsOtherPlayer = not onSelf
                                and UnitExists("target") and UnitIsPlayer("target")
                                and not UnitIsUnit("target", "player")

    -- ЦЕЛЬ-ИГРОК ТРЕБУЕТ ОБЩЕЙ ГРУППЫ.
    -- Всё, что направлено на другого игрока — удар, лечение, бафф,
    -- дебафф, — доставляется аддон-сообщением, а те ходят только внутри
    -- группы или рейда. Без группы пакет молча не уходил, но заклинание
    -- при этом считалось применённым: ресурс списывался, а лог рапортовал
    -- «Эффект наложен». Со стороны это выглядело как «неткод не работает».
    if targetIsOtherPlayer and not IsInGroup() then
        local _, onSelf = SB.Logic.GetTargetedEffect(spell)
        local needsGroup = spell.canCrit or SB.Logic.IsHealingCast(spell)
            or (onSelf == false)
        if needsGroup then
            SB.UI.PrintMsg("targetNotInGroup")
            return false, "group"
        end
    end

    -- ДИСТАНЦИЯ. Приём ближнего боя нельзя применить с другого конца
    -- площади, а дальнобойный — из-за предела своей дальности.
    --
    -- Только по игрокам — то есть ровно в ПвП, как и просили. По НПС
    -- дистанцию по-прежнему оценивает Ведущий: у аддона нет надёжного
    -- способа померить её до неигрового юнита (LibRangeCheck отвечает
    -- брекетами, а не метрами, см. SB.Logic.IsSpellInRange).
    -- ВИДИМОСТЬ. Заклинание в одну цель требует, чтобы цель была перед
    -- глазами: ушла за прорисовку, оказалась в другой фазе или вышла из
    -- мира — бить и лечить некого, хотя аддон-пакет до неё дойдёт
    -- (см. SB.Logic.IsUnitObservable — там же о том, чего проверка не
    -- ловит). Площадь сюда не попадает: у неё цели нет, задетых каждый
    -- определяет у себя.
    if targetIsOtherPlayer and not spell.aoe
       and not SB.Logic.IsUnitObservable("target") then
        SB.UI.PrintMsg("targetNotVisible")
        return false, "sight"
    end

    if targetIsOtherPlayer and not SB.Logic.IsSpellInRange(spell) then
        SB.UI.PrintMsg("targetOutOfRange")
        return false, "range"
    end

    -- ПРЕДЕЛ ПЕРЕДВИЖЕНИЯ. Ход состоит из перемещения и действия, и
    -- выбрав весь ход бегом, действие персонаж уже не совершает — ему
    -- остаётся только пропустить ход (см. Core/Movement.lua).
    if SB.Movement and not SB.Movement.CheckCanAct() then return false, "move" end

    return true
end

function SB.Logic.ConfirmCast(spellID, slotLevel, opts)
    local PM = SB.PlayerModel
    opts = opts or {}

    -- Фиксируем цель до любых задержек (ГМ может рассмотреть заявку
    -- спустя время, когда игрок уже сменил таргет)
    --
    -- «НА СЕБЯ» ФИКСИРУЕТСЯ КАК ОТСУТСТВИЕ ЦЕЛИ, а не как отдельный
    -- получатель. Так весь путь ниже — эмоут, лог, доставка, заявка
    -- Ведущему — разбирается с этим сам, ничего не зная про новый флаг:
    -- цели нет, значит и получателя нет, кроме заклинателя.
    pendingSelfCast       = (opts.onSelf == true)
    local hasUnit         = (not pendingSelfCast) and UnitExists("target")
    pendingTargetName     = (hasUnit and UnitName("target")) or ""
    pendingTargetGender   = (hasUnit and UnitSex("target"))  or 1
    pendingTargetIsAlly   = (hasUnit and UnitIsPlayer("target")
                             and UnitCanAssist("player", "target")) or false

    -- Проверка подготовки
    local spell = SB.Data.Spells[spellID]
    if not spell then return end
    -- ПОДГОТОВЛЕН — ИЛИ ЛЕЖИТ В СУМКЕ. Ячейки у предмета свои, и искать
    -- его среди подготовленных ЗАКЛИНАНИЙ бессмысленно: там его нет и
    -- быть не может (см. Core/Items.lua). Пока этой развилки не было,
    -- любое зелье отбивалось словами «вы не подготовили это заклинание»:
    -- сумка есть, а выпить из неё нельзя.
    local isItem = SB.Items and SB.Items.IsItem and SB.Items.IsItem(spell)
    local ready  = isItem and SB.Items.IsPrepared(spellID) or PM.IsPrepared(spellID)
    -- БОНУСНОЕ ДЕЙСТВИЕ решается ЗДЕСЬ, до всех проверок, и дальше не
    -- переспрашивается: между этим местом и SpendTurn лежит весь резолв,
    -- и очередь за это время может сдвинуться (см. SB.Logic.IsBonusAction).
    local bonus = SB.Logic.IsBonusAction(spell)
    if not spell.isContainer and not ready then
        SB.UI.PrintMsg(isItem and "itemNotInBag" or "spellNotPrepared")
        return
    end

    -- ВСЕ ОБЩИЕ ЗАПРЕТЫ — одной проверкой (см. SB.Logic.CanCastNow). Она
    -- же стоит на клике по иконке эффекта, поэтому разойтись эти два
    -- списка больше не могут.
    --
    -- Отказы отсюда НЕ ТРОГАЮТ ЗАМОК: он ставится ниже, по факту
    -- состоявшегося каста, и «снять» его отказом означало бы вернуть
    -- игроку право перераспределиться после любого неудачного клика.
    if not SB.Logic.CanCastNow(spell, pendingSelfCast, bonus) then return end
    pendingBonusAction = bonus

    PM.SetLocked(true)

    -- Аура (команда серверному эмулятору). Игнорируется, если ГМ включил
    -- чекбокс «Игнорировать .caura» в библиотеке.
    if spell.caura and not (SpellbreakerAccountDB and SpellbreakerAccountDB.ignoreCaura) then
        SendChatMessage(".caura toggle " .. spell.caura, "SAY")
    end

    -- Списание ресурсов (только если не заговор)
    if slotLevel > 0 then
        -- Тот же потолок, что и у подготовки (PM.GetMaxPrepareOrder): в
        -- чужую школу нельзя влить больше, чем в ней можно выучить, иначе
        -- ограничение мультикласса обходилось бы апкастом — подготовил
        -- чужой заговор и поднял его до своего круга.
        local maxOrder = PM.GetMaxPrepareOrder(spell.class)
        if slotLevel > maxOrder then
            print(string.format(
                "|cFFFF0000[Spellbreaker]: Ваш ранг (%s) не позволяет влить в это заклинание больше %d-го порядка!|r",
                PM.GetMastery(), maxOrder))
            PM.SetLocked(false)
            return
        end
        if not PM.SpendCastResource(slotLevel) then
            print(SB.Theme.MSG_BAD .. "[Spellbreaker]: Не хватает ресурса «" ..
                PM.GetResourceName() .. "»!|r")
            PM.SetLocked(false)
            return
        end
        -- Синхронизировать статус с группой после списания
        SB.Events.Fire("STATUS_CHANGED")
    end

    -- Каст подтверждён (и списание, если требовалось, прошло успешно) —
    -- триггер для уникальных классовых механик (см. Core/ClassMechanics.lua).
    SB.Events.Fire(SB.E.CAST_CONFIRMED, spellID, slotLevel)

    -- ЦЕНА ПРИМЕНЕНИЯ (spell.onCast) — ЗДЕСЬ, В ЕДИНСТВЕННОЙ ТОЧКЕ, ЧЕРЕЗ
    -- КОТОРУЮ ПРОХОДЯТ ВСЕ КАСТЫ.
    --
    -- Раньше она считалась в двух путях резолва из пяти — ПвЕ-броске и
    -- наложении эффекта. Заклинание, уходящее в площадь или в ПвП-удар,
    -- свой onCast не платило вообще: «Огненный ливень» с ценой в единицу
    -- здоровья не снимал ничего, и поле выглядело сломанным.
    --
    -- И платится она за ПРИМЕНЕНИЕ, а не за успех: ход потрачен, кровь
    -- пролита, промахнулся ты или нет. Прежняя привязка к успеху ничего
    -- не значила там, где стояла (оба пути вели её через resistable =
    -- false, где успех гарантирован), а на площади означала бы «плачу,
    -- только если попал» — то есть не цену, а долю добычи.
    --
    -- Повтор потока сюда тоже приходит (ConfirmCast зовётся заново с
    -- channelStep), и это ровно то, что нужно: Жизнеотвод платит кровью
    -- за каждое применение, а не за первое.
    --
    -- ── КОГО ПОЯТ, ТОТ И ПОЛУЧАЕТ ────────────────────────────
    --
    -- У ПРЕДМЕТА выплата — это его содержимое, а не цена: выпитое зелье
    -- достаётся тому, кому его дали. Правило «кому» здесь не своё, а то
    -- же самое, по которому уже расходится эффект склянки, —
    -- ItemStaysOnCaster (см. врезку у неё).
    --
    -- ПОЧЕМУ ЭТОГО НЕ БЫЛО. Половина склянки ездила по цели, а половина
    -- нет: эффект-контейнер уходил союзнику веткой GetTargetedEffect, а
    -- выплата применялась здесь и всегда на себя. Отсюда и жалоба
    -- «зельями не всегда можно хилить союзников»: троллья кровь,
    -- которая вешает регенерацию, работала, а лечебное зелье, которое
    -- отдаёт здоровье сразу, — нет. Оно молча лечило поящего, а не того,
    -- кому подносили склянку. Таких предметов двенадцать, и все
    -- лечебные зелья в их числе.
    --
    -- ШЛЁМ ТОЛЬКО ID: содержимое получатель берёт из СВОЕЙ библиотеки
    -- (см. ParseITEMPAY). Уехала бы выплата полем пакета — любой клиент
    -- дарил бы соседям «+99 ХП» одной подделанной строкой.
    if spell.onCast and SB.ActiveEffects and SB.ActiveEffects.ApplyPayload then
        if isItem and not ItemStaysOnCaster(spell, pendingTargetIsAlly)
           and SB.Net and SB.Net.SendItemPayload then
            SB.Net.SendItemPayload(pendingTargetName, spellID)
        elseif SB.ActiveEffects.ApplyPayloadCollected then
            local parts = SB.ActiveEffects.ApplyPayloadCollected(spellID, spell.onCast)
            if #parts > 0 then
                local rec = { spellID = spellID, text = table.concat(parts, ", ") }
                castPayload = rec
                -- Не забрали к концу кадра — печатаем отдельно.
                C_Timer.After(0, function()
                    if castPayload ~= rec then return end
                    castPayload = nil
                    local G = SB.Theme.MSG_BODY
                    SB.Events.Fire(SB.E.BROADCAST_LOG,
                        SB.Theme.MSG_TAG .. "[Spellbreaker]:|r " .. G .. UnitName("player") ..
                        " — |r" .. (spell.name or spellID) .. G .. ": " .. rec.text .. ".|r",
                        SB.LogRank.TICK)
                end)
            end
        else
            SB.ActiveEffects.ApplyPayload(spellID, spell.onCast)
        end
    end

    -- СКЛЯНКА РАСХОДУЕТСЯ ПРИМЕНЕНИЕМ — здесь же, в единственной точке,
    -- через которую проходят все касты. Предмет применяется тем же
    -- кодом, что заклинание, и своей ветки резолва у него нет: в этом и
    -- был смысл держать его среди заклинаний (см. Core/Items.lua).
    --
    -- ЗА ПРИМЕНЕНИЕ, А НЕ ЗА УСПЕХ, по той же причине, что и onCast выше:
    -- выпитое зелье выпито, подействовало оно или нет.
    if SB.Items and SB.Items.NoteUsed then
        SB.Items.NoteUsed(spellID)
    end

    -- ЗДЕСЬ, а не в SpendTurn: ПвЕ-каст уходит заявкой Ведущему, и ход
    -- по нему тратится только когда тот ответит, — а темп ограничивать
    -- надо с момента, когда игрок нажал, иначе заявками можно засыпать.
    -- Все отказы выше по стеку сюда не доходят и кулдаун не тратят.
    --
    -- БОНУСНОЕ ДЕЙСТВИЕ ТЕМП НЕ ТРАТИТ: иначе выпитое зелье запирало бы
    -- обычное действие на шесть секунд, то есть стоило бы ровно того же,
    -- что и ход. Спам при этом невозможен — бонусное действие одно за
    -- ход (см. TO.CanUseBonus).
    if SB.Cooldowns and not bonus then SB.Cooldowns.Start(SB.Cooldowns.TURN) end

    -- ПОТОК начинается ЗДЕСЬ, а не по успеху броска, и на то две причины.
    -- Во-первых, исход каста приходит асинхронно — по сети от цели или
    -- от Ведущего, — и «повесить держатель на успехе» пришлось бы
    -- дублировать во все пять путей резолва. Во-вторых, по смыслу поток
    -- это не результат, а поза: жрец уже тянет силу, промахнулся он или
    -- нет. Каждое продолжение всё равно требует собственного броска,
    -- поэтому неудачно начатый поток ничего не даёт даром.
    if spell.channel and spell.channelEffect and not opts.channelStep then
        SB.ActiveEffects.Add(spell.channelEffect,
            SB.Data.GetChannelUses(spell), true)
    end

    -- ОБЪЯВЛЕННЫЙ САМОКАСТ НЕ ВИДИТ НИ ИГРОКОВ, НИ СУЩЕСТВ. Развилка
    -- ниже вся построена на «а кто в таргете», и оставь мы её живой —
    -- выпитое зелье полетело бы в выбранного волка или в союзника,
    -- которого игрок выделил вовсе не за этим.
    local aimed = not pendingSelfCast
    local hasEnemyPlayerTarget = aimed and UnitExists("target") and UnitIsPlayer("target")
                                 and not UnitIsUnit("target", "player")
    local hasValidHealTarget = aimed and UnitExists("target") and UnitIsPlayer("target")

    -- ДВОЙНОЕ ЗАКЛИНАНИЕ: isHeal И canCrit одновременно. Одно и то же
    -- прикосновение, которое своему затягивает раны, а чужому жжёт плоть, —
    -- и разводить его на два заклинания с одинаковым описанием незачем.
    --
    -- Куда оно пойдёт, решает ПОМЕТКА «ДРУГ» (см. SB.Data.IsFriend), а не
    -- фракция и не таблица юнита: сцена в РП делится на своих и чужих по
    -- отыгрышу, и знает об этом только сам игрок. Тот же список, по
    -- которому уже разбирается рассеивание (снять бафы с чужого, дебафы со
    -- своего) и площадь (см. FriendIgnoresAoe), — то есть правило в аддоне
    -- одно на все три случая, а не третье по счёту.
    --
    -- Себя аддон всегда считает своим, так что каст на себя лечит.
    -- Непомеченный — чужой: дружба объявляется явно, одним щелчком, и
    -- обратное умолчание («лечим всех, кого не отметили врагом») означало
    -- бы, что список надо вести на весь рейд противника.
    local targetName = aimed and UnitExists("target") and UnitName("target") or nil
    local dualHealsTarget = spell.isHeal and spell.canCrit
        and targetName and SB.Data.IsFriend(targetName)

    -- ТОЛЬКО ЧИСТОЕ СОТВОРЕНИЕ, а не всё, что кладёт вещь в сумку.
    --
    -- Раньше здесь стояло просто `spell.creates`, и ветка перехватывала
    -- ЛЮБОЕ заклинание с этим полем. Врезка ниже честно предупреждала:
    -- «заклинание, которое И создаёт предмет, И бьёт, пойдёт сюда, а не
    -- в боевую ветку; таких в библиотеке нет, а появись оно — решать
    -- придётся руками». Оно появилось — «Похищение души», которое добывает
    -- осколок ударом.
    --
    -- Решаем так: МАРШРУТ выбирается по тому, что заклинание делает с
    -- ЦЕЛЬЮ, а сотворение срабатывает по исходу в самой боевой ветке
    -- (см. SB.Logic.GrantCreatedItems). Сюда попадает только то, чему с
    -- целью делать нечего.
    if spell.creates and not SB.Logic.IsHarmful(spell)
       and not SB.Logic.IsHealingCast(spell) then
        -- СОТВОРЕНИЕ ПРЕДМЕТА — ВСЕГДА САМ, НИКОГДА ЗАЯВКОЙ.
        --
        -- Ведущему тут решать нечего: цели нет, сопротивляться некому,
        -- а результат — вещь в собственной сумке заклинателя. Пока
        -- ветки не было, все шесть таких заклинаний (все помечены
        -- resistable = true) падали в самый низ цепочки, то есть прямо
        -- в очередь заявок: чтобы налить себе воды маны, маг ждал
        -- Ведущего.
        --
        -- ПЕРВОЙ, А НЕ ГДЕ-ТО ПОСЕРЕДИНЕ. «Всегда минуя заявки» — это и
        -- значит «раньше всех остальных разборов»: любая ветка выше
        -- увела бы заклинание своим путём. Цена — заклинание, которое
        -- И создаёт предмет, И бьёт по площади, пойдёт сюда, а не в
        -- площадную ветку; таких в библиотеке нет, а появись оно —
        -- решать, что в нём главное, всё равно придётся руками.
        --
        -- ДВА ИСХОДА, оба локальные:
        -- ПОРОГ СПРАШИВАЕМ У ОБЩЕГО ПРАВИЛА, А НЕ ВЫВОДИМ ЗАНОВО.
        --
        -- Здесь стояло собственное «resistable == false → ноль, иначе
        -- ConjureDC», и оно разошлось с SB.Logic.IsGuaranteed в тот
        -- день, когда сотворению объявили автоуспех: правило поменяли в
        -- одном месте, а ветка продолжала считать по-своему. Все шесть
        -- мирных сотворений помечены resistable = true, так что каждое
        -- по-прежнему бросало против шестидесяти.
        --
        -- НАРУЖУ ЭТО ВЫХОДИЛО МОЛЧА, и в этом вся беда. По провалу
        -- GrantCreatedItems выходит на первой же строке (landed == false)
        -- и не печатает НИЧЕГО — ни «некуда положить», ни «предел
        -- пачки». В логе оставалось только «Провал.», ничем не связанное
        -- с пустой сумкой, и со стороны это выглядело как «камень
        -- здоровья просто не появляется».
        local dc = SB.Logic.IsGuaranteed(spell) and 0
                   or (SB.Data.Config.ConjureDC or 0)
        SB.Logic.ProcessRollAndCast(spellID, dc, slotLevel,
            slotLevel > (spell.level or 0))
    elseif SB.Logic.CanDispelLocally(spell, aimed) then
        -- РАССЕИВАНИЕ — сам, минуя Ведущего: снимать эффекты умеет только
        -- тот клиент, на котором они висят. Но только когда есть КОГО
        -- чистить: без цели у заклинания с дальностью это уже вопрос к
        -- Ведущему, а не самокаст (см. SB.Logic.CanDispelLocally).
        --
        -- aimed уехал ВНУТРЬ проверки, а не остался условием рядом с ней:
        -- у склянки «на себя» — не отсутствие цели, а сама цель, и
        -- отбивать её здесь значило бы держать половину правила снаружи.
        SB.Logic.ResolveDispel(spellID, slotLevel)
    elseif aimed and SB.Logic.CanDispelNpc and SB.Logic.CanDispelNpc(spell) then
        -- РАССЕИВАНИЕ С СУЩЕСТВА — сразу за рассеиванием с игрока, и это
        -- не косметика. Рассеивающее заклинание сплошь и рядом помечено
        -- ещё и isHeal (снятие яда лечит), а ветка лечения существа стоит
        -- ниже — окажись эта после неё, «Очищение» на отравленном волке
        -- лечило бы его вместо того, чтобы снять яд.
        SB.Logic.ResolveNpcDispel(spellID, slotLevel)
    elseif spell.aoe and spell.isHeal then
        -- ПЛОЩАДНОЕ лечение — цель не нужна: бросок один на всех, а порог
        -- каждый проверяет у себя, по своему уровню (см. ResolveAoeHeal).
        --
        -- БЕЗ ОГЛЯДКИ НА ГРУППУ, в отличие от площадной атаки. Та вне
        -- группы просто некому: весь её смысл в рассылке. Лечение же и в
        -- одиночку осмысленно — лекарь стоит в собственном круге, —
        -- а падение в заявку Ведущему означало бы, что одно и то же
        -- заклинание работает по двум разным правилам.
        --
        -- Стоит ПЕРВЫМ среди площадных: лечащее заклинание с полем aoe
        -- иначе проваливалось в одиночное лечение и лечило одного.
        SB.Logic.ResolveAoeHeal(spellID, slotLevel)
    elseif spell.aoe and spell.canCrit and IsInGroup() then
        -- ПЛОЩАДНАЯ атака — цель не нужна вовсе: бросок уходит всей
        -- группе, и каждый сам проверяет, попал ли он в радиус.
        -- Вне группы рассылать некуда, поэтому там заклинание идёт
        -- обычным путём (одиночная цель или заявка ГМу).
        SB.Logic.InitiateAoeAttack(spellID, slotLevel)
    elseif spell.aoe and IsInGroup() and not spell.isHeal
           and (spell.buff or spell.debuff) then
        -- ПЛОЩАДНОЙ бафф/дебафф БЕЗ урона — тоже минуя ГМа. Цель ему,
        -- как и площадной атаке, не нужна: бросок уходит группе, а порог
        -- каждый проверяет у себя (см. ResolveAoeEffectCast).
        SB.Logic.ResolveAoeEffectCast(spellID, slotLevel)
    elseif spell.canCrit and hasEnemyPlayerTarget and not dualHealsTarget then
        -- ПвП-заклинание, направленное на другого игрока — минуя ГМа.
        -- Двойное заклинание сюда не попадает, если цель помечена другом:
        -- оно уходит веткой лечения ниже (см. dualHealsTarget).
        SB.Logic.InitiatePvpAttack(spellID, slotLevel)
    elseif aimed and spell.canCrit and SB.Logic.CanHitNpc(spell) then
        -- УДАР ПО СУЩЕСТВУ — тем же разменом, что по игроку, только обе
        -- стороны считает атакующий: клиента, который бросил бы за НПС
        -- защиту, не существует (см. Core/Logic/NPC.lua).
        --
        -- СТОИТ ПОСЛЕ ПвП и до заявки Ведущему: пока существ не было,
        -- уронное заклинание по НПС уходило Ведущему целиком, и он
        -- отыгрывал и бросок, и урон руками.
        SB.Logic.ResolveNpcAttack(spellID, slotLevel)
    elseif aimed and SB.Logic.IsHealingCast(spell) and SB.Logic.CanHitNpc(spell) then
        -- Лечение существа — тем же порогом, что лечение игрока.
        SB.Logic.ResolveNpcHeal(spellID, slotLevel)
    elseif aimed and SB.Logic.CanAffectNpc and SB.Logic.CanAffectNpc(spell) then
        -- ЧИСТЫЙ ЭФФЕКТ НА СУЩЕСТВО — «Проклятие слабости» на волке.
        -- Стоит ПОСЛЕ удара и лечения: у заклинания с уроном дебафф
        -- вешается попаданием, а не отдельным броском.
        --
        -- И ДО ветки GetTargetedEffect ниже, которая существо в цели
        -- отсекает: пока этой ветки не было, такое заклинание уходило
        -- заявкой Ведущему, и он навешивал эффект руками.
        SB.Logic.ResolveNpcEffect(spellID, slotLevel)
    elseif SB.Logic.IsHealingCast(spell) and hasValidHealTarget then
        -- Лечащее заклинание на игрока (или на себя) — минуя ГМа. Сюда же
        -- чистая починка доспеха: применяет её носитель, как и лечение
        -- (см. SB.Logic.GetSpellRepair).
        SB.Logic.ResolveHeal(spellID, slotLevel)
    elseif SB.Logic.CanSteal(spell, aimed) then
        -- КРАЖА — состязание, у которого нет эффекта (см. ResolveSteal).
        --
        -- ВЫШЕ ЭФФЕКТНОЙ ВЕТКИ И НИЖЕ ВСЕХ БОЕВЫХ. Ниже боевых потому,
        -- что заклинание, которое И бьёт, И крадёт, — прежде всего удар:
        -- добыча там побочна. Выше эффектной — потому что та отбирает
        -- себе всё с полем buff/debuff, а вор вполне может ещё и пугать
        -- жертву; кража в таком заклинании главнее.
        SB.Logic.ResolveSteal(spellID, slotLevel)
    elseif SB.Logic.GetTargetedEffect(spell) then
        -- Бафф на союзника/себя или дебафф на другого игрока — бросок
        -- на закрепление эффекта, минуя ГМа (см. ResolveEffectCast).
        -- Нет цели или в цели НПС — сюда не попадаем, и заклинание идёт
        -- обычным ПвЕ-путём ниже.
        SB.Logic.ResolveEffectCast(spellID, slotLevel)
    elseif spell.resistable == false then
        -- Без сопротивления → бросаем сразу локально
        SB.Logic.ProcessRollAndCast(spellID, 0, slotLevel, slotLevel > (spell.level or 0))
    else
        -- Метка цели для заявки ГМу
        local d = spell.distance
        local targetLabel = (not d or d <= 0)
            and "На себя"
            or (pendingTargetName ~= "" and pendingTargetName or "Неопознанная цель")

        SB.Events.Fire("CAST_PENDING", spellID)
        -- Модификатор считаем ЗДЕСЬ и везём с заявкой: у Ведущего нет
        -- ни наших характеристик, ни навыков, ни висящих эффектов, а
        -- справедливая СЛ считается именно от них (см. SB.Logic.FairDC).
        SB.Events.Fire("CAST_REQUEST", spellID, slotLevel, targetLabel,
            SB.Logic.GetCastModifier(spell, slotLevel))

        -- ЗАЯВКА — ЭТО УЖЕ ПОТРАЧЕННЫЙ ХОД.
        --
        -- Раньше ход списывался только когда Ведущий ОТВЕТИТ, и между
        -- заявкой и ответом игрок числился непоходившим. Стоило это
        -- дорого: классовые механики срабатывают на CAST_CONFIRMED, то
        -- есть на попытку, — и разбойник наливал себе ресурс заявками,
        -- ничего за них не платя. Сдерживал его только шестисекундный
        -- темп.
        --
        -- Тем же правилом, которым здесь платится цена применения:
        -- «ход потрачен, кровь пролита, промахнулся ты или нет» (см.
        -- врезку об onCast выше). Заявил действие — заявил ход.
        --
        -- ОТВЕТ ВЕДУЩЕГО ХОД БОЛЬШЕ НЕ СПИСЫВАЕТ: сетевые вызовы
        -- ProcessRollAndCast и ExecuteForcedOutcome об этом знают.
        SB.Logic.SpendTurn(SB.Logic.TurnSkipFor(spell, spellID))
    end
end

-- ============================================================
-- ОБРАБОТКА БРОСКА И РЕЗУЛЬТАТА
-- Вызывается либо локально (resistable=false),
-- либо по ответу ГМа по сети.
-- ============================================================
--- @param totalScaling boolean|nil  Флаг «ГМ разрешил усиление» от старого
---        протокола. Сейчас не используется: усиление считается из
---        реально вложенного ресурса (см. GetCastPower) — параметр
---        оставлен, чтобы не ломать вызовы из Network.lua.
--- @param turnSpent boolean|nil  ход уже потрачен НА ЗАЯВКЕ, и списывать
---        его второй раз нельзя. Ставят его сетевые вызовы — те, что
---        приходят ответом Ведущего; локальные (сотворение предмета,
---        каст без сопротивления) тратят ход здесь, потому что заявки у
---        них не было вовсе.
function SB.Logic.ProcessRollAndCast(spellID, dc, slotLevel, totalScaling, turnSpent)
    local spell   = SB.Data.Spells[spellID]
    -- slotLevel в контексте обязателен: от него зависит источник
    -- "resource" (прибавка к попаданию за вложенный ресурс).
    --
    -- versus — вторая сторона броска, и нужна она провокации: по своему
    -- провокатору бьют без штрафа (см. её источник в реестре). Берём
    -- ИМЯ ИЗ ТАРГЕТА, а не из заявки: заявка уходит Ведущему словами, а
    -- штраф считается здесь и сейчас.
    local mod, modParts = SB.Logic.GetModifierBreakdown("attack",
        { spell = spell, slotLevel = slotLevel, versus = UnitName("target") })

    -- Скейлинг от характеристик, объявленный самим заклинанием
    -- (spell.scaling / устаревшее spell.attributes) — см. GetSpellScaling.
    local hitBonus,  hitParts  = SB.Logic.GetSpellScaling(spell, "hit")
    local critBonus, critParts = SB.Logic.GetSpellScaling(spell, "crit")
    local dmgBonus,  dmgParts  = SB.Logic.GetSpellScaling(spell, "damage", slotLevel)
    -- Урон от висящих эффектов — в тот же dmgBonus и ту же разбивку,
    -- чтобы ГМ видел в логе откуда что.
    --
    -- ЧЕРЕЗ GetDamageMod, А НЕ GetMod("damage"): прибавка бывает трёх
    -- уровней — всему урону, всей магии и одной школе, — и складывать их
    -- в каждом из пяти путей резолва по отдельности значило бы завести
    -- пять расходящихся ответов на один вопрос.
    if SB.ActiveEffects and SB.ActiveEffects.GetDamageMod then
        local effDmg, effParts = SB.ActiveEffects.GetDamageMod(spell)
        dmgBonus = dmgBonus + effDmg
        for _, p in ipairs(effParts) do table.insert(dmgParts, p) end
    end
    local critThresh = SB.Logic.GetCritThreshold(critBonus, rollMax)

    -- Базовый урон от вложенного ресурса (см. GetCastPower). Прибавка к
    -- попаданию из той же функции уже учтена выше — она приходит как
    -- обычный источник реестра "resource".
    local baseDmg = SB.Logic.GetCastPower(spell, slotLevel)

    mod = mod + hitBonus
    -- Скейлинг заклинания подмешиваем в разбивку модификатора, чтобы
    -- в тултипе броска было видно, за счёт чего именно набрался бонус.
    for _, p in ipairs(hitParts) do table.insert(modParts, p) end

    -- ЧЕРЕЗ SB.Logic.Roll, А НЕ math.random ПО ГРАНИЦАМ: здесь стояла
    -- вторая копия одной строки — «взять диапазон и бросить в нём». Пока
    -- пол кубика двигала одна раса, копия была безобидной; теперь его
    -- двигают и эффекты, и второй бросок мимо общей функции однажды
    -- уехал бы от первого.
    local roll, _, rollMax = SB.Logic.Roll()
    local total   = roll + mod
    local dcNum   = tonumber(dc) or 0
    local success = total >= dcNum
 
    -- Единственная отпись игрока — на успех (и крит-успех тоже её
    -- использует). У провала отписи нет в принципе.
    local successMsg = SB.SpellOutcomes.Get(spellID)
 
    local outcomeText, resultStatus, succeeded, detail, isCrit
 
    if SB.Logic.IsGuaranteed(spell) and dcNum == 0 then
        outcomeText   = successMsg
        resultStatus  = "|cFF00FF00УСПЕХ (Без сопротивления)|r"
        succeeded     = true
        detail        = nil
    else
        -- Крит — по ЧИСТОМУ кубику (см. GetCritThreshold).
        --
        -- КРИТИЧЕСКОГО ПРОВАЛА В АДДОНЕ НЕТ. Натуральная единица —
        -- обычный неудачный бросок и ничего больше: она проигрывает СЛ
        -- сама, без отдельной ветки. Прежняя ветка не добавляла ни одного
        -- последствия (succeeded всё равно false), зато отнимала у игрока
        -- право на модификаторы: развитый персонаж с +40 к броску
        -- проваливал каст ровно так же, как новичок, — просто потому что
        -- выпала единица. В системе, где весь смысл в том, что вложенное
        -- работает, такая грань обесценивала вложенное.
        --
        -- Крит ТРЕБУЕТ успеха: полоса крита теперь широкая (до 17% при
        -- вложенном навыке), и «критический успех» вопреки проваленной
        -- СЛ означал бы, что каждое шестое заклинание пробивает любой
        -- порог Ведущего. Исключение одно — натуральный максимум
        -- кубика: он срабатывает всегда, какой бы высокой ни была СЛ.
        --
        -- ЛЕЧАЩИЕ ЗАКЛИНАНИЯ КРИТУЮТ НАРАВНЕ С УРОННЫМИ. Флага canCrit у
        -- них нет и быть не должно — он в маршрутизации означает «это
        -- удар» (см. ConfirmCast), — но крит у лечения есть везде, кроме
        -- этой ветки: и в одиночном резолве, и в площадном. Из-за
        -- проверки строго по canCrit лечение, ушедшее заявкой Ведущему
        -- (цель — НПС или цели нет вовсе), критом не становилось никогда.
        local mayCrit  = spell.canCrit or SB.Logic.IsHealingCast(spell)
        local isNatMax = (roll >= rollMax)
        if mayCrit and (isNatMax or (success and roll >= critThresh)) then
            outcomeText = successMsg; resultStatus = "|cFF00FF00Критический успех!|r"; succeeded = true; isCrit = true
            detail = string.format("Кубик %d при пороге крита %d (итог %d против СЛ %d)",
                roll, critThresh, total, dcNum)
        elseif success then
            outcomeText = successMsg; resultStatus = "|cFF00FF00Успех.|r"; succeeded = true
            detail = string.format("%d + %d = %d против СЛ %d", roll, mod, total, dcNum)
        else
            outcomeText = nil;    resultStatus = "|cFFFF0000Провал.|r"; succeeded = false
            detail = string.format("%d + %d = %d против СЛ %d", roll, mod, total, dcNum)
        end
    end
 
    -- Уведомить UI о вердикте (для фрейма ожидания каста)
    SB.Events.Fire("CAST_RESOLVED", spellID, succeeded, resultStatus, detail)
 
    -- Активный эффект (контейнер) — вешается НА СЕБЯ. Исход этой ветке
    -- известен (мы сами его и посчитали), поэтому спрашиваем по нему.
    local ownContainer = SB.Logic.ApplyOwnContainer(spell, slotLevel, succeeded)
    SB.Logic.GrantCreatedItems(spell, succeeded)

    -- Эффект на цель-союзника (или на себя, если цели нет) — см.
    -- SB.Logic.ApplyBuffToTarget. Если заклинание площадное — вместо
    -- одной цели эффект уходит всем в радиусе (это и есть аура, а для
    -- дебаффа — площадное ослабление вроде Пронзительного воя).
    -- ИМЯ ЭФФЕКТА В ЛОГ БОЛЬШЕ НЕ ПИШЕТСЯ. Оно есть в карточке
    -- заклинания строкой «Накладывает: <ссылка>» (см. UI/Library.lua), а
    -- ссылка на само заклинание в сообщении кликабельна — то есть узнать,
    -- что именно повесилось, можно за один клик, не удлиняя каждую строку
    -- боя. Остаётся только то, чего в карточке нет и быть не может:
    -- КОМУ эффект ушёл и по какому радиусу.
    local buffTargetNote = ""
    local aoeEffectID = (spell.aoe and IsInGroup()) and (spell.buff or spell.debuff) or nil
    if aoeEffectID and succeeded then
        SB.Logic.InitiateAoeEffect(spell, slotLevel)
        buffTargetNote = string.format(" (всем %s в радиусе %g м)",
            SB.Logic.AoeEpicenterLabel(SB.Logic.GetAoeEpicenter(spell)),
            SB.Logic.GetAoeRadius(spell))
    elseif spell.buff and succeeded then
        local onWhom, toScene = SB.Logic.ApplyBuffToTarget(spell, slotLevel)
        -- Цель, которой аддон не ведёт (НПС, персонаж вне группы): эффект
        -- отыгрывает Ведущий, и врать «на себя» в логе нельзя.
        -- Стрелка вместо «эффект ->»: слово «эффект» здесь ничего не
        -- уточняет — в этой строке больше некому никуда уходить.
        buffTargetNote = string.format(" %s %s", "\226\134\146",
            onWhom or (toScene and "цель Ведущего" or "на себя"))
    end
	
    -- Уменьшить счётчик всех активных эффектов на 1 при любом касте.
    -- Исключаем контейнер текущего заклинания — он только что добавлен/
    -- обновлён, уменьшать его не нужно. Также исключаем isContainer-спеллы
    -- (Use уже уменьшил).
    --
    -- НО ТОЛЬКО ЕСЛИ ОН ДЕЙСТВИТЕЛЬНО ЛЁГ. Провалившийся каст не должен
    -- защищать уже висящую копию того же эффекта от тика — тот же
    -- случай, что и с наложением на чужого в ResolveEffectCast:
    -- пропускать надо то, что легло сейчас, а не всё с таким id.
    --
    -- РАНЬШЕ ЭТО БЫЛО ОТМЕНОЙ: TurnSkipFor добавляла контейнер по факту
    -- наличия поля, и здесь его приходилось вычёркивать обратно строкой
    -- skip[spell.container] = nil. Теперь ApplyOwnContainer возвращает
    -- ровно то, что легло, — и вычёркивать нечего.
    --
    -- НО НЕ ВТОРОЙ РАЗ. Пришли мы сюда ответом Ведущего — ход списан ещё
    -- на заявке, и эффекты тогда же тикнули. Контейнер при этом ложится
    -- уже ПОСЛЕ того тика, так что пропускать ему нечего.
    if not turnSpent then
        SB.Logic.SpendTurn(SB.Logic.TurnSkipFor(spell, spellID, ownContainer))
    end
 
    -- Системный лог. ПвЕ-урон аддон сам не применяет — его отыгрывает
    -- Ведущий, поэтому в лог идёт готовое ИТОГОВОЕ число, а не «+Урон»
    -- без цифры: ГМу иначе пришлось бы самому складывать базу, крит и
    -- скейлинг. Источников при этом может быть несколько (и с минусом),
    -- но перечислять их прямо в строке больше не нужно — разбивка живёт
    -- в самом числе (SB.UI.AmountText). Списком она
    -- занимала полторы строки чата на КАЖДЫЙ каст, а нужна Ведущему
    -- ровно в тот момент, когда он сверяет цифру.
    local G = SB.Theme.MSG_BODY -- тёплое золото вместо белого по умолчанию — читается лучше
    local bonusInfo = ""
    -- Урон, с которого потом посчитается вампиризм. Сам вампиризм
    -- применяется НИЖЕ, после рассылки основного сообщения: иначе
    -- «вытягивает жизнь» встало бы в лог раньше самого удара.
    local leechFrom = 0
    if succeeded and spell.canCrit then
        -- Крит МНОЖИТ уже сложенный урон, поэтому применяется последним,
        -- после базы и скейлинга (см. SB.Logic.ApplyCritDamage).
        --
        -- Нижняя грань — MinDamageOnHit, тот же порог, что и в ПвП. База
        -- теперь есть только у заговоров, и уронное заклинание высокого
        -- круга без канала damage (такие в библиотеке есть — «Молот
        -- правосудия», «Отравленный клинок») давало в лог «урон 0», а на
        -- крите — «урон 0» вдвое. Попавший удар всегда снимает хотя бы
        -- единицу; ноль означал бы «попал, но ничего не произошло».
        local sum = math.max(SB.Data.Config.MinDamageOnHit or 1, baseDmg + dmgBonus)
        local dmgTotal, critAdd = SB.Logic.ApplyCritDamage(sum, isCrit)
        local parts = { { key = "base", value = sum - dmgBonus } }
        for _, p in ipairs(dmgParts) do
            table.insert(parts, { key = p.label, value = p.value })
        end
        -- Крит идёт ПОСЛЕДНЕЙ строкой разбивки и хранит прибавку, а не
        -- множитель: подсказка складывает слагаемые и обязана сойтись с
        -- итогом, а «×2» в такой сумме не складывается.
        if critAdd ~= 0 then
            table.insert(parts, { key = "crit", value = critAdd })
        end
        bonusInfo = G .. " (урон |r" ..
            SB.UI.AmountText("dmg", dmgTotal) .. G .. ")|r"
        leechFrom = dmgTotal
    elseif succeeded and dmgBonus ~= 0 then
        local parts = {}
        for _, p in ipairs(dmgParts) do
            table.insert(parts, { key = p.label, value = p.value })
        end
        bonusInfo = G .. " (|r" ..
            SB.UI.AmountText("eff", dmgBonus) .. G .. " к эффекту)|r"
    end
    local link = SB.UI.MakeSpellLink(spell)
    local sysMsg
    -- СЛОВО «ЗАКЛИНАНИЕ» УБРАНО, А ПОРЯДОК ОСТАЛСЯ ЧИСЛОМ В СКОБКАХ.
    --
    -- «применяет заклинание (Порядок: 2) [Огненный шар]» — существительное
    -- здесь пересказывает ссылку, которая стоит следом: что это
    -- заклинание, видно из самой карточки, и «способность» против
    -- «заклинания» игрок отличает по тому же признаку, по какому их
    -- отличает аддон, — по наличию порядка. Поэтому у заговора не пишется
    -- ничего, а у заклинания остаётся «(2)»: в этой строке скобка после
    -- ссылки может значить только порядок.
    local ordTxt = (slotLevel and slotLevel > 0) and (G .. " (" .. slotLevel .. ")") or ""
    if SB.Logic.IsGuaranteed(spell) then
        -- Выплата — в эту же строку: «применяет [Простое лечебное зелье]: +2 ХП.»
        local pay = SB.Logic.TakeCastPayload(spellID)
        sysMsg = SB.Theme.MSG_TAG .. "[Spellbreaker]:|r " .. G .. UnitName("player") ..
                 " применяет |r" .. link .. ordTxt .. G .. buffTargetNote ..
                 (pay and (": " .. pay) or "") .. ".|r"
    else
        -- СЛ показываем, только если она реально задана Ведущим. У
        -- заклинаний без сопротивления бросок идёт против нуля, и строка
        -- «против СЛ 0» читалась как сбой, хотя означала «сопротивляться
        -- нечему».
        local dcTxt = (dcNum > 0) and (G .. " против СЛ " .. dcNum) or ""
        -- «Результат:» не пишем: сам исход назван словом («Успех.»,
        -- «Провал.», «Критический успех!») и выкрашен в цвет исхода —
        -- подписывать его ещё и заголовком незачем.
        sysMsg = SB.Theme.MSG_TAG .. "[Spellbreaker]:|r " .. G .. UnitName("player") ..
                 " применяет |r" .. link .. ordTxt .. G .. bonusInfo .. buffTargetNote ..
                 " — |r" .. SB.UI.RollLine(roll, mod, total, G) .. dcTxt ..
                 G .. ". |r" .. resultStatus
    end
    SB.Events.Fire("BROADCAST_LOG", sysMsg, SB.LogRank.ACTION)

    -- ВАМПИРИЗМ в ПвЕ. Урон по НПС аддон никому не применяет — его
    -- отыгрывает Ведущий, — но число посчитано здесь, и в лог ушло
    -- именно оно, поэтому доля берётся от него. Своё здоровье при этом
    -- настоящее и растёт сразу (см. SB.Logic.ApplyLeech).
    if leechFrom > 0 then
        SB.Logic.ApplyLeech(spell, leechFrom)
    end

    -- «Нанёс урон» — вторая половина воронки для эффектов, спадающих от
    -- собственного удара (см. effect.breakOn в Core/ActiveEffects.lua).
    -- Первая половина — ATTACK_RESOLVED, но она приходит ответом от
    -- цели-игрока, а по НПС ответа нет: урон считает сам аддон, здесь.
    if leechFrom > 0 and SB.ActiveEffects and SB.ActiveEffects.BreakOn then
        SB.ActiveEffects.BreakOn("dealt")
    end

    -- RP-эмоут — только если у игрока задана отпись. Пустое поле
    -- (включая провал, у которого outcomeText = nil) —
    -- ничего не отправляем.
    if outcomeText and outcomeText ~= "" then
        local rpMsg = ApplyTemplates(outcomeText)
        if not SpellbreakerAccountDB or SpellbreakerAccountDB.sendEmotes ~= false then
            SendChatMessage(rpMsg, "EMOTE")
        end
    end

    -- Хук для будущих уникальных механик заклинаний, работающих через
    -- код (spell.onResolve = function(ctx) ... end). Оборачиваем в
    -- pcall — ошибка в чьей-то кастомной логике не должна ронять
    -- остальной резолв.
    if spell.onResolve then
        local ok, err = pcall(spell.onResolve, {
            spellID = spellID, spell = spell, roll = roll, mod = mod, total = total,
            dc = dcNum, succeeded = succeeded, isCrit = isCrit,
            slotLevel = slotLevel, hitBonus = hitBonus, critBonus = critBonus,
            dmgBonus = dmgBonus, caster = UnitName("player"),
        })
        if not ok then
            print(SB.Theme.MSG_TAG .. "[Spellbreaker]|r: " .. SB.Theme.MSG_BAD ..
                "Ошибка в onResolve заклинания " .. (spell.name or spellID) .. ": " .. tostring(err) .. "|r")
        end
    end
end

-- ============================================================
-- ПРИНУДИТЕЛЬНЫЙ РЕЗУЛЬТАТ (без броска d20, от ГМа)
-- ============================================================
function SB.Logic.ExecuteForcedOutcome(spellID, outcomeIndex, slotLevel)
    local spell = SB.Data.Spells[spellID]
    if not spell then return end

    SB.PlayerModel.SetLocked(true)
    if spell.caura and not (SpellbreakerAccountDB and SpellbreakerAccountDB.ignoreCaura)
       then SendChatMessage(".caura toggle " .. spell.caura, "SAY") end

    -- Единственная отпись игрока используется на исходах 1 (успех) и
    -- 3 (крит. успех) — на провале (2) отписи нет вообще.
    --
    -- ЧЕТВЁРТОГО ИСХОДА БОЛЬШЕ НЕТ: критический провал вырезан из аддона
    -- целиком. Индексы 1-3 оставлены как были — по ним ездят пакеты со
    -- старых клиентов, и сдвигать нумерацию значило бы превращать чужой
    -- «крит. успех» в «провал».
    local succeeded    = (outcomeIndex == 1 or outcomeIndex == 3)
    local outcomeText  = succeeded and SB.SpellOutcomes.Get(spellID) or nil
    local labels = { "Успех.", "Провал.", "Критический успех!" }

    local colorCode    = succeeded and "|cFF00FF00" or "|cFFFF0000"
    local resultStatus = colorCode .. (labels[outcomeIndex] or "Успех.") .. "|r"
    SB.Events.Fire("CAST_RESOLVED", spellID, succeeded, resultStatus, "Форсировано ГМом")

    local t = (tonumber(slotLevel) or 0) == 0 and "способность" or ("заклинание (Порядок: " .. (tonumber(slotLevel) or 0) .. ")")
    local link = SB.UI.MakeSpellLink(spell)
    local G    = "|cFFFFD100" -- тёплое золото вместо белого по умолчанию — читается лучше
    local sysMsg = "|cFF9933FF[Spellbreaker]:|r " .. G .. UnitName("player") ..
        " применяет " .. t .. " |r" .. link ..
        G .. ". Форсировано ГМом: |r" .. resultStatus

    -- РУЧНОГО ЦИКЛА ПО ЭФФЕКТАМ ЗДЕСЬ БОЛЬШЕ НЕТ. Он выглядел как то же
    -- самое, что SpendTurn, но отличался тремя вещами, и все три были
    -- ошибками:
    --   • не сбрасывал пройденный путь — после форсированного исхода
    --     персонаж оставался с накопленными метрами и мог упереться в
    --     предел, «ничего не сделав»;
    --   • не собирал тики в одну строку (FlushTickSummary), и три
    --     висящих эффекта давали три сообщения подряд;
    --   • шёл без пачки, поэтому каждый эффект слал группе свой пакет
    --     AEFFECT — ровно тот шторм, от которого TickAll и заведена.
    -- SpendTurn делает всё это одним вызовом; см. его же во всех
    -- остальных путях резолва.
    --
    -- ИСХОД ЗДЕСЬ ИЗВЕСТЕН: его назначил Ведущий, это и есть succeeded.
    -- Раньше контейнер вешался безусловно, и форсированный ПРОВАЛ всё
    -- равно давал заклинателю его ауру — то есть решение Ведущего
    -- действовало на цель и не действовало на самого заклинателя.
    -- Возвращённое значение здесь не нужно: его брали, чтобы отдать
    -- в TurnSkipFor, а хода тут больше нет.
    SB.Logic.ApplyOwnContainer(spell, slotLevel, succeeded)
    SB.Logic.GrantCreatedItems(spell, succeeded)

    -- ХОД ЗДЕСЬ НЕ ТРАТИТСЯ ВОВСЕ, и SpendTurn отсюда убран.
    --
    -- Форсированный исход — это ОТВЕТ Ведущего на заявку, а заявка
    -- тратит ход сразу, в момент отправки (см. ветку заявки в
    -- ConfirmCast). Списывать второй раз значило бы отнимать у игрока
    -- два хода за одно действие.
    --
    -- Эффекты тикнули тогда же, на заявке, а контейнер ложится уже
    -- после того тика — пропускать ему нечего, и TurnSkipFor здесь
    -- больше не нужна.

    -- ЭФФЕКТ НА ЦЕЛЬ — ТОЖЕ. Здесь вешался только собственный контейнер
    -- заклинателя, а spell.buff терялся: Ведущий жал «Успех», союзник
    -- ничего не получал. Тем же вызовом, что и в ProcessRollAndCast, —
    -- доставка эффекта живёт в одном месте (см. ApplyBuffToTarget).
    if succeeded and spell.buff then
        SB.Logic.ApplyBuffToTarget(spell, slotLevel)
    end
    -- Сотворение вызвано ВЫШЕ, вместе с контейнером и по тому же исходу.
    -- Здесь стоял второй его вызов — безусловный, — и после того как
    -- верхний научился спрашивать succeeded, эти двое выдали бы вещь
    -- дважды, причём и на форсированном провале.

    SB.Events.Fire("BROADCAST_LOG", sysMsg, SB.LogRank.ACTION)
    if outcomeText and outcomeText ~= "" then
        local rpMsg = ApplyTemplates(outcomeText)
        if not SpellbreakerAccountDB or SpellbreakerAccountDB.sendEmotes ~= false then
            SendChatMessage(rpMsg, "EMOTE")
        end
    end

    -- Ход в очереди закрывает сам SpendTurn выше (см. Core/TurnOrder.lua).
    SB.Events.Fire("STATUS_CHANGED")
end

-- ============================================================
-- ПВП (авто-резолв между игроками, минуя ГМа)
-- Срабатывает, если у заклинания canCrit = true и в таргете
-- другой игрок (не сам каст-, не НПС).
-- ============================================================

-- Запоминаем, каким заклинанием мы атаковали кого, чтобы когда
-- придёт результат защиты — знать, какую отпись (outcome) слать.
local pendingPvpSpells = {}

--- Атакующая сторона: считает свой бросок и шлёт его цели.
function SB.Logic.InitiatePvpAttack(spellID, slotLevel)
    local PM    = SB.PlayerModel
    local spell = SB.Data.Spells[spellID]
    if not spell or not UnitExists("target") then return end

    local targetName = UnitName("target")
    local mod, modParts = SB.Logic.GetModifierBreakdown("attack",
        { spell = spell, slotLevel = slotLevel, versus = targetName })

    -- ПвП-размен начался: с этого момента лидер больше не может
    -- объявить Короткий Отдых всей группе (см. PM.IsPvpEngaged).
    SB.PlayerModel.SetPvpEngaged(true)

    -- Базовый урон от вложенного ресурса (см. GetCastPower). Прибавка к
    -- попаданию из той же функции уже в mod — источник "resource".
    local baseDmg = SB.Logic.GetCastPower(spell, slotLevel)

    -- Скейлинг от характеристик (см. GetSpellScaling).
    local hitBonus,  hitParts = SB.Logic.GetSpellScaling(spell, "hit")
    local critBonus           = SB.Logic.GetSpellScaling(spell, "crit")
    local dmgBonus            = SB.Logic.GetSpellScaling(spell, "damage", slotLevel)
    -- Урон от своих баффов/дебаффов считается ЗДЕСЬ, у атакующего:
    -- у защищающегося клиента нет доступа к нашим эффектам, а едет по
    -- сети уже готовое число (см. SB.Net.SendPvpAttack).
    if SB.ActiveEffects and SB.ActiveEffects.GetDamageMod then
        dmgBonus = dmgBonus + (SB.ActiveEffects.GetDamageMod(spell))
    end
    mod = mod + hitBonus
    for _, p in ipairs(hitParts) do table.insert(modParts, p) end

    local roll, _, rollMax = SB.Logic.Roll()
    local total  = roll + mod
    -- Крит — по чистому кубику, как и в ПвЕ (см. GetCritThreshold).
    local isCrit = roll >= SB.Logic.GetCritThreshold(critBonus, rollMax)

    -- atkTotal запоминаем, чтобы по ответу защищающегося отличить
    -- ПРОМАХ от попадания, которое полностью съела броня: в обоих
    -- случаях приходит dmg = 0, но для классовых механик это разные
    -- события (Воин копит с попадания, ОнД — только с промаха).
    pendingPvpSpells[targetName] = { spellID = spellID, isCrit = isCrit, atkTotal = total }

    -- «Внушение» — прибавка не к попаданию, а к ЗАКРЕПЛЕНИЮ дебаффа
    -- (см. SB.Skills.GetPersuasionDebuffBonus). Проверяет её цель, у себя,
    -- вместе со своей «Волей» — значит число обязано доехать в пакете:
    -- своих навыков она не видит так же, как не видит наш урон.
    local persuade = (SB.Skills and SB.Skills.GetPersuasionDebuffBonus)
        and SB.Skills.GetPersuasionDebuffBonus(spell) or 0

    -- Атака больше НЕ печатает своё отдельное сообщение в лог/чат.
    -- Единое финальное сообщение (атака + защита + итог) собирает
    -- и рассылает защищающаяся сторона — см. HandlePvpAttackReceived.
    -- dmgBonus и baseDmg считаем здесь (наши собственные атрибуты и
    -- наш класс/вложенная мана) и шлём по сети — у защищающегося
    -- клиента нет доступа ни к тому, ни к другому. Вместе с ними едет и
    -- РАЗБИВКА нашего модификатора: сообщение о бое собирает
    -- защищающаяся сторона, и без разбивки в тултипе на модификаторе
    -- атакующего значилось «Нет данных о разбивке» — у обоих игроков.
    SB.Net.SendPvpAttack(targetName, spellID, roll, mod, total, isCrit, dmgBonus, baseDmg, slotLevel, persuade)

    -- СОБСТВЕННЫЙ КОНТЕЙНЕР АТАКУЮЩЕГО (буря вокруг себя, стойка, аура).
    -- В ПвЕ его вешает ProcessRollAndCast, а здесь этой ветки нет — и
    -- «Огненный ливень», применённый по игроку, не давал заклинателю
    -- ничего, хотя по НПС давал. Вешаем на факт каста: исход прилетит
    -- ответом позже, а поле вокруг заклинателя уже бушует.
    --
    -- ИСХОД ЭТОЙ ВЕТКЕ НЕ ИЗВЕСТЕН: его считает защищающийся и присылает
    -- ответом позже (см. HandlePvpAttackResult). Ждать нечего — вешаем
    -- сразу, третьей строкой правила из ApplyOwnContainer.
    local ownContainer = SB.Logic.ApplyOwnContainer(spell, slotLevel, nil)
    SB.Logic.GrantCreatedItems(spell, nil)

    -- Атака — потраченный ход, как и любой другой каст. Но тратится он
    -- по приходу итога от цели (см. HoldTurnUntilResult).
    SB.Logic.HoldTurnUntilResult(SB.Logic.TurnSkipFor(spell, spellID, ownContainer))
end


-- ============================================================
-- ВАМПИРИЗМ (spell.leech)
--
-- Часть нанесённого урона заклинатель забирает себе в здоровье. Это не
-- лечение и броском не проверяется: попал — забрал. Поэтому вампиризм
-- и не идёт путём ResolveHeal, у которого свой порог и своя «Милость».
--
-- ЧИСЛО БЕРЁТСЯ ИЗ ФАКТИЧЕСКОГО УРОНА, а не из своей заявки. В ПвП урон
-- считает и применяет ЗАЩИЩАЮЩАЯСЯ сторона (своя броня, свои дебаффы),
-- и приезжает он готовым в ответе PVPRES — вот его долю и берём. Иначе
-- заклинатель лечился бы с урона, который цель полностью отбила.
--
-- ФОРМАТ (в описании заклинания):
--   leech = 0.5,                    -- половина нанесённого урона
--   leech = 50,                     -- то же самое, процентом
--   leech = { share = 0.5, max = 5 } -- с потолком за один каст
-- ============================================================

--- Доля урона, уходящая заклинателю в здоровье. 0 — вампиризма нет.
function SB.Logic.GetLeechShare(spell)
    local l = spell and spell.leech
    if type(l) == "table" then l = l.share end
    local share = tonumber(l) or 0
    if share <= 0 then return 0 end
    -- Долю принимаем и дробью (0.5), и процентом (50): в данных
    -- заклинаний соседствуют оба способа записи чисел, и молча
    -- перепутанный формат дал бы вампиризм в полсотни жизней.
    if share > 1 then share = share / 100 end
    return math.min(share, 1)
end

--- Сколько ХП вернёт вампиризм с урона dmg (до зажима по максимуму).
function SB.Logic.GetLeechAmount(spell, dmg)
    local share = SB.Logic.GetLeechShare(spell)
    dmg = tonumber(dmg) or 0
    if share <= 0 or dmg <= 0 then return 0 end

    -- Хотя бы единица: половина от единичного урона — это ноль, и на
    -- заговорах механика молча превращалась бы в ничто.
    local healed = math.max(1, math.floor(dmg * share + 0.5))

    local cap = (type(spell.leech) == "table") and tonumber(spell.leech.max)
    if cap and healed > cap then healed = cap end
    return healed
end

--- Забрать жизнь: лечит заклинателя и объявляет это в лог.
--- @param intoReport boolean|nil  true — сложить в общий блок площадного
---        залпа, а не печатать отдельной строкой: задетых бывает пятеро,
---        и пять строк «+1 ХП» подряд — это шум, а не отчёт.
--- @return number  сколько РЕАЛЬНО влилось (0, если здоровье уже полное)
function SB.Logic.ApplyLeech(spell, dmg, intoReport)
    local amount = SB.Logic.GetLeechAmount(spell, dmg)
    if amount <= 0 then return 0 end

    local PM     = SB.PlayerModel
    local before = PM.GetHealth()
    PM.Heal(amount)                       -- зажимает по максимуму сам
    local healed = PM.GetHealth() - before
    if healed <= 0 then return 0 end      -- полное здоровье — забирать некуда

    -- Здоровье изменилось: синхронизируем с группой, как это делает
    -- любое другое лечение (см. HandleHealReceived).
    SB.Events.Fire(SB.E.STATUS_CHANGED)

    -- Площадь складывает вытянутую жизнь в свой блок сама
    -- (см. SB.Logic.AoeReportAddLeech в Core/Logic/Aoe.lua). Сложилось —
    -- своей строкой не печатаем.
    if intoReport and SB.Logic.AoeReportAddLeech(healed) then
        return healed
    end

    local G = SB.Theme.MSG_BODY
    SB.Events.Fire(SB.E.BROADCAST_LOG,
        -- Заклинание не называем: оно названо строкой выше, в шапке
        -- собственного каста, и эта строка приклеена к ней тем же блоком.
        SB.Theme.MSG_TAG .. "[Spellbreaker]:|r " .. G .. UnitName("player") ..
        " вытягивает жизнь: |r" .. SB.Theme.MSG_GOOD .. "+" .. healed .. " ХП|r" ..
        G .. ".|r",
        SB.LogRank.RESULT)
    return healed
end

--- База порога закрепления эффекта: чистая 60, без уровня. Вынесена
--- в константу, потому что от неё считаются ВСЕ пороги эффектов —
--- одиночные, площадные и каст на себя.
local EFFECT_BASE_THRESHOLD = 60

--- ПОРОГ ПО ЧИСЛУ УРОВНЯ, а не по юниту: 60 плюс уровень по эталонной
--- шкале.
---
--- ЗАЧЕМ ОТДЕЛЬНО ОТ EffectThreshold. Та спрашивает уровень у ИГРОВОГО
--- ЮНИТА (UnitLevel), и это верно ровно там, где юнит есть. У половины
--- расчётов его нет: у существа уровень лежит в его записи, у площадного
--- залпа — свой у каждого задетого, у лечения — у того, кого лечат.
---
--- ПОКА ЭТОЙ ФУНКЦИИ НЕ БЫЛО, эти места писали «60 + …» руками, и таких
--- мест набралось ПЯТЬ: лечение, лечение существа, эффект на существо,
--- площадь и кража. Шестая копия одного числа — это не шесть порогов, а
--- один, из которого пять однажды не поедут за правкой. Ровно та же
--- болезнь, что была у собственного контейнера заклинателя и у объёма
--- исходящего исцеления.
--- @param level number|nil  уровень цели «как в игре» (не эталонный)
--- @return number
function SB.Logic.BaseThresholdFor(level)
    return math.floor(EFFECT_BASE_THRESHOLD
        + SB.Data.ToReferenceLevel(tonumber(level) or 1))
end

--- Порог закрепления эффекта на юните: 60 + его уровень по эталонной
--- шкале, плюс «Воля», если эффект враждебный.
---
--- КАСТ НА СЕБЯ — исключение: там порог ровно 60, без уровня. Уровень
--- в пороге означает «чем матёрее цель, тем труднее на неё что-то
--- навесить», и к собственным аурам/стойкам это отношения не имеет:
--- получалось, что персонаж тем хуже владеет своими же заклинаниями,
--- чем он опытнее. Вдобавок надбавка ехала по эталонной шкале, то есть
--- на Sanctuary (кап 100) она растягивалась и один и тот же баф на
--- себя стоил разного на разных реалмах.
--- ЧЕМ СОПРОТИВЛЯЮТСЯ — РЕШАЕТ САМ ДЕБАФФ.
---
--- Раньше планку поднимала одна «Воля», одинаково против всего: и
--- против удара по почкам, и против насмешки, и против яда. Стойкость
--- была одна на все случаи, и «крепкий телом» ничем не отличался от
--- «твёрдого духом».
---
--- Теперь каждый дебафф называет своё (effect.resist), и модификатор
--- этого атрибута идёт в порог ДВОЙНЫМ: сопротивление — единственное,
--- ради чего его вкладывают против этого дебаффа, и половинной доли
--- тут мало, чтобы решение было заметным.
---
--- Не назвал — сопротивляться нечем, порог голый. Это НЕ поблажка:
--- дебафф без сопротивления обычно и не про стойкость (метка, клеймо,
--- чары на оружии), а тот, что про неё, разберут поимённо.
---
--- ТРЕТЬЕГО ПАРАМЕТРА «Воля» ЗДЕСЬ БОЛЬШЕ НЕТ. Он какое-то время
--- стоял пустым местом «ради старых вызовов», и это было ловушкой:
--- имя обещало слагаемое, которого давно нет, а восемь вызовов
--- передавали в него nil, делая вид, что оно чему-то служит.
---
--- @param onSelf boolean|nil    true — эффект ложится на самого себя
--- @param resistMod number|nil  модификатор названного атрибута или
---        НАВЫКА у того, по кому бьют (см. SB.Logic.OwnResistMod)
function SB.Logic.EffectThreshold(unit, isDebuff, onSelf, resistMod)
    local threshold = EFFECT_BASE_THRESHOLD
    if not onSelf then
        threshold = threshold + SB.Data.ToReferenceLevel(UnitLevel(unit) or 1)
    end
    -- floor в конце, а не внутри: ToReferenceLevel возвращает дробное
    -- число на реалме с капом, отличным от эталонного.
    threshold = math.floor(threshold)
    if isDebuff then
        threshold = threshold + 2 * (tonumber(resistMod) or 0)
    end
    return threshold
end

--- Чем этот эффект полагается преодолевать. Имя атрибута или НАВЫКА,
--- либо nil. Читается и из самого эффекта, и из заклинания, которое его
--- вешает: автор волен написать поле там, где ему удобнее.
function SB.Logic.DebuffResistStat(effectID, sourceSpell)
    local eff = (type(effectID) == "table") and effectID
                or SB.Data.Spells[effectID]
    local named = (eff and type(eff.effect) == "table" and eff.effect.resist)
                  or (eff and eff.resist)
                  or (sourceSpell and sourceSpell.resist)
    if type(named) ~= "string" or named == "" then return nil end
    return named
end

--- Насколько СВОЙ персонаж стоек к названному дебаффу — в модификаторах.
---
--- Считается только у себя, и это не ограничение, а суть: у чужого
--- клиента этих чисел нет и взять их неоткуда. Игровое API отдаёт про
--- цель уровень и здоровье, но не характеристики; когда-то я вёз их
--- отдельным полем сетевого статуса, и это было лишним — решение всё
--- равно принимает тот, по кому бьют (см. SB.Logic.HandleBuffReceived).
---
--- ИМЕННО ПОЭТОМУ ЗДЕСЬ РАБОТАЮТ И НАВЫКИ, а не одни атрибуты: пока
--- число ехало по сети, возить пришлось бы ещё и весь список навыков.
--- У себя же спрашивается и то, и другое одинаково дёшево.
--- ЧЕРЕЗ GetCheckModifier, А НЕ ЧЕРЕЗ ГОЛЫЙ GetModifier: у навыка к его
--- собственному модификатору прибавляется родительский атрибут — ровно
--- так считается любая проверка навыка в аддоне. Атрибуту родителя нет,
--- и для него функция возвращает то же самое, что возвращала раньше:
--- сто тридцать семь готовых дебаффов от этой замены не дрогнули.
function SB.Logic.OwnResistMod(statName)
    if type(statName) ~= "string" or statName == "" then return 0 end
    if not (SB.Skills and SB.Skills.GetCheckModifier) then return 0 end
    return tonumber((SB.Skills.GetCheckModifier(statName))) or 0
end

-- ============================================================
-- ЗВУКОВОЙ ОТКЛИК НА ИСХОД СВОЕГО ДЕЙСТВИЯ
--
-- Большинство путей резолва заканчивается событием CAST_RESOLVED, и
-- звук для них висит одной подпиской в UI/MainFrame.lua. Но два пути
-- этого события не шлют и слать не могут:
--   * ПвП-удар — исход приходит ответом защищающейся стороны, а на
--     CAST_RESOLVED подписаны классовые механики, для которых ПвП уже
--     отработан через ATTACK_RESOLVED (двойной триггер);
--   * лечение — свой самостоятельный резолв.
-- Им звук нужен ровно так же, поэтому вот общая точка на оба.
--
-- ЗАЩИТА и сопротивление чужому эффекту звука не получают намеренно:
-- игрок не выбирал этот момент, и отклик на чужое действие только сбивал
-- бы с толку.
-- ============================================================
function SB.Logic.PlayOutcomeSound(succeeded)
    if not SB.Theme or not SB.Theme.PlaySound then return end
    SB.Theme.PlaySound(succeeded and "success" or "fail")
end

-- ============================================================
-- ПАДЕНИЕ В 0 ХП ОТ ПвП-УДАРА
--
-- Персонаж, которого добили, сам отправляет серверному эмулятору
-- команду ауры «павший» (Config.DeathCaura). Отправляет именно он: та же
-- логика, что и у .caura при касте — команда действует на того, от чьего
-- имени написана.
--
-- Флаг нужен, чтобы каждый следующий удар по уже лежащему не слал
-- команду заново: .caura toggle ПЕРЕКЛЮЧАЕТ ауру, и второй удар просто
-- снял бы её обратно. Снимается, как только здоровье снова выше нуля
-- (лечение, отдых) — тогда следующая смерть отработает как первая.
-- ============================================================
local pvpDeathSent = false

--- @param before number  здоровье ДО удара
local function CheckPvpDeath(before)
    local hp = SB.PlayerModel.GetHealth()
    if hp > 0 then
        pvpDeathSent = false
        return
    end
    -- Именно ПАДЕНИЕ в ноль: тот, кто уже лежал до удара, ауру не
    -- переключает.
    if before <= 0 or pvpDeathSent then return end

    local caura = SB.Data.Config.DeathCaura
    if not caura then return end
    -- Тот же выключатель, что и у .caura заклинаний: чекбокс
    -- «Игнорировать .caura» обещает, что аддон вообще не пишет .caura.
    if SpellbreakerAccountDB and SpellbreakerAccountDB.ignoreCaura then return end

    pvpDeathSent = true
    SendChatMessage(".caura toggle " .. caura, "SAY")
end

--- Защищающаяся сторона: получает бросок атакующего, считает свой,
--- сравнивает и, если проиграл, теряет базовый урон атакующего
--- (+его скейлинг, ×CritDamageMultiplier при крите, −своя броня).
--- @param isAoe boolean|nil  удар пришёл площадью: сообщение уходит
---        короткой строкой под общую шапку залпа (см. InitiateAoeAttack).
--- @param fromNpc boolean|nil  бьёт существо от руки Ведущего: сверка
---        чисел к нему не применяется (см. SB.Logic.VerifyIncomingDamage).
function SB.Logic.HandlePvpAttackReceived(attackerName, spellID, atkRoll, atkMod, atkTotal, atkCrit,
                                          atkDmgBonus, atkBaseDmg, atkSlot, isAoe, atkPersuade,
                                          fromNpc)
    local PM    = SB.PlayerModel
    local spell = SB.Data.Spells[spellID]

    -- Жертва размена вовлечена в бой ровно так же, как нападающий:
    -- объявлять группе отдых, пока по тебе бьют, нельзя.
    PM.SetPvpEngaged(true)

    -- СВЕРКА ЧУЖОГО КАСТА. Считаем её здесь, у защищающегося: это
    -- единственная сторона, которой подлог не выгоден (см.
    -- SB.Logic.VerifyIncomingCast). Если что-то не сходится, дальше идёт
    -- ПЕРЕСЧИТАННЫЙ итог, а не присланный, и вся группа видит претензию
    -- прямо в строке боя.
    local tamperNote
    atkTotal, tamperNote = SB.Logic.VerifyIncomingCast(
        attackerName, spellID, atkRoll, atkMod, atkTotal, atkSlot, fromNpc)

    -- ЧИСЛА УРОНА — ОТДЕЛЬНОЙ СВЕРКОЙ, и это не придирка к оформлению.
    -- Проверка выше смотрит на БРОСОК: попал ли вообще. А отнимается
    -- здоровье по совсем другим полям — базе и скейлингу, — и они до сих
    -- пор принимались на веру целиком. Подменённому клиенту хватало
    -- согласованной тройки «бросок-модификатор-итог», чтобы приложить
    -- сотней урона: арифметика в ней честная, а сотня лежит рядом.
    local dmgNote
    atkBaseDmg, atkDmgBonus, dmgNote = SB.Logic.VerifyIncomingDamage(
        spell, atkSlot, atkBaseDmg, atkDmgBonus, fromNpc)
    if dmgNote then
        tamperNote = tamperNote and (tamperNote .. "; " .. dmgNote) or dmgNote
    end

    -- КРИТ — ТОЖЕ СВЕРЯЕМ, и теперь это не роскошь. Он удваивает урон и
    -- пробивает защиту без броска (строкой ниже), а приезжает готовым
    -- флагом от атакующего. Полоса крита не бывает шире своего потолка
    -- ни у кого, значит и кубик ниже этой грани критом быть не может
    -- (см. SB.Logic.MinPlausibleCritRoll). Существу верим: его бросок
    -- считает тот же Ведущий, что и всё остальное в сцене.
    if atkCrit and not fromNpc then
        local floorRoll = SB.Logic.MinPlausibleCritRoll(SB.Logic.ROLL_MAX)
        if (tonumber(atkRoll) or 0) < floorRoll then
            atkCrit = false
            local note = string.format("крит на кубике %d при грани %d",
                tonumber(atkRoll) or 0, floorRoll)
            tamperNote = tamperNote and (tamperNote .. "; " .. note) or note
        end
    end

    -- «БЕЗ СОПРОТИВЛЕНИЯ» — ЗНАЧИТ БЕЗ ЗАЩИТНОГО БРОСКА (см.
    -- SB.Logic.IsGuaranteed). Бросок не просто игнорируется, а не
    -- катится вовсе: числа, которые ни на что не влияют, поехали бы в
    -- строку боя и читались бы как «защита проиграла», хотя защиты
    -- не было.
    local guaranteed = SB.Logic.IsGuaranteed(spell)

    -- ПРОТИВ КРИТА ЗАЩИТА НЕ БРОСАЕТСЯ — ровно до тех пор, пока её итогу
    -- некуда примениться.
    --
    -- Крит попадает всегда (см. landed ниже), так что попадание бросок
    -- уже не решает. Но ОДНО применение у него осталось: заклинание с
    -- дебаффом меряет закрепление чар именно этим итогом, и «Стойкость»
    -- с «Волей» против крита работают по-прежнему. Убери бросок совсем —
    -- сравнивать стало бы не с чем, и дебафф крита ложился бы сам собой.
    --
    -- Поэтому развилка по самому заклинанию, а не по флагу: дебаффа нет —
    -- итог не нужен никому, и катить его значит печатать в строку боя
    -- числа, которые ни на что не влияют. Ровно тот же довод, по
    -- которому не бросает «без сопротивления», и ровно та жалоба, с
    -- которой правило и начали: «крит, а страж всё равно кидает куб».
    local skipDefense = guaranteed or (atkCrit and not (spell and spell.debuff))

    -- Область "defense": ни Мастерство, ни Ловкость сюда не входят —
    -- только Акробатика, Концентрация, профиль класса и висящие эффекты.
    -- Все они обычные источники реестра, поэтому целиком видны в разбивке
    -- тултипа у обеих сторон размена.
    local defMod, defRoll, defTotal = 0, 0, 0
    if not skipDefense then
        -- versus — нападающий: провокация не мешает уворачиваться от
        -- того, кто её и наложил (см. её источник в реестре).
        defMod   = SB.Logic.GetModifierBreakdown("defense",
            { spell = spell, versus = attackerName })
        defRoll  = SB.Logic.Roll()
        defTotal = defRoll + defMod
    end

    -- ПОПАДАНИЕ. Дальше по функции сравнения бросков больше нет — только
    -- этот флаг: иначе гарантированный удар пришлось бы дописывать в
    -- пять разных мест (урон, дебафф, текст исхода, ответ, onResolve), и
    -- одно из них обязательно бы забылось.
    --
    -- КРИТ ПОПАДАЕТ ВСЕГДА. Отвести его нельзя ничем: это и есть смысл
    -- критического удара, и полоса под него теперь целиком
    -- зарабатывается (см. Config.CritBand) — даром он не достаётся
    -- никому, так что и «автоуспех даром» отсюда не выходит.
    --
    -- ЗАЩИТА ПРИ ЭТОМ ВСЁ РАВНО БРОСАЕТСЯ, и это не противоречие. Её
    -- итог перестал решать, попал ли удар, но остался нужен ниже —
    -- дебафф от попадания меряется именно им (см. врезку о «Стойкости»
    -- там же). Убери мы бросок совсем — сравнивать закрепление чар
    -- стало бы не с чем, и любой дебафф крита ложился бы сам собой.
    local landed = guaranteed or atkCrit or (atkTotal > defTotal)

    -- Броня работает ПОСЛЕ проверки попадания: увернуться она не
    -- помогает (это Акробатика), но гасит уже прошедший урон — и гасит
    -- ЦЕЛИКОМ, если запаса хватает.
    --
    -- ЗАПАС ПРИ ЭТОМ ТРАТИТСЯ: каждая поглощённая единица урона стоит
    -- десяти единиц брони и возвращается только Долгим Отдыхом (см.
    -- SB.Skills.AbsorbDamage). Поэтому здесь именно списание, а не
    -- чтение: удар, дошедший до брони, её и расходует.
    --
    -- Config.MinDamageOnHit остался ТОЛЬКО как пол СОБСТВЕННОГО урона
    -- удара (строкой ниже) — до брони. Гасить им броню больше не нужно:
    -- «неуязвимый латник», ради которого пол и вводился, кончается сам,
    -- когда кончается запас.
    --
    -- Базовый урон приходит ОТ АТАКУЮЩЕГО (SB.Logic.GetCastPower): он
    -- зависит от его класса и от того, сколько маны он влил, а этого
    -- нам локально не видно. Фолбэк на Config.BaseDamage — для пакетов
    -- со старых клиентов, которые поле baseDmg ещё не шлют.
    local healthBefore = PM.GetHealth()
    local dmg, rawDmg, reduction, resisted = 0, 0, 0, 0
    if landed then
        local base = tonumber(atkBaseDmg) or SB.Data.Config.BaseDamage or 1
        local scal = tonumber(atkDmgBonus) or 0
        -- Тот же пол, что и в ПвЕ-ветке: попавший удар не может стоить
        -- ноль ещё ДО брони (у заклинаний выше нулевого круга базы
        -- больше нет, см. GetCastPower).
        local sum = math.max(SB.Data.Config.MinDamageOnHit or 1, base + scal)
        -- ЗАЩИТА СЧИТАЕТСЯ ПО СИЛЕ УДАРА, А КРИТ УДВАИВАЕТ ПРОШЕДШЕЕ.
        --
        -- Порядок здесь решает больше, чем любое из чисел: доспех
        -- вычитается плоско, и до перестановки удвоение доходило до
        -- цели как ушестерение (см. врезку у SB.Logic.ApplyCritDamage).
        --
        -- СНАЧАЛА СОПРОТИВЛЕНИЕ, ПОТОМ ДОСПЕХ — см. врезку у
        -- SB.Skills.MitigateDamage. Школа удара берётся ИЗ СВОЕЙ
        -- БИБЛИОТЕКИ, а не из пакета: определение заклинания у всех
        -- одинаковое, везти поле по сети незачем — и подделать его тогда
        -- тоже не выйдет (тот же довод, что у resistable,
        -- см. SB.Logic.IsGuaranteed).
        local dmgType = spell and spell.damageType
        local through
        through, resisted, reduction = SB.Skills.MitigateDamage(sum, dmgType)
        dmg = SB.Logic.ApplyCritDamage(through, atkCrit)
        -- rawDmg — сила удара ДО защиты: её показывает лог («удар
        -- выдержан целиком» считается именно по ней).
        rawDmg = sum
        if dmg > 0 then
            PM.GrantHealth(-dmg)
        end

        -- ЩИТЫ И АУРЫ ОТВЕЧАЮТ ЗДЕСЬ — по факту прошедшего удара и с
        -- именем того, кто его нанёс (см. onAction в Core/ActiveEffects.lua).
        --
        -- Даже если урон целиком съели доспех и сопротивление: «кто-либо
        -- попытался навредить» — это про попытку, а не про пробитие.
        if SB.ActiveEffects and SB.ActiveEffects.FireAction then
            SB.ActiveEffects.FireAction("damaged", spell, attackerName)
        end
    end

    -- ДЕБАФФ ОТ ПОПАДАНИЯ. Вешаем его СЕБЕ, локально: заклинание уже
    -- прилетело, его определение у нас есть, и никакого дополнительного
    -- пакета не нужно — а значит нет и нового способа навязать чужому
    -- персонажу эффект (ADDEFF по-прежнему только от лидера).
    -- Поле spell.debuff = "<id эффекта>", см. Spells/Effects.lua.
    --
    -- СТОЙКОСТЬ поднимает планку ИМЕННО ДЛЯ ДЕБАФФА, а не для всей
    -- защиты: удар всё равно проходит и урон всё равно снимается, но
    -- зацепиться за стойкого чары уже не могут. Считается локально —
    -- этот путь и так исполняется у цели (см. SB.Logic.OwnResistMod).
    -- ИМЯ ЭФФЕКТА НЕ ЗАПОМИНАЕМ, только факт: наложился или отведён.
    -- Что именно вешает заклинание, написано в его карточке, а ссылка на
    -- него в этой же строке кликабельна. Заодно имя перестало ездить по
    -- сети в ответе PVPRES.
    --
    -- «ВНУШЕНИЕ» АТАКУЮЩЕГО ПРИБАВЛЯЕТСЯ ИМЕННО ЗДЕСЬ, а не к его броску.
    -- Навык отвечает за то, чтобы чары ЗАЦЕПИЛИСЬ, и подмешивать его в
    -- попадание нельзя: тогда развитое «Внушение» поднимало бы ещё и урон
    -- каждого уронного заклинания, у которого дописан дебафф. Число
    -- считает атакующий (свой навык он знает точно) и везёт в пакете —
    -- ровно как урон и базу; см. SB.Skills.GetPersuasionDebuffBonus.
    local debuffLanded, debuffResisted = false, false
    -- ЧЕМ ИМЕННО ОТВЕЛИ — запоминаем для строки боя. Раньше там стояло
    -- «Воля отвела дебафф», и это была неправда с тех пор, как Воля
    -- перестала поднимать порог: отводит тот атрибут, который назван в
    -- карточке самого дебаффа, а он у каждого свой (у «Смертельного
    -- удара» — Выносливость). Строка обещала игроку вкладываться в Волю
    -- там, где Воля ни при чём.
    local resistStat
    if spell and spell.debuff and landed then
        -- СОПРОТИВЛЕНИЕ СЧИТАЕМ ЗДЕСЬ, у себя: этот путь исполняется на
        -- стороне цели, и свои характеристики она знает точно — везти их
        -- по сети незачем (см. SB.Logic.EffectThreshold о том, почему
        -- прибавка двойная).
        resistStat = SB.Logic.DebuffResistStat(spell.debuff, spell)
        local resistBonus = 2 * SB.Logic.OwnResistMod(resistStat)
        local persuade = math.max(0, tonumber(atkPersuade) or 0)
        if guaranteed or (atkTotal + persuade > defTotal + resistBonus) then
            -- ИМЯ НАПАДАЮЩЕГО ЕДЕТ В ЭФФЕКТ: провокации нужен тот, кто
            -- её наложил, а здесь он известен точно и бесплатно — это
            -- довод в пользу самого этого пути (см. врезку
            -- «ПРОВОКАЦИЯ» в Core/ActiveEffects.lua).
            SB.Logic.ApplyEffect(spell.debuff, spell, atkSlot, nil, nil, attackerName)
            debuffLanded = true
        else
            debuffResisted = true
        end
    end

    local newHealth = PM.GetHealth()
    local maxHealth = PM.GetMaxHealth()

    -- Добили — переключаем ауру «павший» на себе (см. CheckPvpDeath).
    -- До рассылки результата: команда эмулятору не должна ждать сети.
    CheckPvpDeath(healthBefore)

    -- ВОЗМЕЗДИЕ ЧИСЛАМИ уезжает вместе с итогом (см. TakeRetributions).
    -- Существу отвечать некому: у него нет клиента, который принял бы урон.
    local retrib = SB.ActiveEffects.TakeRetributions and SB.ActiveEffects.TakeRetributions() or {}
    if fromNpc or #retrib == 0 then retrib = nil end

    -- ЕДИНОЕ ФИНАЛЬНОЕ СООБЩЕНИЕ (атака + защита + итог одной строкой).
    -- G — основной цвет тела сообщения: тёплое золото вместо белого
    -- по умолчанию, читается заметно лучше на фоне чат-окна.
    local G          = SB.Theme.MSG_BODY
    local link       = spell and SB.UI.MakeSpellLink(spell) or (G .. "неизвестное заклинание|r")
    -- КРИТ — ГОЛОЙ ГРАНЬЮ. Когда выпал крит, модификатор и итог не решают
    -- ничего: попадание решила грань кубика. «[88]. КРИТ!» — ровно то, что
    -- случилось, без «(КРИТ!)» у названия и «крит — защиты нет» после
    -- броска, которые говорили одно и то же дважды.
    local critTxt    = ""
    -- Три исхода: промах, доспех выдержал, урон. Средний вернулся вместе
    -- с бронёй-запасом: она снова умеет погасить удар целиком, и молчать
    -- об этом нельзя — «Урон: 0 ХП» читается как сбой, а не как работа
    -- доспеха. Разбивка (база, крит, скейлинг, броня) уехала из строки в
    -- подсказку на самом числе: в бою на несколько участников приписка
    -- «(5 урона - 2 броня)» у каждого удара забивала чат целиком.
    -- ЧЕМ ЗАКРЫЛСЯ — КОРОТКОЙ ПРИПИСКОЙ, и только если и правда закрылся.
    --
    -- Без неё сопротивление невидимо: игрок видит «Урон: 2», а было
    -- четыре, и понять, сработала ли раса, неоткуда. Тот же довод, по
    -- которому в строке живёт «дебафф отведён».
    --
    -- Школу называем ТОЛЬКО когда резист сработал: «Урон: 2 (огонь)» на
    -- каждом ударе — это подпись ради подписи, тип и так написан в
    -- карточке заклинания, ссылка на которую стоит в этой же строке.
    local guard = {}
    if resisted > 0 then
        local dt = SB.Data.GetDamageType(spell)
        -- Имя школы КАК ЕСТЬ. Строчную букву здесь напрашивается
        -- сделать через :lower(), но в Lua он побайтовый и кириллицу не
        -- трогает вовсе: вызов выглядел бы работающим, ничего не делая.
        guard[#guard + 1] = "резист " .. resisted ..
            (dt and (" (" .. dt.name .. ")") or "")
    elseif resisted < 0 then
        guard[#guard + 1] = "уязвимость +" .. (-resisted)
    end
    if reduction > 0 then guard[#guard + 1] = "доспех " .. reduction end
    local guardTxt = (#guard > 0)
        and (G .. " — " .. table.concat(guard, ", ") .. "|r") or ""

    local outcomeTxt
    if not landed then
        outcomeTxt = SB.Theme.MSG_GOOD .. "Атака отражена!|r"
    elseif dmg <= 0 then
        -- «Доспех выдержал» — только когда доспех и правда один это
        -- сделал. Сработал резист — заслуга общая, и приписывать её
        -- железу нельзя: разбивка тут же, в guardTxt.
        outcomeTxt = SB.Theme.MSG_GOOD ..
            ((resisted > 0) and "Удар выдержан целиком!" or "Доспех выдержал удар целиком!") ..
            "|r" .. guardTxt
    else
        -- БЕЗ «(7/42)»: здоровье и так видно на рамке (подмена ХП на
        -- стандартных рамках, см. UI/Overlay.lua), а в строке оно
        -- удлиняло каждый удар ради числа, на которое никто не смотрит.
        local dmgLink = SB.UI.AmountText("dmg", dmg)
        outcomeTxt = SB.Theme.MSG_BAD .. "Урон: |r" .. dmgLink ..
            SB.Theme.MSG_BAD .. " ХП|r" .. guardTxt
    end

    -- КРИТ — ЗАЩИТЫ НЕТ, ДАЖЕ ЕСЛИ КУБИК БРОШЕН. У крита с дебаффом
    -- бросок защиты катится: им меряется закрепление чар (см. врезку у
    -- landed выше). Но стоял он на месте защиты — «vs [95][+36]=131», — и
    -- строка читалась так, будто цель отбивалась от удара, которого
    -- отбить нельзя. Теперь на месте защиты «крит — защиты нет», а бросок
    -- стоит там, где он работает: у дебаффа.
    local critNoDefense = atkCrit and not guaranteed and not skipDefense
    local resistRoll = critNoDefense
        and (" " .. SB.UI.RollLine(defRoll, defMod, defTotal, G)) or ""
    if debuffLanded then
        outcomeTxt = outcomeTxt .. G .. " | |r" .. SB.Theme.MSG_BAD .. "дебафф наложен|r" ..
            ((resistRoll ~= "") and (G .. " (сопротивление" .. resistRoll .. G .. ")|r") or "")
    elseif debuffResisted then
        -- Без этой строки «Воля» была бы невидимой: игрок получил урон,
        -- дебаффа нет, и почему — непонятно.
        -- АТРИБУТ НАЗЫВАЕМ, если он есть: это единственное число,
        -- которое игрок может изменить заранее, и узнать его он должен
        -- из той же строки, где увидел исход. Не назван — значит
        -- отбиваться было нечем в принципе (метки и клейма, см.
        -- SB.Logic.DebuffResistStat), и скобки пустыми не ставим.
        outcomeTxt = outcomeTxt .. G .. " | |r" .. SB.Theme.MSG_GOOD ..
            "дебафф отведён" ..
            ((resistStat or resistRoll ~= "")
                and (" (" .. (resistStat or "") ..
                     ((resistStat and resistRoll ~= "") and ":" or "") ..
                     resistRoll ..
                     ((resistRoll ~= "") and SB.Theme.MSG_GOOD or "") .. ")")
                or "") .. "|r"
    end

    -- Цифры атакующего не сошлись между собой. Пишем это в ту же строку,
    -- что и исход: претензия должна быть видна всем участникам сцены и
    -- Ведущему, а не осесть в личном чате защищающегося.
    if tamperNote then
        outcomeTxt = outcomeTxt .. " " .. SB.Theme.MSG_BAD ..
            "[!] Цифры атакующего не сходятся: " .. tamperNote ..
            ". Считаем по пересчитанному.|r"
    end

    -- ФОРМА СООБЩЕНИЯ. У одиночного размена — полный абзац: он один, и
    -- назвать в нём заклинание с броском атакующего не жалко. У площадного
    -- всё это уже сказано в шапке залпа (см. InitiateAoeAttack), а
    -- задетых бывает пятеро — поэтому здесь остаётся только своя строка:
    -- кто, чем закрылся и что получил. Ссылки те же самые, так что вся
    -- разбивка по-прежнему доступна по наводке.
    if isAoe then
        -- В чат НЕ пишем: результат едет лично атакующему, и печатает его
        -- он — общим блоком, схлопнув одинаковые исходы в одну строку.
        -- Шлём именно ДАННЫЕ, а не готовую строку: чужие строки не
        -- сгруппировать, а заодно из пакета уходит вся разметка с цветами
        -- и ссылками — это примерно втрое короче.
        SB.Net.SendPvpResult(attackerName, UnitName("player"), defRoll, defMod, defTotal,
            dmg, newHealth, maxHealth, {
                landed   = landed,
                debuff   = debuffLanded,
                resisted = debuffResisted,
                retrib   = retrib,
            })
    else
        -- ОТВЕТ АТАКУЮЩЕМУ — ПОСЛЕ СТРОКИ БОЯ, следующим кадром. Строка
        -- уходит очередью кадра (см. SB.Net.QueueLogLine), и отправь мы
        -- ответ сразу, атакующий успевал бы разослать вампиризм и
        -- потратить ход раньше, чем группа прочла сам удар. Таймер
        -- заводится позже таймера очереди и потому срабатывает за ним.
        -- У гарантированного удара защитных чисел нет — и в строке их
        -- тоже нет: «vs Защита: 0 + 0 (итог 0)» читалось бы как сбой
        -- расчёта. Та же формулировка, что у гарантированного эффекта
        -- (см. ResolveEffectCast).
        local rollTxt
        if atkCrit and not guaranteed then
            rollTxt = SB.UI.RollText(atkRoll) .. G .. ". |r" ..
                      SB.Theme.MSG_BAD .. "КРИТ!|r "
        else
            local defTxt = skipDefense
                and (G .. ", цель не сопротивляется")
                or  (G .. " vs |r" .. SB.UI.RollLine(defRoll, defMod, defTotal, G))
            rollTxt = SB.UI.RollLine(atkRoll, atkMod, atkTotal, G) .. defTxt .. G .. ". |r"
        end
        -- «атакует X заклинанием [Y]» → «— [Y] по X»: два существительных
        -- из трёх пересказывали ссылку и стрелку, а третье («заклинанием»)
        -- не отличало удар от заклинания никак — бьют здесь всегда
        -- чем-то из библиотеки.
        local line = SB.Theme.MSG_TAG .. "[Spellbreaker]:|r " ..
            G .. attackerName .. " — |r" .. link .. critTxt ..
            G .. " по " .. UnitName("player") ..
            G .. ": |r" .. rollTxt .. outcomeTxt

        -- СТРОКА БОЯ И ИТОГ — ОДНИМ ПАКЕТОМ В ГРУППУ. Раньше строка шла
        -- в группу, а итог — лично атакующему, и порядок между двумя
        -- каналами WoW не держит: атакующий получал итог раньше строки и
        -- успевал разослать вампиризм, тики и «Ходит: …» до самого удара.
        -- Один пакет порядок держит сам: все печатают строку, а атакующий
        -- тут же, в том же обработчике, берёт из него итог (см. ParsePVPRES).
        --
        -- Через BROADCAST_LOG с приложением, а не мимо: у события одна
        -- подписка — сеть, — и она отправит пакет немедленно, в обход
        -- очереди кадра (ранга ACTION он и так первый).
        SB.Events.Fire(SB.E.BROADCAST_LOG, line, SB.LogRank.ACTION, {
            pvpResult = { attackerName, UnitName("player"), defRoll, defMod, defTotal,
                          dmg, newHealth, maxHealth, retrib },
        })
    end

    SB.Events.Fire("STATUS_CHANGED")

    if spell and spell.onResolve then
        local ok, err = pcall(spell.onResolve, {
            spellID = spellID, spell = spell, roll = atkRoll, mod = atkMod, total = atkTotal,
            defRoll = defRoll, defMod = defMod, defTotal = defTotal,
            -- succeeded — попадание состоялось (бросок пробил защиту либо
            -- заклинание объявлено без сопротивления), даже если весь урон
            -- затем съела броня; фактический урон смотри в dmg,
            -- поглощение — в reduction.
            --
            -- rawDmg — СИЛА УДАРА ДО ЗАЩИТЫ, и это уже не «dmg до брони»:
            -- крит умножает то, что прошло сквозь защиту, а не то, что в
            -- неё прилетело (см. врезку у SB.Logic.ApplyCritDamage).
            -- У крита dmg поэтому бывает БОЛЬШЕ rawDmg.
            succeeded = landed, isCrit = atkCrit,
            dmg = dmg, rawDmg = rawDmg, reduction = reduction,
            attacker = attackerName, defender = UnitName("player"),
        })
        if not ok then
            print(SB.Theme.MSG_TAG .. "[Spellbreaker]|r: " .. SB.Theme.MSG_BAD ..
                "Ошибка в onResolve заклинания " .. (spell.name or spellID) .. ": " .. tostring(err) .. "|r")
        end
    end
end

--- Атакующая сторона: получает итог защиты — единое сообщение уже
--- разослала защищающаяся сторона (см. HandlePvpAttackReceived), здесь
--- только шлём РП-отпись (outcome) заклинания по факту попадания/промаха.
--- @param aoe table|nil  данные для сжатого отчёта о залпе:
---        { parts = разбивка защиты, landed, debuff, resisted }
function SB.Logic.HandlePvpResultReceived(targetName, defRoll, defMod, defTotal, dmg, newHealth, maxHealth, aoe, retrib)
    -- Всё, что ответ печатает (вампиризм, отпись), идёт ДО траты хода:
    -- тики и сдвиг очереди — последние в цепочке (см. HoldTurnUntilResult).
    -- Площадь отпускает ход сама, по печати блока залпа.
    local ok, err = pcall(SB.Logic.HandlePvpResultBody, targetName, defRoll, defMod,
        defTotal, dmg, newHealth, maxHealth, aoe)
    -- ВОЗМЕЗДИЕ ЦЕЛИ — после строки удара и до траты хода: ударил,
    -- получил в ответ, потом тики. Не больше пяти источников за удар —
    -- пакет чужой, и бесконечный список из него не принимаем.
    if type(retrib) == "table" and SB.ActiveEffects and SB.ActiveEffects.ApplyRetribution then
        for i, id in ipairs(retrib) do
            if i > 5 then break end
            pcall(SB.ActiveEffects.ApplyRetribution, id)
        end
    end
    if not aoe then SB.Logic.ReleaseHeldTurn() end
    if not ok then error(err, 0) end
end

function SB.Logic.HandlePvpResultBody(targetName, defRoll, defMod, defTotal, dmg, newHealth, maxHealth, aoe)
    local pending = pendingPvpSpells[targetName]
    pendingPvpSpells[targetName] = nil

    -- Ответ на ПЛОЩАДНОЕ заклинание. Цели у него заранее неизвестны, и
    -- записи под конкретное имя нет — берём общий висящий размен. Он
    -- НЕ обнуляется первым же ответом: задетых несколько, и каждый
    -- отвечает отдельно. Отпись при этом уходит только один раз
    -- (emoteSent), иначе на площадь в трёх целей улетело бы три эмоута.
    local fromAoe = false
    local aoePending
    if not pending then
        -- Срок годности записи и её очистку держит сама площадь
        -- (см. SB.Logic.TakePendingAoe в Core/Logic/Aoe.lua).
        aoePending = SB.Logic.TakePendingAoe()
        if aoePending then
            pending = aoePending
            fromAoe = true
        end
    end

    local spellID = pending and pending.spellID

    -- Попадание определяем по броскам, а НЕ по факту урона: удар,
    -- полностью поглощённый бронёй, всё равно попал.
    --
    -- Заклинание «без сопротивления» попадает всегда, и здесь это надо
    -- посчитать ЗАНОВО: цель прислала свои нули (защитного броска у неё
    -- не было, см. HandlePvpAttackReceived), и сравнение с ними дало бы
    -- ложный промах — а от него зависят и вампиризм, и отпись, и
    -- классовые механики.
    -- Крит и здесь попадает всегда — тем же правилом и по той же
    -- причине, что у цели: разойдись эти две строки, и вампиризм с
    -- классовыми механиками считали бы промах там, где цель уже
    -- получила урон.
    local landed = SB.Logic.IsGuaranteed(spellID and SB.Data.Spells[spellID])
        or (pending ~= nil and pending.isCrit == true)
        or ((pending ~= nil and pending.atkTotal ~= nil)
            and (pending.atkTotal > (tonumber(defTotal) or 0))
            or false)

    -- Триггер уникальных механик некастеров (Воин копит ресурс с
    -- попадания, Охотник на демонов восполняет ресурс с промаха) —
    -- нужен независимо от того, есть ли у нас отпись для этого заклинания.
    -- ИМЯ ЦЕЛИ ЧЕТВЁРТЫМ ДОВОДОМ: по нему уходит onAction.toTarget —
    -- «с каждой атакой цель испытывает шанс получить оглушение».
    -- Доставляет эффект клиент цели, поэтому нужно именно имя игрока
    -- (см. врезку о возмездии в Core/ActiveEffects.lua).
    SB.Events.Fire(SB.E.ATTACK_RESOLVED, dmg, spellID, landed, targetName)

    -- Результат задетого — в общий блок залпа (см. OpenAoeReport).
    if aoe then
        SB.Logic.AoeReportAdd({
            kind     = "atk",
            name     = targetName,
            roll     = defRoll,
            mod      = defMod,
            total    = defTotal,
            landed   = aoe.landed,
            dmg      = dmg,
            hp       = newHealth,
            maxHp    = maxHealth,
            debuff   = aoe.debuff,
            resisted = aoe.resisted,
        })
    end

    -- Отклик на СВОЙ удар. Для площадного — один раз на весь залп, а не
    -- на каждого ответившего: пятеро задетых дали бы пять звуков подряд.
    -- Успехом считаем сам факт попадания хоть по кому-то.
    if pending and not fromAoe then
        SB.Logic.PlayOutcomeSound(landed)
    elseif pending then
        -- Площадь — через общий сборщик отчёта: у него и правило «не
        -- больше двух звуков на залп», и состояние (см. AoeReportSound).
        SB.Logic.AoeReportSound(landed)
    end

    local spell = spellID and SB.Data.Spells[spellID]
    if not spell then return end

    -- ВАМПИРИЗМ. Урон уже посчитала и применила к себе цель — берём его
    -- готовым из ответа (см. SB.Logic.ApplyLeech). Считается по каждому
    -- ответившему: площадное вампирическое заклинание тянет жизнь со
    -- всех задетых, а не с одного.
    if landed then
        SB.Logic.ApplyLeech(spell, dmg, fromAoe)
    end

    -- Отпись есть только при попадании — по факту ПОПАДАНИЯ, а не
    -- урона: заклинание сработало и отыгрывается даже если броня цели
    -- погасила весь урон. При промахе отписи нет.
    if not landed then return end
    if fromAoe and aoePending then
        -- Отметка живёт в самой записи залпа: отпись уходит один раз на
        -- всю площадь, а не по разу на каждого ответившего.
        if aoePending.emoteSent then return end
        aoePending.emoteSent = true
    end
    local outcomeText = SB.SpellOutcomes.Get(spellID)
    if not outcomeText or outcomeText == "" then return end

    local rpMsg = ApplyTemplates(outcomeText)
    if not SpellbreakerAccountDB or SpellbreakerAccountDB.sendEmotes ~= false then
        SendChatMessage(rpMsg, "EMOTE")
    end
end

-- ============================================================
-- ЛЕЧЕНИЕ (авто-резолв, минуя ГМа)
-- Срабатывает, если у заклинания isHeal = true.
-- Порог = 60 + уровень исцеляемого; шанс попасть в него поднимает навык
-- «Милосердие» (источник реестра "mercy"). Объём исцеления при успехе —
-- по той же шкале, что и урон: 1 ХП на заговоре и +1 за каждую
-- вложенную единицу маны (см. SB.Logic.GetCastPower), плюс скейлинг
-- канала damage.
-- ============================================================

function SB.Logic.ResolveHeal(spellID, slotLevel)
    local PM      = SB.PlayerModel
    local spell   = SB.Data.Spells[spellID]
    if not spell then return end
    if not UnitExists("target") or not UnitIsPlayer("target") then return end

    local healUnit  = "target"
    local healName  = UnitName(healUnit)
    -- Порог = 60 + уровень цели откалиброван под максимум 25 (Origins,
    -- где потолок — 85 против броска 1-100+мод.). Без перевода в
    -- эталонную шкалу (см. SB.Data.ToReferenceLevel) на реалме с более
    -- высоким капом (Sanctuary, 100) порог для персонажа макс. уровня
    -- ушёл бы к 160 — лечение стало бы практически невозможным.
    local healLevel = SB.Data.ToReferenceLevel(UnitLevel(healUnit) or 1)

    -- Скейлинг от характеристик (см. GetSpellScaling). Канал damage у
    -- лечащего заклинания означает силу исцеления.
    local hitBonus, hitParts = SB.Logic.GetSpellScaling(spell, "hit")
    local dmgBonus           = SB.Logic.GetSpellScaling(spell, "damage", slotLevel)
    local critBonus          = SB.Logic.GetSpellScaling(spell, "crit")

    -- Та же развилка, что у урона (см. GetCastPower): у лечения
    -- кастерского класса вложенная мана поднимает объём исцеления, у
    -- некастерского (Целебные туманы Монаха) — шанс, что оно подействует.
    -- Прибавка к попаданию приходит как источник реестра "resource".
    -- База — своя (см. SB.Logic.GetHealPower): у лечения она есть на
    -- любом круге, а не только у заговоров.
    local baseHeal = SB.Logic.GetHealPower(spell, slotLevel)

    local mod, modParts = SB.Logic.GetModifierBreakdown("attack",
        { spell = spell, slotLevel = slotLevel })
    mod = mod + hitBonus
    for _, p in ipairs(hitParts) do table.insert(modParts, p) end
    local roll, _, rollMax = SB.Logic.Roll()
    local total     = roll + mod
    -- Крит — по ЧИСТОМУ кубику, ровно как в бою (см. GetCritThreshold):
    -- иначе у развитого лекаря критом становился бы каждый второй успех,
    -- а у начинающего — никогда. Канал "crit" (и скейлинг заклинания, и
    -- висящие баффы) работает здесь так же, как на ударах.
    local isCrit    = roll >= SB.Logic.GetCritThreshold(critBonus, rollMax)
    -- Округляем: healLevel может быть дробным на реалме с растянутой
    -- прогрессией (см. ToReferenceLevel выше) — без floor порог/лог
    -- показывали бы игроку что-то вроде "против порога 82.5".
    local threshold = SB.Logic.BaseThresholdFor(UnitLevel(healUnit) or 1)
    -- «Без сопротивления» действует и на лечение: порог не берётся вовсе
    -- (см. SB.Logic.IsGuaranteed). Крит при этом остаётся случайным — он
    -- от кубика, а кубик бросается в любом случае.
    local guaranteed = SB.Logic.IsGuaranteed(spell)
    local success    = guaranteed or (total >= threshold)

    -- Сила исцеления — та же шкала, что у урона кастера: 1 ХП на
    -- заговоре, +1 за каждую вложенную единицу маны, плюс скейлинг от
    -- характеристик (только при успехе).
    -- «Милосердие» в объём БОЛЬШЕ НЕ ВХОДИТ: навык переехал в бросок
    -- (источник реестра "mercy", см. SB.Skills.GetMercyHealBonus) и
    -- покупает теперь надёжность, а не размер исцеления.
    -- Канал "heal" висящих эффектов плюс профиль класса — сдвиг силы
    -- исцеления (см. SB.Logic.GetHealBonus). Отдельный от "damage": бафф
    -- может усилить лечение, не усиливая удары, и наоборот.
    local effHeal = SB.Logic.GetHealBonus()
    local healAmount = baseHeal + (success and (dmgBonus + effHeal) or 0)
    -- Критическое исцеление УМНОЖАЕТ итог — по тем же соображениям, что
    -- и крит урона: плоская прибавка у развитого лекаря значила бы
    -- проценты, а у заговора — половину лечения.
    local critAdd = 0
    isCrit = isCrit and success
    healAmount, critAdd = SB.Logic.ApplyCritHeal(healAmount, isCrit)

    -- ПОЧИНКА ДОСПЕХА — тем же броском и тем же ответом, что лечение
    -- (см. врезку у SB.Logic.GetSpellRepair). Под успех она попадает так
    -- же: провалившийся каст не чинит ничего.
    local repairArmor = success and SB.Logic.GetSpellRepair(spell, slotLevel) or 0

    -- Если лечим себя — применяем локально сразу (сетевое эхо от своих
    -- же сообщений игнорируется диспетчером, поэтому self-heal нужно
    -- обработать напрямую).
    if success and healName == UnitName("player") then
        PM.Heal(healAmount)
        if repairArmor > 0 and SB.Skills and SB.Skills.AdjustArmor then
            SB.Skills.AdjustArmor(repairArmor)
        end
        SB.Events.Fire("STATUS_CHANGED")
    end
    SB.Net.SendHealResult(healName, spellID, success, healAmount, repairArmor)

    -- ── ЭФФЕКТ, КОТОРЫЙ ВЕШАЕТ ЛЕЧЕНИЕ (spell.buff) ─────────
    --
    -- ЭТОГО ШАГА ЗДЕСЬ НЕ БЫЛО, и «Озарение» друида работало ровно
    -- наполовину: рана затягивалась, а сам эффект — прибавка к лечению,
    -- «Милосердие» и тик на два — не появлялся ни у кого и никогда.
    --
    -- Причина та же, что была у «Призвать рой»: доставку эффекта
    -- выполняет ApplyBuffToTarget, а звали её из ОДНОГО пути резолва
    -- (ProcessRollAndCast). Лечащий каст с живой целью идёт своей веткой
    -- и мимо неё; парадокс тот же — чтобы эффект лёг, надо было лечить
    -- ТАК, чтобы каст не разрешился сам и ушёл заявкой Ведущему.
    -- Заклинаний с этой болезнью шесть: «Жизнецвет», «Озарение» и
    -- «Спокойствие» друида, «Успокаивающий туман» монаха, «Аура защиты
    -- от тьмы» паладина и «Целительный ливень» шамана.
    --
    -- ТОЛЬКО НА УСПЕХЕ: провалившееся лечение не лечит и эффекта не
    -- оставляет — иначе промах давал бы половину заклинания даром.
    local healBuff
    if success and spell.buff then
        SB.Logic.ApplyBuffToTarget(spell, slotLevel)
        -- Что легло НА МЕНЯ — только самолечение: эффект на союзника
        -- уезжает ему и моего хода не касается (см. TurnSkipFor).
        if healName == UnitName("player") then healBuff = spell.buff end
    end

    -- Отклик лекарю. Лечение резолвится локально и CAST_RESOLVED не
    -- шлёт, поэтому звук здесь (см. SB.Logic.PlayOutcomeSound).
    SB.Logic.PlayOutcomeSound(success)

    -- Лечение — такой же потраченный ход, как удар.
    SB.Logic.SpendTurn(SB.Logic.TurnSkipFor(spell, spellID, healBuff))

    local link    = SB.UI.MakeSpellLink(spell)
    local modLink = SB.UI.ModText(mod)
    local healLo, healHi = SB.Logic.GetRollRange()
    local rollLink = SB.UI.RollText(roll)
    local G       = SB.Theme.MSG_BODY -- тёплое золото вместо белого по умолчанию — читается лучше
    -- Разбивка исцеления — в подсказку на числе, как у урона: в строку
    -- она не влезает, а понять, откуда взялись 5 ХП (вложенная мана,
    -- характеристики, висящие баффы), игроку нужно. «Милосердия» здесь
    -- нет — оно теперь в разбивке БРОСКА, рядом с остальными навыками.
    -- Здоровье цели тут неизвестно — считает и применяет его она сама,
    -- поэтому в ссылку уходят нули, и строку ХП подсказка не рисует.
    local healParts = {
        { key = "hbase", value = baseHeal },
        { key = "scal",  value = dmgBonus },
        { key = "heff",  value = effHeal },
        { key = "crit",  value = critAdd },
    }
    -- ИСТОЩЕНИЕ ЗАТЯЖНОГО БОЯ режет любое исцеление, и режет его у
    -- ПОЛУЧАТЕЛЯ (см. PM.Heal). В строку пишем то, что он реально
    -- получит: иначе лог обещает три ХП, а полоска прибавляет два.
    -- По сети при этом уходит ЧИСТОЕ значение — штраф получатель
    -- применит сам, и применить его дважды нельзя.
    local wear = (SB.TurnOrder and SB.TurnOrder.GetHealWear
        and SB.TurnOrder.GetHealWear()) or 0
    local shownHeal = math.max(0, healAmount - wear)
    local wearTxt = (wear > 0)
        and (G .. " (истощение боя −" .. wear .. ")|r") or ""

    -- Починка — отдельной припиской, и только если она есть: у чистого
    -- лечения этой скобки быть не должно, а у чистой починки не должно
    -- быть «восстанавливает 0 ХП».
    local repairTxt = (repairArmor > 0)
        and (G .. " Доспех: |r" .. SB.Theme.MSG_GOOD .. "+" .. repairArmor ..
             " брони|r" .. G .. ".|r") or ""

    local outcomeTxt
    if not success then
        outcomeTxt = SB.Theme.MSG_BAD .. "Исцеление не подействовало.|r"
    else
        local head = (isCrit and (SB.Theme.MSG_GOOD .. "Критическое исцеление!|r ")
                              or  (SB.Theme.MSG_GOOD .. "Исцеление удалось!|r "))
        if shownHeal > 0 or not (repairArmor > 0) then
            outcomeTxt = head .. G .. healName .. " восстанавливает |r" ..
                SB.UI.AmountText("heal", shownHeal) .. G .. " ХП.|r" ..
                wearTxt .. repairTxt
        else
            -- Чистая починка: про ХП молчим вовсе.
            outcomeTxt = SB.Theme.MSG_GOOD .. "Доспех починен!|r" .. repairTxt
        end
    end
    -- У гарантированного лечения броска нет — и в строке его нет, ровно
    -- как у гарантированного эффекта (см. ResolveEffectCast): «Итог 43
    -- против порога 71. Исцеление удалось» выглядело бы поломкой.
    -- Гарантированное лечение — без «(без сопротивления)» и без
    -- «Исцеление удалось!»: броска не было, и удаться иначе оно не могло.
    local rollTxt = guaranteed
        and (G .. ": |r")
        or  (G .. ": |r" .. SB.UI.RollLine(roll, mod, total, G) ..
             G .. " против " .. threshold .. ". |r")
    if guaranteed and success and (shownHeal > 0 or not (repairArmor > 0)) then
        outcomeTxt = G .. healName .. " восстанавливает |r" ..
            SB.UI.AmountText("heal", shownHeal) .. G .. " ХП.|r" .. wearTxt .. repairTxt
    end
    -- «лечит X заклинанием [Y]» → «— [Y] на X»: существительное
    -- пересказывало ссылку, стоящую следом (тот же разбор, что у удара).
    local sysMsg = SB.Theme.MSG_TAG .. "[Spellbreaker]:|r " ..
        G .. UnitName("player") .. " — |r" .. link ..
        G .. " на " .. healName .. rollTxt .. outcomeTxt
    SB.Events.Fire("BROADCAST_LOG", sysMsg, SB.LogRank.ACTION)

    local emoteText = success and SB.SpellOutcomes.Get(spellID) or nil
    if emoteText and emoteText ~= "" then
        local rpMsg = ApplyTemplates(emoteText)
        if not SpellbreakerAccountDB or SpellbreakerAccountDB.sendEmotes ~= false then
            SendChatMessage(rpMsg, "EMOTE")
        end
    end

    if spell.onResolve then
        local ok, err = pcall(spell.onResolve, {
            spellID = spellID, spell = spell, roll = roll, mod = mod, total = total,
            threshold = threshold, succeeded = success, healAmount = healAmount,
            isCrit = isCrit, hitBonus = hitBonus, dmgBonus = dmgBonus,
            caster = UnitName("player"), target = healName,
        })
        if not ok then
            print(SB.Theme.MSG_TAG .. "[Spellbreaker]|r: " .. SB.Theme.MSG_BAD ..
                "Ошибка в onResolve заклинания " .. (spell.name or spellID) .. ": " .. tostring(err) .. "|r")
        end
    end
end

-- ============================================================
-- РАССЕИВАНИЕ (spell.dispel)
--
-- Заклинание объявляет ШКОЛЫ, которые оно снимает, — одной строкой или
-- списком:
--   dispel = "magic"                  -- Рассеивание магии
--   dispel = { "poison", "disease" }  -- Очищение паладина
-- Школы дебаффов и умолчание для неразмеченных — см. врезку в
-- Core/Database.lua.
--
-- БРОСКА ЗДЕСЬ НЕТ, И ЭТО НАМЕРЕННО. Сколько снимает рассеивание,
-- решает его круг (см. GetDispelCount), а бросок поверх означал бы
-- «потратил ход и не снял ничего» — худший из исходов у заклинания,
-- которое и так тратит ход целиком.
--
-- СНИМАЕТ ТОТ, НА КОМ ВИСИТ. Эффекты живут на клиенте носителя, и
-- никакой другой клиент их не видит: заклинатель шлёт пакет «сними у
-- себя вот эти школы, не больше стольких», а строку в лог пишет
-- носитель — он один знает, что именно ушло.
--
-- ДРУГ РЕШАЕТ, ЧТО ИМЕННО СНИМАЕТСЯ — баффы или дебаффы, а не смесь
-- того и другого. Список «Друг» тот же, что у площадных заклинаний
-- (см. врезку «Свои и чужие» в Core/Database.lua): заклинатель считает
-- цель своей — значит хочет ей помочь, и рассеивание снимает с неё
-- вред (дебаффы). Не отметил — значит цель чужая, и рассеивание бьёт
-- по её пользе (баффы), как и подобает вражескому чарами.
--   • ДРУГ (или сам себе — см. SB.Data.IsFriend) → снимаются ДЕБАФФЫ;
--   • НЕ ДРУГ                                    → снимаются БАФФЫ.
-- Решение — за ЗАКЛИНАТЕЛЕМ, и едет вместе с пакетом рассеивания
-- (см. SB.Net.SendDispel), потому что снимает эффекты получатель у
-- себя, а список друзей есть только у того, кто кастует.
-- ============================================================

--- Школы, которые снимает заклинание, множеством. nil — не рассеивающее.
function SB.Logic.GetDispelSchools(spell)
    local d = spell and spell.dispel
    if type(d) == "string" then d = { d } end
    if type(d) ~= "table" then return nil end

    local set, any = {}, false
    for _, s in ipairs(d) do
        -- Незнакомую школу молча пропускаем: опечатка в данных не должна
        -- превращать заклинание в «снимает всё». Неснимаемую (кровотечение)
        -- — тоже: правило живёт в описании школы, а не в дисциплине того,
        -- кто пишет заклинания.
        local info = SB.Data.EffectSchools[s]
        if info and not info.undispellable then set[s] = true; any = true end
    end
    return any and set or nil
end

--- Сколько эффектов снимает этот каст.
---
--- СКОЛЬКО СНИМАЕТ — СТОЛЬКО, КАКОЙ КРУГ У ЗАКЛИНАНИЯ. «Рассеивание
--- магии» жреца первого круга снимает один эффект, «Антимагия» мага
--- третьего — три. Прежде число росло от вливания сверх круга, и сила
--- рассеивания зависела от того, сколько маны не жалко, а не от того,
--- чем рассеивают. Вливать теперь некуда — и выбор круга у рассеиваний
--- пропадает сам (SB.Logic.CanUpcast сравнивает, что даёт каждый круг).
--- Заговор и склянка нулевого круга снимают один: меньше не бывает.
--- slotLevel не читается и остался в подписи ради вызывающих.
function SB.Logic.GetDispelCount(spell, slotLevel)
    local base = tonumber(SB.Data.Config.DispelBase) or 1
    return math.max(base, tonumber(spell and spell.level) or 0)
end

--- Строка в лог по итогу рассеивания. Пишет её носитель эффектов —
--- он один знает, что с него сняли (см. врезку выше).
--- @param friend boolean  что снимали: true — дебаффы (цель — друг),
---        false — баффы (цель чужая). Только для подписи глагола.
function SB.Logic.AnnounceDispel(casterName, spellID, names, friend)
    local spell = SB.Data.Spells[spellID]
    local G     = SB.Theme.MSG_BODY
    local who   = UnitName("player")
    local link  = spell and SB.UI.MakeSpellLink(spell) or (G .. "заклинанием|r")
    -- Глагол называет то, что реально произошло: дружеский каст лечит,
    -- вражеский — срывает чужие чары. Один и тот же «очищает» на оба
    -- случая вводил бы в заблуждение того, кто снял баффы с врага.
    local verb  = (friend == false) and "срывает чары с" or "очищает"

    local tail
    if #names == 0 then
        tail = SB.Theme.MSG_BODY .. "снимать нечего.|r"
    else
        tail = SB.Theme.MSG_GOOD .. "снято " .. #names .. ": |r" ..
               G .. table.concat(names, ", ") .. ".|r"
    end

    -- Строка — ОТВЕТ заклинателю: он держит ход, пока её не увидит (см.
    -- ResolveDispel). Одним пакетом в группу, тем же приёмом, что итог
    -- удара: все печатают, заклинатель по ней отпускает ход.
    local replyTo = (casterName and casterName ~= who) and casterName or nil
    SB.Events.Fire(SB.E.BROADCAST_LOG,
        SB.Theme.MSG_TAG .. "[Spellbreaker]:|r " .. G ..
        (casterName or "Кто-то") .. " " .. verb .. " " .. who .. " через |r" .. link ..
        G .. ": |r" .. tail, SB.LogRank.RESULT, replyTo and { replyTo = replyTo } or nil)
end

--- Снять с СЕБЯ по чужому (или своему) рассеиванию.
--- @param friend boolean|nil  см. SB.ActiveEffects.Dispel
function SB.Logic.HandleDispelReceived(casterName, spellID, schools, count, effectID, slotLevel, friend)
    if type(schools) ~= "table" then return end
    local names = SB.ActiveEffects.Dispel(schools, count, friend)
    -- Бонусный бафф заклинания («Очищенная кровь» у Снятия болезни)
    -- ложится независимо от того, было ли что снимать: это часть каста,
    -- а не награда за попадание.
    if effectID then
        SB.Logic.ApplyEffect(effectID, SB.Data.Spells[spellID], slotLevel)
    end
    SB.Logic.AnnounceDispel(casterName, spellID, names, friend)
    SB.Events.Fire(SB.E.STATUS_CHANGED)
end

--- Может ли аддон разрешить рассеивание сам, не спрашивая Ведущего.
---
--- То же правило, что у одиночного баффа (см. GetTargetedEffect): каст с
--- дальностью адресован КОМУ-ТО, и без этого кого-то аддону решать
--- нечего. Раньше «нет цели» молча значило «чищу себя» — и «Рассеивание
--- магии» с дальностью 30 м, нацеленное на предмет или на НПС, снимало
--- эффекты с самого заклинателя.
---
--- Дальность 0 — заклинание про себя по определению, ему цель не нужна.
---
--- СКЛЯНКА — ИСКЛЮЧЕНИЕ, И ТО ЖЕ САМОЕ, ЧТО У ЭФФЕКТА И ВЫПЛАТЫ.
--- Дальность у зелья не «докуда добьёт», а «надо стоять рядом», и
--- доводом против того, чтобы выпить самому, служить не может (см.
--- врезку у ItemStaysOnCaster). Пока исключения не было, «Зелье
--- сопротивления яду» не снимало ничего: выпитое на себя оно уходило
--- мимо этой ветки — сначала по aimed, потом по дальности, — и
--- проваливалось в обычный бросок, где рассеивания нет вовсе.
--- @param aimed boolean|nil  каст НЕ помечен «на себя». nil — не
---        спрашивали (старые вызовы), и тогда не ограничивает.
function SB.Logic.CanDispelLocally(spell, aimed)
    if not SB.Logic.GetDispelSchools(spell) then return false end
    if SB.Items and SB.Items.IsItem and SB.Items.IsItem(spell) then return true end
    if aimed == false then return false end
    if (tonumber(spell.distance) or 0) <= 0 then return true end
    return UnitExists("target") and UnitIsPlayer("target")
end

function SB.Logic.ResolveDispel(spellID, slotLevel)
    local spell   = SB.Data.Spells[spellID]
    local schools = SB.Logic.GetDispelSchools(spell)
    if not schools then return end

    local count = SB.Logic.GetDispelCount(spell, slotLevel)
    local me    = UnitName("player")
    -- Цель — дружественная и может быть собой. Нет цели вовсе — чистим
    -- себя: это единственное осмысленное умолчание у заклинания,
    -- которое ничего не делает без носителя.
    --
    -- «НА СЕБЯ» У СКЛЯНКИ СИЛЬНЕЕ ВЫБРАННОЙ ЦЕЛИ. onSelf — это не
    -- подсказка, а отмена цели (см. SB.UI.ShowItemUseMenu): кто бы ни
    -- стоял сейчас в таргете, к этому глотку он отношения не имеет.
    -- Правило то же, что у эффекта и выплаты склянки, и записано оно
    -- один раз — в ItemStaysOnCaster.
    local targetName = me
    local hasOther = UnitExists("target") and UnitIsPlayer("target")
                     and not UnitIsUnit("target", "player")
    if hasOther and not ItemStaysOnCaster(spell, true) then
        targetName = UnitName("target")
    end

    -- ДРУГ РЕШАЕТ, ЧТО СНИМЕТ КАСТ — см. врезку выше и в
    -- Core/ActiveEffects.lua. Сам себе всегда друг (SB.Data.IsFriend),
    -- поэтому самокаст неизменно чистит СЕБЯ от вреда.
    local friend = SB.Data.IsFriend(targetName)

    if targetName == me then
        SB.Logic.HandleDispelReceived(me, spellID, schools, count,
                                      spell.buff, slotLevel, friend)
    else
        SB.Net.SendDispel(targetName, spellID, schools, count,
                          spell.buff, slotLevel, friend)
        local G = SB.Theme.MSG_BODY
        print(SB.Theme.MSG_TAG .. "[Spellbreaker]|r: " .. G ..
            "рассеивание ушло к " .. targetName ..
            " (до " .. count .. " эффектов, " ..
            (friend and "дебаффы" or "баффы") .. ").|r")
        -- Что снято, пишет ЦЕЛЬ, и её строка — ответ нам (см.
        -- AnnounceDispel): ход ждёт её, как удар ждёт итога.
        SB.Logic.HoldTurnUntilResult(SB.Logic.TurnSkipFor(spell, spellID))
        return
    end

    SB.Logic.SpendTurn(SB.Logic.TurnSkipFor(spell, spellID))
end

-- ============================================================
-- НАЛОЖЕНИЕ ЭФФЕКТА НА ИГРОКА — БРОСОК ПО ОБРАЗЦУ ЛЕЧЕНИЯ
--
-- Когда бафф или дебафф направлен на КОРРЕКТНУЮ цель-игрока, эффект
-- не даётся даром: идёт бросок против того же порога, что у лечения —
-- 60 + уровень цели (по эталонной шкале, см. SB.Data.ToReferenceLevel).
-- Не прошёл — эффект не лёг.
--
-- Что считается корректной целью:
--   • бафф   — дружественный игрок ИЛИ ты сам;
--   • дебафф — другой игрок (на себя дебафф не наводят).
-- Нет цели или в цели НПС — заклинание идёт обычным путём (ПвЕ:
-- заявка Ведущему или локальный бросок), там эффект разбирает Ведущий.
--
-- Порог берётся у ЦЕЛИ, а не у заклинателя: навесить что-то на
-- новичка проще, чем на матёрого — ровно как с лечением.
--
-- Каст НА СЕБЯ считается иначе: порог ровно 60, без уровня вообще.
-- Собственные ауры, стойки и обликы не «сопротивляются» хозяину, а с
-- прибавкой по уровню выходило, что чем персонаж опытнее, тем хуже он
-- владеет своими же заклинаниями. Подробности — в SB.Logic.EffectThreshold.
-- ============================================================

--- Есть ли у заклинания эффект, который можно навесить броском, и
--- годится ли текущая цель. Вызывается из ConfirmCast при выборе пути.
--- @return string|nil effectID, boolean onSelf
function SB.Logic.GetTargetedEffect(spell)
    if not spell then return nil end
    -- Площадные эффекты идут своим путём — там целей много и броска нет.
    if spell.aoe and IsInGroup() then return nil end

    -- Заклинания «без сопротивления» ОТСЮДА НЕ ВЫВОДЯТСЯ, хотя броска им
    -- не положено: этот путь умеет не только бросать, но и доставлять —
    -- эффект на себя, баф союзнику, дебафф цели по сети. Уведи их в
    -- локальный резолв — и одиночный дебафф просто перестал бы доезжать.
    -- Бросок для них отключается внутри ResolveEffectCast.

    -- Уронные и лечащие сюда не попадают: у них свои ветки резолва, и
    -- свой container/buff они вешают уже по факту исхода. Перехватить их
    -- здесь значило бы отобрать у заклинания урон или лечение.
    if spell.canCrit or SB.Logic.IsHealingCast(spell) then return nil end

    local hasTarget = UnitExists("target") and UnitIsPlayer("target")
    local isSelf    = hasTarget and UnitIsUnit("target", "player")

    -- container — эффект, который физически нельзя навести ни на кого,
    -- кроме себя: стойки, собственные ауры, обликы. Цель ему не нужна
    -- вовсе, поэтому и бросок всегда местный.
    --
    -- Раньше container здесь не проверялся вообще, и такое заклинание
    -- уходило либо в ПвЕ-ветку с СЛ от Ведущего, либо прямо в заявку
    -- Ведущему — то есть баф на самого себя ждал чужого решения.
    if spell.container then
        return spell.container, true
    end

    if spell.buff then
        -- ПРЕДМЕТ — ПЕРВЫМ ДЕЛОМ И ДО СОЮЗНИКА: выбранный пункт «на себя»
        -- должен перебивать того, кто оказался в таргете, иначе меню
        -- врало бы (см. ItemStaysOnCaster).
        if ItemStaysOnCaster(spell, hasTarget) then
            return spell.buff, true
        end
        -- На союзника — если он в цели.
        if hasTarget and not isSelf and UnitCanAssist("player", "target") then
            return spell.buff, false
        end
        -- НА СЕБЯ — ТОЛЬКО ЕСЛИ ЗАКЛИНАНИЕ ВООБЩЕ ПРО СЕБЯ.
        --
        -- Раньше здесь стояло безусловное «на себя», и любой промах мимо
        -- цели молча превращался в самобафф: снял таргет, нажал «Могущество»
        -- с дальностью 2.5 м — и оно легло на заклинателя, будто так и
        -- задумано. Таких заклинаний в библиотеке 64, и ни одно из них
        -- не про себя.
        --
        -- Признак «про себя» тот же, которым пользуется вся остальная
        -- маршрутизация: дальность 0 или её нет вовсе — это «На себя»
        -- (см. метку цели в ConfirmCast). Такому баффу цель и не нужна.
        -- Всё прочее — цели нет, в цели НПС, в цели враг — аддон разрешить
        -- не может и не должен: заклинание уходит заявкой Ведущему.
        --
        -- ПЛОЩАДЬ ПОД ЭТО ПРАВИЛО НЕ ПОПАДАЕТ. В группе она сюда и не
        -- доходит (отсечена в начале функции), а в одиночку у неё цели
        -- нет по устройству: аура гремит вокруг заклинателя, и «нет
        -- таргета» для неё — норма, а не промах мимо союзника.
        if isSelf or spell.aoe or (tonumber(spell.distance) or 0) <= 0 then
            return spell.buff, true
        end
        return nil
    end

    -- Дебафф — только на ДРУГОГО игрока: на себя его не наводят.
    if spell.debuff and hasTarget and not isSelf then
        return spell.debuff, false
    end
    return nil
end

--- Бросок на наложение эффекта. Устроен как SB.Logic.ResolveHeal:
--- те же модификаторы атаки, тот же порог, то же единое сообщение.
function SB.Logic.ResolveEffectCast(spellID, slotLevel)
    local spell = SB.Data.Spells[spellID]
    if not spell then return end
    -- Цена каста («Кровавая ярость: +2 Ярость, 2 урона») — в строку
    -- каста (см. TakeCastPayload). Забираем сразу: строка может ждать
    -- ответа цели, а выплата напечаталась бы без неё в конце кадра.
    local pay = SB.Logic.TakeCastPayload(spellID)

    local effectID, onSelf = SB.Logic.GetTargetedEffect(spell)
    if not effectID then return end

    -- Порог берётся у того, НА КОГО ложится эффект: на новичка навесить
    -- проще, чем на матёрого. Каст на СЕБЯ из этого правила выведен —
    -- там порог ровно 60, без уровня (см. SB.Logic.EffectThreshold).
    local targetName = onSelf and UnitName("player") or UnitName("target")
    local levelUnit  = onSelf and "player" or "target"

    local hitBonus, hitParts = SB.Logic.GetSpellScaling(spell, "hit")
    local mod, modParts = SB.Logic.GetModifierBreakdown("attack",
        { spell = spell, slotLevel = slotLevel })
    mod = mod + hitBonus
    for _, p in ipairs(hitParts) do table.insert(modParts, p) end

    local roll      = SB.Logic.Roll()
    local total     = roll + mod

    -- ПОРОГ ЧУЖОГО НАМ НЕ ПРИНАДЛЕЖИТ. Здесь считается ПРЕДВАРИТЕЛЬНЫЙ:
    -- 60 плюс уровень цели — всё, что игровое API про неё отдаёт.
    -- Стойкость цели (effect.resist) в него не входит и войти не может:
    -- характеристик чужого персонажа клиент не видит.
    --
    -- Настоящий порог посчитает сама цель и пришлёт назад вместе с
    -- исходом (см. SB.Logic.HandleBuffReceived). Ровно так с самого
    -- начала устроен площадной путь — там целей много и ни одна не в
    -- прицеле, так что иначе и не выходило. Одиночный каст выбивался из
    -- общего правила только потому, что уровень цели прочитать МОЖНО, и
    -- казалось, будто заклинатель справится сам. Как только к порогу
    -- добавилась стойкость, не справился: я стал возить модификаторы
    -- атрибутов отдельным полем сетевого статуса. Поля больше нет.
    --
    -- Предварительный порог всё же нужен: если цель не ответит (нет
    -- аддона, потерялся пакет), напечатать исход придётся по нему.
    local threshold = SB.Logic.EffectThreshold(levelUnit, false, onSelf)

    -- «БЕЗ СОПРОТИВЛЕНИЯ» — ЗНАЧИТ БЕЗ БРОСКА. Порог здесь не берётся
    -- вовсе: эффект ложится всегда. Раньше resistable = false не
    -- выполнялось ровно там, где его чаще всего и объявляют — на
    -- собственных стойках, обликах и аурах: они всё равно требовали
    -- взять 60. Доставка при этом остаётся общей (на себя, союзнику,
    -- цели по сети) — из-за неё эти заклинания и не выведены отсюда
    -- в локальный резолв.
    local guaranteed = SB.Logic.IsGuaranteed(spell)
    local success    = guaranteed or (total >= threshold)

    -- РЕШАЕТ НЕ НАША СТОРОНА, если цель — чужой игрок и бросок был.
    -- Гарантированному ждать нечего: ни броска, ни порога, исход
    -- известен заранее.
    local waitsForTarget = (not onSelf) and (not guaranteed)
        and IsInGroup() and SB.Net and SB.Net.SendBuff and true or false

    if waitsForTarget then
        -- ШЛЁМ И ПРИ СВОЁМ «ПРОВАЛЕ» ТОЖЕ, а не только при успехе.
        -- Предварительный порог не обязан быть НИЖЕ настоящего: слабая
        -- характеристика даёт отрицательный модификатор, и стойкость
        -- цели порог не поднимет, а опустит. Отсеки мы такой каст у
        -- себя — цель никогда не узнала бы, что могла его пропустить.
        SB.Net.SendBuff(targetName, spellID, effectID, slotLevel, nil,
                        roll, mod, total)
    elseif success then
        if onSelf then
            SB.Logic.ApplyEffect(effectID, spell, slotLevel)
        else
            -- ГАРАНТИРОВАННОМУ БРОСОК НЕ ШЛЁМ: его не с чем сверять,
            -- и цель применит эффект безусловно — как применяла всегда.
            SB.Net.SendBuff(targetName, spellID, effectID, slotLevel)
        end
    end

    -- Ход потрачен. Пропускаем ТОЛЬКО ТОТ эффект, который лёг НА НАС и
    -- лёг именно сейчас: иначе он сгорел бы на единицу в тот же миг.
    --
    -- РАНЬШЕ ЗДЕСЬ СТОЯЛ ПРОСТО effectID, И ЭТО БЫЛО ОШИБКОЙ. Пропуск
    -- работает по id эффекта, а не по «той копии, что я сейчас наложил»,
    -- и наложение НА ЧУЖОГО защищало СВОЮ копию того же эффекта:
    -- наслал «Боль» на противника, будучи сам под «Болью», — своя
    -- «Боль» этот ход не тикала. Площадной путь так не ошибался: он
    -- передаёт landedOnSelf, то есть тоже «легло на меня».
    local landedOnSelf = (success and onSelf) and effectID or nil
    -- Исход каста на другого приходит ответом цели, и строка ждёт его —
    -- значит ждёт и ход: иначе «Ходит: …» печаталось бы раньше самого
    -- каста (см. SB.Logic.HoldTurnUntilResult). Отпускает Announce.
    if waitsForTarget then
        SB.Logic.HoldTurnUntilResult(SB.Logic.TurnSkipFor(spell, spellID, landedOnSelf))
    else
        SB.Logic.SpendTurn(SB.Logic.TurnSkipFor(spell, spellID, landedOnSelf))
    end

    -- ИСХОД ПЕЧАТАЕТСЯ ОДНОЙ СТРОКОЙ, и потому собран в функцию: при
    -- касте на чужого настоящий порог и настоящий исход приезжают
    -- ответом цели, и строка ждёт их, а не делится надвое.
    local function Announce(finalThreshold, finalSuccess)
        local G    = SB.Theme.MSG_BODY
        local link = SB.UI.MakeSpellLink(spell)
        -- Исход коротким словом, без названия эффекта: заклинание в этой
        -- же строке названо ссылкой, а что оно вешает — написано в его
        -- карточке. Та же формулировка, что у остальных путей резолва.
        local outcomeTxt = finalSuccess
            and (SB.Theme.MSG_GOOD .. "Успех.|r")
            or  (SB.Theme.MSG_BAD  .. "Провал.|r")

        -- ГАРАНТИРОВАННОЕ — ОДНОЙ ФРАЗОЙ: «применяет [Боевой крик] на
        -- себя.» Бафф — автоуспех, это сказано в карточке заклинания, и
        -- «(без сопротивления). Успех.» на каждой стойке и каждом зелье
        -- пересказывало очевидное. Броска не было — и в строке его нет.
        local rollTxt = guaranteed
            and (G .. ".|r")
            or  (G .. ": |r" .. SB.UI.RollLine(roll, mod, total, G) ..
                 G .. " против " .. finalThreshold .. ". |r")
        if guaranteed and finalSuccess then outcomeTxt = "" end
        if guaranteed and not finalSuccess then rollTxt = G .. ". |r" end
        if pay then
            if guaranteed and finalSuccess then
                rollTxt = G .. ": " .. pay .. ".|r"
            else
                outcomeTxt = outcomeTxt .. G .. " (" .. pay .. ")|r"
            end
        end

        SB.Events.Fire(SB.E.BROADCAST_LOG,
            SB.Theme.MSG_TAG .. "[Spellbreaker]:|r " .. G .. UnitName("player") ..
            " применяет |r" .. link .. G .. " на " .. (onSelf and "себя" or targetName) ..
            rollTxt .. outcomeTxt, SB.LogRank.ACTION)

        -- РП-отпись — по тем же правилам, что у остальных заклинаний:
        -- только на успех и только если игрок её задал.
        local outcomeText = finalSuccess and SB.SpellOutcomes.Get(spellID) or nil
        if outcomeText and outcomeText ~= "" then
            local rpMsg = ApplyTemplates(outcomeText)
            if not SpellbreakerAccountDB or SpellbreakerAccountDB.sendEmotes ~= false then
                SendChatMessage(rpMsg, "EMOTE")
            end
        end

        SB.Events.Fire(SB.E.CAST_RESOLVED, spellID, finalSuccess,
            finalSuccess and "|cFF00FF00Успех.|r" or "|cFFFF0000Провал.|r",
            guaranteed and "Без сопротивления — бросок не требуется"
                or string.format("%d + %d = %d против порога %d",
                                 roll, mod, total, finalThreshold))
        -- Строка ушла — теперь и ход (см. HoldTurnUntilResult выше).
        if waitsForTarget then SB.Logic.ReleaseHeldTurn() end
    end

    if waitsForTarget then
        SB.Logic.BuffAwait(targetName, spellID, threshold, success, Announce)
    else
        Announce(threshold, success)
    end
end

-- ============================================================
-- ОЖИДАНИЕ ОТВЕТА ЦЕЛИ
--
-- Заклинатель больше не знает, лёг ли эффект: порог собран из уровня
-- цели и её же стойкости, а характеристик чужого персонажа клиент не
-- видит. Ответ приходит тем же тиком, поэтому печать ждёт его и
-- остаётся ОДНОЙ СТРОКОЙ — ради этого здесь ожидание, а не две
-- отдельные реплики «бросил» и «ответили».
--
-- НЕ ОТВЕТИЛИ — ПЕЧАТАЕМ ПО СВОЕМУ ПОРОГУ, тому самому, по которому
-- этот путь считал раньше. У цели может не быть аддона, и тогда на неё
-- всё равно ничего не ляжет, — но молчание в чате хуже неточной
-- строки: игрок решил бы, что ход пропал впустую.
-- ============================================================
local buffAwaits = {}

SB.Logic.BUFF_AWAIT_SEC = 2

--- @param fallbackThreshold number  по чему печатать, если ответа не будет
function SB.Logic.BuffAwait(targetName, spellID, fallbackThreshold,
                            fallbackSuccess, announce)
    local key = (targetName or "?") .. "::" .. tostring(spellID)
    -- Прежнее ожидание тем же ключом закрываем сразу: два каста одного
    -- заклинания в одну цель подряд иначе съели бы первую строку.
    local prev = buffAwaits[key]
    if prev then
        buffAwaits[key] = nil
        prev.announce(prev.threshold, prev.success)
    end

    local rec = { announce = announce, threshold = fallbackThreshold,
                  success = fallbackSuccess }
    buffAwaits[key] = rec
    C_Timer.After(SB.Logic.BUFF_AWAIT_SEC, function()
        if buffAwaits[key] ~= rec then return end
        buffAwaits[key] = nil
        rec.announce(rec.threshold, rec.success)
    end)
end

--- Цель ответила: вот её настоящий порог и настоящий исход.
---
--- ХВОСТ АРГУМЕНТОВ ПРОБРАСЫВАЕТСЯ КАК ЕСТЬ. Ожидание не знает и знать
--- не должно, чем именно закончился каст: эффекту хватает порога с
--- исходом, а краже нужна ещё и добыча (см. SB.Logic.HandleStealResult).
--- Заводить второе такое же ожидание ради одного лишнего поля значило бы
--- получить две расходящиеся копии одного механизма.
function SB.Logic.HandleBuffResultReceived(targetName, spellID, threshold, ok, ...)
    local key = (targetName or "?") .. "::" .. tostring(spellID)
    local rec = buffAwaits[key]
    if not rec then return end
    buffAwaits[key] = nil
    rec.announce(threshold, ok, ...)
end

-- ============================================================
-- КРАЖА — СОСТЯЗАНИЕ, У КОТОРОГО НЕТ ЭФФЕКТА
--
-- «Карманная кража» разбойника не решалась аддоном вовсе: ни дебаффа,
-- ни контейнера, а resistable = true, — значит каст падал в самый низ
-- цепочки, прямо в заявку Ведущему. Тот отыгрывал бросок руками.
--
-- ЧЕГО НЕ ХВАТАЛО — НЕ ЗАКЛИНАНИЮ, А ВИДУ КАСТА. В аддоне был
-- состязательный путь ровно один: наложить эффект. Всё, что решается
-- броском против чужой стойкости, но эффектом не заканчивается,
-- деваться было некуда. Поэтому здесь заведён не «путь карманной
-- кражи», а путь ЗАКЛИНАНИЯ С ДОБЫЧЕЙ: поле steal объявительное, и
-- любое будущее воровство поедет тем же кодом.
--
-- РЕШАЕТ ТОТ, У КОГО БЕРУТ, — то же правило, что у порога дебаффа и у
-- всего остального спорного в этом файле. И причина та же, только здесь
-- она вдвое весомее: заклинатель не знает ни стойкости цели, ни того,
-- что у неё в сумке. Обе половины ответа есть только на её клиенте.
--
-- У СУЩЕСТВА СУМКИ НЕТ ВОВСЕ, и заводить её ради одного заклинания
-- незачем: бросок считается честно, а что выпало из кармана купца —
-- решает Ведущий, как и всё прочее про мир.
--
-- СТРОКИ ЛОКАЛЬНЫЕ, А НЕ В ОБЩИЙ ЛОГ. Удачная кража, объявленная всему
-- рейду, — это не кража. Знают двое: вор и обворованный.
-- ============================================================

--- Что крадёт это заклинание. nil — не крадёт ничего.
--- @return string|nil  пока единственный вид: "item"
function SB.Logic.GetStealKind(spell)
    if type(spell) ~= "table" then return nil end
    local kind = spell.steal
    -- Короткая запись steal = true читается как «предмет»: это
    -- единственное, что у персонажа вообще можно отнять физически.
    if kind == true then kind = "item" end
    if kind ~= "item" then return nil end
    return kind
end

--- Может ли аддон разрешить кражу сам, не спрашивая Ведущего.
---
--- ЦЕЛЬ ОБЯЗАТЕЛЬНА, и умолчания «нет цели — сам у себя» здесь быть не
--- может: у кражи без жертвы нет смысла, в отличие от рассеивания, где
--- самокаст — осмысленное действие.
--- @param aimed boolean|nil  каст НЕ помечен «на себя»
function SB.Logic.CanSteal(spell, aimed)
    if not SB.Logic.GetStealKind(spell) then return false end
    if aimed == false then return false end
    if not UnitExists("target") then return false end
    if UnitIsUnit("target", "player") then return false end
    -- Игрок или существо — годятся оба: у первого сумка настоящая, у
    -- второго её нет и добычу назначает Ведущий.
    return UnitIsPlayer("target")
        or (SB.Logic.TargetNpcStats and SB.Logic.TargetNpcStats() ~= nil)
end

--- Вор: бросок и отправка. Решение принимает цель.
function SB.Logic.ResolveSteal(spellID, slotLevel)
    local spell = SB.Data.Spells[spellID]
    if not spell or not SB.Logic.GetStealKind(spell) then return end
    if not UnitExists("target") then return end

    local G    = SB.Theme.MSG_BODY
    local link = SB.UI.MakeSpellLink(spell)

    local hitBonus, hitParts = SB.Logic.GetSpellScaling(spell, "hit")
    local mod, modParts = SB.Logic.GetModifierBreakdown("attack",
        { spell = spell, slotLevel = slotLevel })
    mod = mod + hitBonus
    for _, p in ipairs(hitParts) do table.insert(modParts, p) end

    local roll  = SB.Logic.Roll()
    local total = roll + mod
    local guaranteed  = SB.Logic.IsGuaranteed(spell)
    local targetName  = UnitName("target") or "?"
    local npcStats    = (not UnitIsPlayer("target"))
        and SB.Logic.TargetNpcStats and SB.Logic.TargetNpcStats() or nil

    -- ── СУЩЕСТВО: СЧИТАЕМ САМИ, ДОБЫЧУ ДАЁТ ВЕДУЩИЙ ─────────
    if npcStats then
        -- Тот же порог, что у эффекта на существо (см. ResolveNpcEffect):
        -- база плюс уровень, плюс его «Воля» — кража чужому вмешательству
        -- родня, и сопротивляются ей тем же.
        local threshold = SB.Logic.BaseThresholdFor(npcStats.level)
            + SB.NPC.WillBonus(npcStats, "target")
        local ok = guaranteed or (total >= threshold)

        SB.Logic.SpendTurn(SB.Logic.TurnSkipFor(spell, spellID))
        print(SB.Theme.MSG_TAG .. "[Spellbreaker]|r: " .. G ..
            "вы обчищаете карманы |r" .. targetName .. G .. " через |r" .. link ..
            G .. ": |r" .. SB.UI.RollLine(roll, mod, total, G) ..
            G .. " против " .. threshold .. ". |r" ..
            (ok and (SB.Theme.MSG_GOOD .. "Успех — добычу назначает Ведущий.|r")
                 or (SB.Theme.MSG_BAD  .. "Не вышло.|r")))
        return
    end

    -- ── ИГРОК: РЕШЕНИЕ И ДОБЫЧА — НА ЕГО КЛИЕНТЕ ────────────
    --
    -- Предварительный порог нужен ровно затем же, зачем в ResolveEffectCast:
    -- цель может не ответить (нет аддона, потерялся пакет), и напечатать
    -- исход придётся хоть по чему-то.
    local threshold = SB.Logic.EffectThreshold("target", false, false)
    local success   = guaranteed or (total >= threshold)

    SB.Logic.SpendTurn(SB.Logic.TurnSkipFor(spell, spellID))

    --- @param itemID string|nil  что удалось вынуть (nil — карман пуст)
    local function Announce(finalThreshold, finalOk, itemID, count)
        local tail
        if not finalOk then
            tail = SB.Theme.MSG_BAD .. "Не вышло.|r"
        elseif not itemID then
            tail = SB.Theme.MSG_GOOD .. "Успех, |r" .. G .. "но карман пуст.|r"
        else
            local sp   = SB.Data.Spells[itemID]
            local name = (sp and sp.name) or itemID
            -- КЛАДЁМ ЗДЕСЬ, а не при получении пакета: положить надо
            -- ровно один раз, и это то же место, где о добыче печатают.
            local got  = (SB.Items and SB.Items.Grant)
                and SB.Items.Grant(itemID, count) or 0
            if got > 0 then
                tail = SB.Theme.MSG_GOOD .. "Успех: |r" .. G ..
                       name .. " (" .. got .. " шт.).|r"
            else
                -- СУМКА ПОЛНА — ДОБЫЧА ПОТЕРЯНА, и вернуть её нельзя:
                -- у жертвы она уже вынута. Честнее сказать об этом, чем
                -- тихо не положить ничего.
                tail = SB.Theme.MSG_GOOD .. "Успех, |r" .. SB.Theme.MSG_BAD ..
                       "но нести некуда: |r" .. G .. name ..
                       SB.Theme.MSG_BAD .. " выронен.|r"
            end
        end
        print(SB.Theme.MSG_TAG .. "[Spellbreaker]|r: " .. G ..
            "вы обчищаете карманы |r" .. targetName .. G .. " через |r" .. link ..
            G .. ": |r" .. SB.UI.RollLine(roll, mod, total, G) ..
            G .. " против " .. finalThreshold .. ". |r" .. tail)
    end

    if IsInGroup() and SB.Net and SB.Net.SendSteal then
        SB.Net.SendSteal(targetName, spellID, slotLevel, roll, mod, total)
        SB.Logic.BuffAwait(targetName, spellID, threshold, success, Announce)
    else
        -- Вне группы доставить нечего и некому: печатаем по своему
        -- порогу, добычи нет — её выдаёт только клиент жертвы.
        Announce(threshold, success, nil, nil)
    end
end

--- Жертва: считает СВОЙ порог, сама лезет в СВОЮ сумку и отвечает вору.
function SB.Logic.HandleStealReceived(casterName, spellID, slotLevel,
                                      roll, mod, total, sender)
    local spell = SB.Data.Spells[spellID]
    if not spell or not SB.Logic.GetStealKind(spell) then return end

    local G    = SB.Theme.MSG_BODY
    local link = SB.UI.MakeSpellLink(spell)

    -- Та же сверка чисел, что у ПвП-удара и одиночного эффекта:
    -- завышенный итог иначе обчистил бы карман в обход броска.
    local tamperNote
    total, tamperNote = SB.Logic.VerifyIncomingCast(sender or casterName,
        spellID, roll, mod, total, slotLevel)
    if tamperNote then
        print(SB.Theme.MSG_BAD .. "[Spellbreaker]: " .. (sender or casterName or "?") ..
            " — цифры не сходятся: " .. tamperNote .. ".|r")
    end

    -- ЧЕМ СОПРОТИВЛЯЕМСЯ — СПРАШИВАЕМ У СЕБЯ, ровно как у дебаффа
    -- (см. HandleBuffReceived). Заклинание называет стат полем resist,
    -- и читается он тем же DebuffResistStat: эффекта здесь нет, а
    -- правило одно.
    local resistMod = SB.Logic.OwnResistMod(
        SB.Logic.DebuffResistStat(nil, spell))
    local threshold = SB.Logic.EffectThreshold("player", true, false, resistMod)
    local ok = SB.Logic.IsGuaranteed(spell) or (total >= threshold)

    local itemID, count
    if ok and SB.Items and SB.Items.TakeRandomStack then
        itemID, count = SB.Items.TakeRandomStack()
    end

    local tail
    if not ok then
        tail = SB.Theme.MSG_GOOD .. "Вы заметили.|r"
    elseif not itemID then
        tail = SB.Theme.MSG_BAD .. "Обчистили, |r" .. G .. "но взять было нечего.|r"
    else
        local sp = SB.Data.Spells[itemID]
        tail = SB.Theme.MSG_BAD .. "Украдено: |r" .. G ..
               ((sp and sp.name) or itemID) .. " (" .. (count or 1) .. " шт.).|r"
    end
    print(SB.Theme.MSG_TAG .. "[Spellbreaker]|r: " .. G ..
        (casterName or "Кто-то") .. " лезет к вам в карман |r" .. link ..
        G .. ": |r" .. SB.UI.RollLine(roll, mod, total, G) ..
        G .. " против " .. threshold .. ". |r" .. tail)

    if SB.Net and SB.Net.SendStealResult then
        SB.Net.SendStealResult(sender or casterName, spellID, threshold, ok,
                               itemID, count)
    end
end

--- Вор: ответ жертвы. Порог, исход и добыча приезжают вместе.
function SB.Logic.HandleStealResult(targetName, spellID, threshold, ok, itemID, count)
    SB.Logic.HandleBuffResultReceived(targetName, spellID, threshold, ok,
                                      itemID, count)
end

--- Исцеляемая сторона: применяет результат лечения к своему здоровью.
--- @param armorAmount number|nil  единицы брони: заклинание могло чинить
---        доспех вместе с раной или вместо неё (см. spell.repairArmor)
function SB.Logic.HandleHealReceived(healerName, spellID, success, amount, armorAmount)
    if not success then return end

    local PM     = SB.PlayerModel
    local asked  = math.max(0, tonumber(amount) or 0)
    local healed = PM.Heal(asked)

    -- СВОЙ МОДИФИКАТОР ВХОДЯЩЕГО ЛЕЧЕНИЯ ВИДЕН ТОЛЬКО НАМ, и назвать его
    -- в общей строке лекарь не может — он про наши баффы не знает
    -- (см. PM.GetIncomingHealMod). Поэтому поправку объясняем локально, и
    -- только когда она есть: истощение боя лекарь уже вычел сам, а упор в
    -- полное здоровье виден по самой полоске.
    local own = (SB.ActiveEffects and SB.ActiveEffects.GetMod)
        and SB.ActiveEffects.GetMod("healTaken") or 0
    if own ~= 0 and asked > 0 then
        print(SB.Theme.MSG_TAG .. "[Spellbreaker]|r: " .. SB.Theme.MSG_BODY ..
            "получено " .. healed .. " ХП (свои эффекты: " ..
            ((own > 0) and "+" or "") .. own .. ").|r")
    end

    local armor = math.max(0, tonumber(armorAmount) or 0)
    if armor > 0 and SB.Skills and SB.Skills.AdjustArmor then
        local moved = SB.Skills.AdjustArmor(armor)
        if moved > 0 then
            print(SB.Theme.MSG_TAG .. "[Spellbreaker]|r: " .. SB.Theme.MSG_BODY ..
                "доспех починен: +" .. moved .. " брони (" ..
                SB.Skills.GetArmorPoints() .. "/" .. SB.Skills.GetArmorMax() .. ").|r")
        end
    end

    SB.Events.Fire("STATUS_CHANGED")
end

-- ============================================================
-- Подписки на события
-- ============================================================
SB.Events.On("SB_INIT", function()
    -- STATUS_CHANGED → триггер синхронизации с группой и перерисовки UI
    -- (обработчики зарегистрированы в Network.lua и UI/MainFrame.lua)
end)
